pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (1..=15) are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here; this residual becomes dead space for lookahead.
        score += (post_residual as f64) * 0.8;
    }

    // New-bin candidate: only attractive when existing fit is poor (large post_residual
    // or many open bins). Baseline keeps it competitive but not dominant.
    if bin_residual == bin_capacity {
        score = 25.0 + mean_residual * 0.3 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable (min item = 1, but
    // gaps far below typical item sizes waste capacity). Penalize gaps that no realistic
    // item can fill well.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 // tiny gap: essentially dead space
        } else if post_residual < 20 {
            25.0
        } else if post_residual < 30 {
            10.0
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: mild penalty proportional to tightness
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this is a huge item.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let crowded = if mean_residual < item_size as f64 * 0.8 { 1.0 } else { 0.0 };
        score += 40.0 - 12.0 * pressure - 20.0 * crowded;
        // Late in the stream, slightly discourage proliferating bins.
        score += 10.0 * (step_index as f64 / total_items as f64);
    }

    // Open-bin pressure: mildly favor filling existing bins as their count grows.
    score += 0.6 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable dead space (strict dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure from number of open bins: discourage scattering across many bins
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with below-average residual (fill emptier-of-space bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish, but allow it to win when existing
    // bins would leave bad dead space or fits are poor
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative anyway
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers in "useful" classes
    // (multiples of common item sizes / large chunks) and penalize dead zones.
    let cap = bin_capacity as f64;

    // Dead-space penalty: leftovers too small to hold even the smallest item (1..=10)
    // are wasted. Penalize sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class reward: leftover divisible by common granularity (10) is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Class of post_residual via integer division thresholds.
    let pr = post_residual as f64;
    if pr >= cap * 0.5 {
        score -= 12.0; // bin still very roomy: good
    } else if pr >= cap * 0.25 {
        score -= 4.0;
    } else if pr > 0.0 {
        score += 10.0; // small scraps are low value
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.1;
            // harmonic bonus: leftover exactly matches next item size class
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // leftover cannot host next item: penalize if leftover is dead scrap
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 3.0;
            }
        }
    } else {
        // last item: prefer tightest fit overall
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current item is large
    // relative to typical residuals, or when all fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so it wins only for bad fits elsewhere.
        score = cap * 0.75;
        // Opening a new bin is more attractive early (plenty of stream left to fill it)
        // and when many bins are already open with small residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        score -= (open_bins_count as f64) * 0.5;
        if item_size >= 50 {
            score -= 10.0; // big items pair well in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // next item also big: fresh bin can host both
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), unless it's a near-perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are useless dead space.
    // Penalize residuals in the "unusable" band (1..=10) heavily, since items >= 10
    // can never fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // 55..15 penalty, worst at 1
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else {
        // Larger leftovers: mildly prefer tighter fits (already via base post_residual),
        // but reward leftovers that can still host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward if next item fills it (near-)exactly.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 25.0 - 2.5 * gap as f64;
            }
        } else if next_item_size > 0 {
            // Leftover cannot host next item: penalize proportionally to how close it is.
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += 0.8 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual is pure dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 40.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced late in the stream when consolidation
        // matters less, and reduced if many bins are open (cleanup phase).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * (1.0 - progress);
        // If the next item is large and current item is small, a fresh bin can be
        // reserved strategy is bad; penalize opening when item is small.
        if item_size < 40 {
            score += 10.0;
        }
        // If no open bin can fit (fitting_bins_count==0 means only new bin fits),
        // opening is forced: make score clearly lowest.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If this is the only fitting bin besides opening new, prefer existing bin
        // unless existing bins would create dead space (handled above).
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Slight tie-breaker: prefer bins whose residual is close to item (snug fit).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest
    // plausible item (min size 1, but small gaps < ~15 are hard to fill).
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    // Perfect fit: full reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted space for next arrival).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward a bin that can also host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.2;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; with few bins, new bins are cheap.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when
    // existing bins have genuinely bad fits, scaled by how bad fits are.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Mild stream progression: late in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual classes are good fits.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Reward near-perfect fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Modulo arithmetic: residuals divisible by common item granularities (10s)
    // remain reusable; penalize awkward odd residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 {
        score -= 10.0;
    } else {
        score += 8.0; // awkward dead space
    }

    // Fractional thresholds on capacity fractions.
    if frac < 0.1 {
        score -= 40.0;
    } else if frac < 0.2 {
        score -= 15.0;
    } else if frac > 0.6 {
        score += 40.0; // leaving more than 60% empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 60.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here regardless; slight bonus for larger residual
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is large.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 150.0 - pressure * 5.0;
        if bin_residual - item_size >= 70 {
            score -= 100.0; // big item into fresh bin is fine
        }
    }

    // Progress-based scaling: early on, be frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Small tie-breaker toward tighter bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless it's genuinely better
    // than dumping into a bin that would leave a tiny dead gap.
    if bin_residual == bin_capacity {
        score = 150.0 + open_bins_count as f64;
        // Allow new bin early in stream or when item is huge relative to capacity.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.05 {
            score -= 120.0;
        }
        if item_size > 80 {
            score -= 60.0;
        }
        // If the item would leave a small dead gap in every fitting bin,
        // opening a fresh bin is competitive.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count >= 1 {
            score -= 80.0;
        }
    }

    // Lookahead: if the next item could use this bin's post residual exactly,
    // reward leaving that gap; if the gap is unusable for next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild normalization toward mean residual state.
    score -= 0.3 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 420.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 150.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 14 && !next_consumes {
        score += 30.0 + (14 - post_residual) as f64 * 7.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 19.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 14.0 + 0.4 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 9.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 7.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 210.0;
        } else {
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 12.0;
        }
        if slack > 0.0 && slack < 10.0 && slack < item_size.min(15) as f64 {
            score += 12.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 12.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 7.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 23.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 9.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 11.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.35 + 16.0 * progress + 3.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 38.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 22.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 26.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 14.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 22.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 16.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 8.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 9.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 8.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 9.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 12.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact-fill lookahead reward
    if post_residual == 0 {
        score -= 480.0;
    }
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
            if post_residual >= next_item_size * 2 {
                score -= 30.0 * (1.0 - progress);
            }
            if slack > 0.0 && slack < 4.0 {
                score -= 16.0;
            }
        }
    }

    // Penalize stranded gaps the next item cannot use
    if post_residual > 0 && !next_consumes {
        let stranded = post_residual as f64 / cap;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 12 {
            score += 30.0 + (12 - post_residual) as f64 * 5.0;
        }
        if post_residual < next_item_size && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 12.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Last-resort fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.3 + 16.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Dead-space penalties for unusable leftover
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.6 && !next_consumes {
            score += 10.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if post_residual == item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    score += post_residual as f64 * 0.4 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in small residue classes are "dead space".
    // Class residuals into deciles of capacity (integer division).
    let post_class = post_residual / (bin_capacity / 10).max(1);
    let item_class = item_size / (bin_capacity / 10).max(1);
    let next_class = next_item_size / (bin_capacity / 10).max(1);

    // Penalize small-but-nonzero dead space quadratically.
    if post_residual > 0 {
        let dead = (bin_capacity as f64 / (post_residual as f64 + 1.0)).ln();
        score += 6.0 * dead * dead;
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Harmonic coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 18.0;
        }
        // Reward when next item's class is small enough to nest in this class.
        if next_class <= post_class {
            score -= 4.0 * (post_class - next_class) as f64;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting a good bin now.
        score += 3.0;
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins with low residual relative to mean (tighten tight bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Modulo-threshold logic: residual congruent to small classes (1..=5 mod 20) is nearly dead.
    let r = post_residual % 20;
    if r >= 1 && r <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Early stream: encourage opening fewer bins; late stream: pack tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 15.0 + 10.0 * (1.0 - progress);
        score += base;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    // Item class harmony: large items prefer large-residual bins.
    score -= 0.3 * item_class as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: reward when the next item fits snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: two items seal the bin exactly.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward more when the leftover after it is small.
            let double_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * double_left;
        } else {
            // Next item won't fit in this bin's remainder: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.30 * gap;
        }
    }

    // Prefer bins whose residual is already below average (tight bins close out fast).
    score += 0.40 * (mean_residual - post_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize large dead space creation relative to typical item sizes (min 1, max 100).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 10.0; // small scraps still usable
        } else if dead > 70.0 {
            score += 0.15 * (dead - 70.0); // large unusable-looking gap
        }
    } else {
        score -= 20.0; // perfectly closed bin
    }

    // Early in the stream, be more conservative about filling bins tightly;
    // later, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score = bin_capacity as f64 - pressure - 10.0 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: opening a new bin is only attractive when the current bin
    // would leave a large, awkward gap and the lookahead item needs fresh space.
    if bin_residual == bin_capacity {
        score = 200.0
            - 40.0 * progress
            - (if next_item_size > 0 && next_item_size > bin_residual - item_size { 30.0 } else { 0.0 })
            - (if fitting_bins_count == 0 { 100.0 } else { 0.0 });
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 150.0;
            // extra reward for chained near-perfect fit
            let chain = (post_residual - next_item_size) as f64;
            score -= (bin_capacity as f64 - chain).max(0.0) * 0.5;
        } else {
            // dead space penalty scaled by how much next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
        }
    }

    // Penalize small unusable post-residual (dead space) but not perfect fits
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fits poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // open new bin only if best alternative leaves large dead space
        if poor_fit < 25.0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 500.0; // keep using open bins when they chain well
        } else {
            score += 120.0; // mild default penalty for opening new bins
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect match for next item: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits with some slack left: mild reward scaled by tightness
            let slack = post - nxt;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportionally to leftover dead space
            score += 12.0 * (nxt - post) / 100.0;
        }
    }

    // Penalize creating unusable tiny residuals (< 10, min item size)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual across open bins
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        let poor_open = mean_residual < item_size as f64 * 0.5;
        score += if poor_open { 5.0 } else { 40.0 };
    }

    // Late in stream: favor closing bins tightly (small post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Prefer bins with many open alternatives less (avoid fragmenting)
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 300.0;
    }
    // Near-perfect fit: leave only tiny slivers, which are easy to fill later.
    if post_residual > 0 && post_residual <= 4 {
        score -= 120.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 15 && !next_consumes {
        score += (15 - post_residual) as f64 * 9.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for next arrival).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 18.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        // Exact lookahead fit is extremely valuable.
        if next_item_size == post_residual {
            score -= 150.0;
        }
        // Two-item lookahead: bin can host next item twice.
        if post_residual >= next_item_size * 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // Post-fit slack small enough that only tiny items fit: mild penalty.
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < 8 && slack < item_size.min(15) {
            score += 12.0;
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 22.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize so new bins open only when fits are bad,
    // scaled by mean residual (large mean residual = plenty of room elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.35 + 15.0 * progress;
        // Early large items: opening a fresh bin is fine.
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // If the fresh bin can host both this and the next item, it is attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose post-fit residual stays above the mean (still usable).
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 6.0 * (1.0 - progress);
        }
        // Post-fit residual barely above next item: great chaining opportunity.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 14.0;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // If mean residual is small (bins nearly full), squeeze into existing bins.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = post_residual % 10;
    // Dead space penalty: residuals < 10 are nearly unusable (min item = 1, but small)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic bonus: post_residual exactly divisible into capacity fractions
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 15.0;
    }

    // Class-based coupling: residue class 0 (multiples of 10) are friendly
    if class == 0 {
        score -= 8.0;
    } else if class >= 5 {
        score += 4.0;
    } else {
        score += 6.0;
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            score -= 20.0 - (nxt_class as f64) * 1.5;
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled by wasted fraction
            let waste = next_item_size as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 40.0 + 60.0 * frag;
        if post_residual == 0 { score -= 200.0; }
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Progress-based mild tightening: later in stream, prefer tighter packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space: penalize proportionally to how close it is to being wasted.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 12.0 + waste * 0.8;
        } else {
            // Post-residual can host the next item: strong reward.
            score -= 15.0;
            // Extra reward for a tight-but-usable fit (next item nearly fills gap).
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / 100.0;
            score -= snug * 8.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Penalize very small leftover gaps that no item (min size 1..10 range) may use well.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    if bin_residual != bin_capacity {
        score -= 3.0 / (1.0 + pressure * 0.2);
    } else {
        // New-bin candidate: acceptable only if existing bins fit poorly.
        let poor_fits = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 18.0 * poor_fits + (item_size as f64) * 0.05;
        // Mildly cheaper to open a new bin early in the stream.
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer bins whose residual is below mean (consolidate fuller bins).
    let r = post_residual as f64;
    if r > mean_residual {
        score += (r - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - r) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer minimal post-residual, with a non-linear (quadratic) penalty
    // on wasted space that grows with stream progress (late in the stream,
    // dead space is more costly since fewer items remain to fill it).
    let mut score = pr + 30.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: when post_residual is small relative to capacity,
    // subtract a smooth non-linear bonus.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead coupling: if the next item could exactly fill the post-residual,
    // reward strongly (smooth Gaussian-like coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap * gap / 200.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // Discourage spreading across many open bins when mean residual is large:
    // prefer bins below the mean residual (tighter bins) via smooth coupling.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // Mild penalty for opening a brand-new empty bin when other bins fit,
    // scaled by how much of the item fills the new bin.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * pr_norm;
    }

    score
}

