        score += 60.0;
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild penalty for creating small unusable gaps (< typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is the core packing signal.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize wasting a large residual on a small item (dead-space creation).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * waste * waste * waste;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if it cannot use the post-residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack);
        } else {
            score += 3.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins (favor filling existing bins over opening new ones).
    let pressure = mean_residual / bin_capacity as f64;
    let load_factor = open_bins_count as f64 / (total_items.max(1) as f64);
    score -= 5.0 * pressure * (1.0 - load_factor.min(1.0));

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * fit_ratio;

    // New-bin candidate shaping: an empty bin gets a neutral-ish base but must
    // lose only when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear waste penalty: dead space hurts more when small and late in stream
    score += 4.0 * (1.0 - norm_pr).powi(2) * (1.0 + progress);

    // Smooth coupling: tight fit rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness.powi(3) * (0.5 + progress);

    // Penalize residuals that no plausible future item can use (smooth barrier)
    let usable = (pr / (next_item_size.max(1) as f64)).min(4.0);
    score += 2.0 * (-usable).exp();

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 3.0 * (1.0 - fits_next) * (1.0 - fits_next.abs());
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (pack tight bins first), smooth coupling
    score += 1.5 * (mean_residual - bin_residual as f64) / cap * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 6.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer-division bands of capacity/4 (quartile classes).
    let q = bin_capacity / 4; // 25
    let post = post_residual;
    let class = post / q; // 0..4 harmonic class of leftover

    // Reward tight fits: post_residual in the lowest classes is good.
    let class_reward: [f64; 5] = [14.0, 8.0, 2.0, -4.0, -10.0];
    score -= class_reward[class.min(4) as usize];

    // Exact-fill / near-exact-fill bonus via modulo arithmetic.
    if post == 0 {
        score -= 30.0;
    } else if post <= 5 {
        score -= 18.0;
    }

    // Dead-space penalty: leftover too small for typical items (1..100 range,
    // but small leftovers < 10 are nearly useless).
    if post > 0 && post < 10 {
        score += 22.0;
    }

    // Harmonic pairing with the lookahead item: if next item fits exactly
    // into post_residual, strong reward; if next item would leave a bad
    // modulo class, penalize.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            let next_post = post - next_item_size;
            // harmonic class of the double-leftover
            let nc = next_post / q;
            let next_reward: [f64; 5] = [10.0, 5.0, 0.0, -3.0, -7.0];
            score -= next_reward[nc.min(4) as usize];
            if next_post == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot fit here: mild penalty, worse if this was
            // the last-chance bin
            score += 6.0;
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post < bin_residual {
        score -= 16.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current item is large or fits poorly anywhere.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its "post_residual" = capacity - item
        let fresh_class = post / q;
        let fresh_penalty: [f64; 5] = [0.0, 6.0, 14.0, 22.0, 30.0];
        score += fresh_penalty[fresh_class.min(4) as usize];
        // if item is large (> half capacity), a fresh bin is natural
        if item_size * 2 > bin_capacity {
            score -= 8.0;
        }
        // if next item is also large, fresh bin keeps pairing options open
        if next_item_size > 0 && next_item_size * 2 > bin_capacity {
            score -= 4.0;
        }
        // many open bins: prefer consolidation into existing bins
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Prefer bins whose residual is close to the item (tightness measure)
    // via integer-division ratio of residual to item.
    if item_size > 0 {
        let ratio = bin_residual / item_size; // 1 = perfect, larger = loose
        score += match ratio {
            1 => -10.0,
            2 => -3.0,
            3 => 2.0,
            _ => 5.0,
        };
    }

    // Stream progression: early on, be more willing to open bins (favor
    // spread); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (progress - 0.5) * 6.0;

    // Mean-residual coupling: if this bin's residual deviates favorably
    // (smaller than mean), it is a good consolidation target.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.08;
    }

    // Small harmonic jitter on post_residual modulo classes to break ties
    // deterministically without randomness.
    score += ((post % 7) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead". Penalize them hard.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // unreachable guard, keeps types happy
    }
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits (post_residual close to 0).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual is "consumed" proportionally well.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins below mean residual (denser bins),
    // penalize placing into bins that are already emptier than average.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item can't use the leftover -> dead space risk
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin attractive only when the fit
    // into existing bins is poor (large post_residual relative to capacity)
    // or when the item is large and no tight option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 0.5;
        // Large items justify fresh bins more (they would leave big
        // unusable gaps in partially filled bins anyway).
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 20.0;
        // If the item would leave a nearly empty unusable gap elsewhere,
        // a new bin is fine; if it fits tightly somewhere, new bin is bad.
        if post_residual as f64 <= bin_capacity as f64 * 0.15 {
            new_bin_score += 40.0;
        }
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this is a chain match — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits, leaving a new residual; reward tight chains.
            let chain_residual = post_residual - next_item_size;
            score -= 200.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
            // Double-chain bonus: residual after chain still usable for typical sizes.
            if chain_residual >= 10 {
                score -= 50.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the gap,
            // since this bin will hold dead space for at least one step.
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // remaining space stays close to (but not far above) the fleet mean,
    // keeping residuals homogeneous and packable.
    let mean_post = mean_residual - item_size as f64;
    let deviation = (post_residual as f64 - mean_post).abs();
    score += 0.3 * deviation;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual
    // of this bin. Penalize the new bin unless the current bin's post
    // residual is very large (poor fit) or the item is a perfect new-bin fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // If the item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 120.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // If next item fits in the fresh bin's residual after this item,
        // opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0;
        }
    } else {
        // Existing bin: reward usage, especially early/mid stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
        // Consolidation: fewer open bins is better.
        score += 2.0 * open_bins_count as f64;
    }

    // Penalize leaving residuals that are too small to be useful
    // (unusable dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by this placement
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward residuals: dead space that likely cannot
    // be filled by future items (residuals smaller than typical items)
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 20.0 * dead;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly reward this placement (perfect pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with below-average residual (concentrate filling)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream: be more willing to open new bins to create
    // diverse residual pools; late: consolidate into existing bins
    score += progress * 8.0;

    // Penalize opening a brand-new bin when good alternatives exist,
    // unless few bins are open (early stream) or fit is very tight
    if bin_residual == bin_capacity {
        let open_bias = 12.0 / (1.0 + open_bins_count as f64);
        score += 25.0 - open_bias;
        if fit_ratio > 0.7 {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is close to item size
    // (best-fit flavor) via smooth kernel
    let gap = (bin_residual - item_size) as f64;
    score += 0.1 * gap * gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, squeeze residuals harder (dead space costs more)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 8.0 * norm_pr * norm_pr * cap;

    // Early in the stream, mildly favor spreading across bins (lower priority on tight fits)
    score -= (1.0 - late) * 4.0 * norm_pr;

    // Reward filling a bin nearly completely (smooth term)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + late);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let fit = fitting_bins_count as f64;
        score += 10.0 + 2.0 * open - 5.0 * fit;
        // If next item could combine with current item in a fresh bin, soften penalty
        let next = next_item_size as f64;
        if next > 0.0 && next + item_size as f64 <= cap {
            score -= 4.0;
        }
    }

    // Lookahead: favor residual that can still host the next item (smooth)
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            let slack = (pr - next) / cap;
            score -= 3.0 * slack * (1.0 - slack);
        } else {
            score += 2.0 * (next - pr) / cap;
        }
    }

    // Deviation from mean residual: prefer bins whose resulting residual is near the mean
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as u32;
    let quarter = cap / 4;
    let eighth = cap / 8;
    let post = post_residual;

    // Reward post_residuals that fall into "usable" harmonic classes:
    // multiples of 10 or 20 (typical item sizes) are highly reusable.
    if post > 0 {
        if post % 10 == 0 {
            score -= 12.0;
        } else if post % 5 == 0 {
            score -= 5.0;
        }
        // Integer-division thresholds: which harmonic band does post_residual sit in?
        let band = post / eighth; // 0..=8
        match band {
            0 => score -= 20.0,          // near-perfect fill (0..12)
            1 => score -= 14.0,          // 12..25
            2 => score -= 8.0,           // 25..37
            3 => score -= 4.0,           // 37..50
            4 => score += 2.0,           // 50..62: half-empty, mediocre
            5 => score += 6.0,           // 62..75
            6 => score += 10.0,          // 75..87
            7 => score += 16.0,          // 87..100: mostly empty, wasteful use
            _ => score += 20.0,
        }
    }

    // Coupling with lookahead: does post_residual leave room for next item?
    if next_item_size > 0 && post >= next_item_size {
        // Harmonic match: post_residual % next_item_size small => next item fits snugly.
        let r = post % next_item_size;
        if r == 0 {
            score -= 15.0;
        } else if r <= 5 {
            score -= 7.0;
        } else {
            score += (r as f64) * 0.15;
        }
    } else if next_item_size > 0 {
        // Dead space for the next item: penalize proportional to wasted gap.
        score += (next_item_size - post) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: give it a moderate default score so it wins only
    // when all open bins have bad (high) harmonic scores.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.05 * (open_bins_count as f64);
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual across open bins is large, discourage new bin.
        score += mean_residual * 0.1;
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual < item_size.min(80) || post_residual < 10;
        if dead {
            score += 40.0 + 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // item is large or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 10.0 + 0.3 * item_size as f64;
        score -= new_bin_bonus;
        // Penalize opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins near the mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            // Reward proportional to how tightly the next item chains
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - chain_slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residuals that are too small to be useful later
        let deadness = (next_item_size - post_residual) as f64;
        score += 15.0 * (deadness / 50.0).min(1.0);
    }

    // Compare post_residual against mean residual: prefer bins that become
    // closer to the (lower) average residual, i.e. balance the load
    let mean_post = mean_residual - item_size as f64;
    score += 0.5 * (post_residual as f64 - mean_post).abs();

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize spreading into many bins when few remain open (encourage consolidation)
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a good
    // future chain or no good fit exists among open bins
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early stream: be slightly more willing to open bins / keep options open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 5.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item exactly or nearly fits the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally to wasted space.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0 + 0.3 * (bin_residual - post_residual) as f64;
    }

    // Many open bins: encourage consolidation into existing bins rather than opening new ones.
    score += 0.4 * open_bins_count as f64;

    // Prefer bins whose residual is close to (below) the mean residual — pack fuller bins first.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Time horizon: early in the stream be conservative (leave room), late in stream pack aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tightness;
    score += 5.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with polynomial shaping
    let mut score = pr;

    // Smooth polynomial interaction: as stream progresses, weight residual more strongly
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_poly * norm_pr * norm_pr * cap * 0.5;

    // Penalize residuals that are large relative to mean residual (wasted space)
    let mean_norm = mean_residual / cap;
    score += (norm_pr - mean_norm).abs() * cap * (0.3 + 0.4 * progress);

    // Reward near-perfect fits: cubic dip near small post_residual
    score -= (1.0 - norm_pr).powi(3) * item_size as f64 * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= cap * 0.8 * (0.5 + prog_poly);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= next_item_size as f64 * 0.4 * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here; slight penalty for fragmenting
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // New-bin candidate: make empty bin mildly attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - norm_pr).abs();
        score = cap * (0.6 - 0.3 * progress) + fragmentation * cap * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover space: small dead space classes are penalized
    // less than mid-range leftovers that are hard to fill.
    let cls = match post_residual {
        0..=10 => 0.0,
        11..=25 => 1.0,
        26..=49 => 3.0,
        _ => 2.0,
