    score += cls * 8.0;

    // Exact match with lookahead item: strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Lookahead fits into the post residual: reward proportionally.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Lookahead cannot use the leftover: penalize large unusable leftovers.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative
    // to capacity or mean residual is large (open bins are mostly full).
    if bin_residual == bin_capacity {
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0; // big items pair better in fresh bins
        }
        if mean_residual > 40.0 && progress > 0.5 {
            score -= 15.0;
        }
    }

    // Prefer bins tighter than the average: keeps large residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Mild pressure to close bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

