        if post_residual < item_size.min(80) {
            score += 35.0 + 0.4 * post_residual as f64;
        }
    }

    // Last-chance bonus: only fitting open bin -> strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: base cost, discounted late in the stream or
    // when open bins are crowded; valuable when next item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 35.0 * (1.0 - progress);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
