        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 12.0;
        }
        if item_size > 70 {
            score -= 8.0 + 0.2 * item_size as f64;
        }
    }

    // Lookahead chaining: perfect 2-step fill is gold; compatible residual rewarded;
    // stranded lookahead penalized proportionally to the waste.
    if next_item_size > 0 {
        if next_item_size == post_residual && post_residual > 0 {
            score -= 350.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

