pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fits are golden.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Awkward fragments: residuals < 10 that the next item cannot consume.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 50.0 + 0.7 * post_residual as f64;
    }

    // Residual smaller than the item itself (and small in absolute terms): dead space.
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Reward retaining slots of usable capacity.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead: chain fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 420.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 60.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 50.0;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            if waste > bin_residual as f64 {
                score += 25.0;
            }
        }
    }

    // Small sliver penalty, softened when the next item can consume it.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.5 - future_help);
    }

    // Prefer bins whose residual is above the mean (keeps a spread of useful bins).
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

