pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item
    // (min size ~1, but tiny gaps < 8 are statistically hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    }
    // Medium-risk gaps: penalize proportionally with a bump for odd sizes.
    if post_residual >= 8 && post_residual < 20 {
        score += 12.0 + (post_residual % 2) as f64 * 4.0;
    }

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size as f64 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is acceptable only when alternatives are scarce or fit would be terrible.
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { 15.0 + fitting_bins_count as f64 * 5.0 };
        score += 25.0 + scarcity + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer closing out existing bins rather than opening more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Mild reward for using existing bins, stronger when this is the last fitting bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
