    // Compare residual against mean residual: prefer filling below-average-residual bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Discourage opening new bins early in the stream when fits exist
    if bin_residual == bin_capacity {
        score += 80.0;
        // but allow new bin if existing residuals are all poor fits for item or next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild late-stream pressure to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

