    }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 420.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 65.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 35.0 ; }
            if post_residual >= next_item_size * 2 { score -= 55.0 ; }
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 0.5 * waste ;
            if waste > bin_residual as f64 { score += 25.0 ; }
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual).abs () ;
            score -= 12.0 * (1.0 - dev / bin_capacity as f64) ;
        }
    }
    // dead-space ratio lookahead: avoid bins that will end up mostly empty
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
