    }
    score += (mean_residual - bin_residual as f64) * 0.08 ;
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, quadratically (dead space is worse than small slack)
    let mut score = pr as f64 * (1.0 + 0.5 * x * x);

    // Smooth interaction: as stream progresses, prefer tighter fits more strongly
    score += 30.0 * progress * x * x;

    // Reward near-perfect fits with a smooth bump around x ~ 0
    score -= 20.0 * (-x * 8.0).exp() * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x).max(0.0);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth ratio)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_ratio = if pr > 0.0 { (nx * cap / pr).min(1.0) } else { 0.0 };
        score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress);
        // Penalize if post residual leaves awkward gap next item can't use
        score += 10.0 * (1.0 - fit_ratio) * x * (1.0 - progress);
    }

    // Mild pressure to consolidate: many open bins with high mean residual -> prefer filling
    let consolidation = (open_bins_count as f64).ln() * (mean_residual / cap);
    score += 3.0 * consolidation * x;

    // Penalize opening new bins late in the stream unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 * progress - 10.0 * (1.0 - progress) * (1.0 - x);
    }

    score
}

