pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, 1.0 = perfect fill
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: bins whose residual lies in a "useful"
    // residue class (divisible into common small item sizes) are more valuable.
    let post = post_residual;
    if post > 0 {
        // Reward residuals that are multiples of common item granularities.
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if post % m == 0 {
                harmony += 6.0;
            }
        }
        // Exact zero-waste potential: residual exactly matches next item.
        if next_item_size > 0 && next_item_size == post {
            harmony += 30.0;
        } else if next_item_size > 0 && post >= next_item_size {
            harmony += 8.0;
        }
        // Penalize dead space: residuals too small for the minimum item (1)
        // matter less, but residuals in awkward ranges (1..10) are dead weight
        // under the 10..80 regime; under 1..100 they are mildly bad.
        if post < 10 {
            harmony -= 12.0 * (10.0 - pr) / 10.0;
        }
        score -= harmony;
    } else {
        // Perfect fill: huge reward.
        score -= 60.0;
    }

    // Integer-division threshold on next_item_size: large lookahead items
    // deserve preserved large residuals.
    if next_item_size > 0 {
        let need = next_item_size as f64;
        if pr < need {
            // This bin can't host the next item; penalize proportionally to
            // how badly we fragment relative to next item's class.
            let class = (need / 25.0).floor(); // 0..4 harmonic class
            score += 5.0 * class * (need - pr) / cap;
        } else {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well. Penalize the fresh bin mildly so tight fits beat it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if nothing else fits well (high mean residual scatter), fresh
        // bin is fine: relax penalty when open bins are already fragmented.
        if open_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // Pairing large item with fresh bin keeps big residual for next.
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    // (fewer bins matter more than balance).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Mild tie-break toward bins below mean residual (use small leftovers first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Dead space is "unusable" if smaller than the minimum plausible item (assume ~10),
        // or smaller than the lookahead item when it can't fit.
        if dead < 10.0 {
            score += (10.0 - dead) * 12.0; // small gap = pure waste, heavy penalty
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            score += (next_item_size as f64 - dead) * 4.0; // lookahead can't use leftover
        } else {
            score -= dead * 0.5; // large usable leftover is mildly good
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New-bin candidate: penalize opening a new bin unless current fit is terrible.
        score += 15.0 + pressure * 0.3;
    }

    // Mean-residual coupling: if the fleet average residual is large, favor using it up.
    if bin_residual < bin_capacity && (mean_residual - post_residual as f64) > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Lookahead synergy: reward if next item exactly fills the post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Strong rewards for perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Penalize dead slivers that no typical item will fill.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward roomy residuals (usable space) in coarse slots.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead: exact pairing is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Dead-sliver control scaled by lookahead usefulness.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance: strongly prefer the only fitting open bin over a new bin.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // --- New-bin candidate gating ---
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }

        // Penalize residuals neither current nor next item can consume.
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
        }

        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }

        // Penalize small residuals no future item can plausibly fill.
        let remaining = if total_items > step_index { total_items - step_index } else { 0 };
        let future_density = remaining as f64 / total_items.max(1) as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }

        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }

        if bin_residual == bin_capacity && fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }

        // Exact two-item fill lookahead.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }

        // Keep new bins closed when slack exists elsewhere.
        if bin_residual == bin_capacity && mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }

        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

