        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress) ; }
    }

    score += (mean_residual - bin_residual as f64) * 0.08 ;
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0 ;
    score
}

