pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = if total_items > step_index { (total_items - step_index) as f64 / total_items as f64 } else { 0.0 };
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    if !is_new_bin {
        // Exact / near-exact fill rewards.
        if post_residual == 0 {
            score -= 530.0;
        } else if post_residual <= 4 {
            score -= 235.0;
        }

        // Dead slivers: leftovers too small to be useful.
        if post_residual > 0 && post_residual < 10 && !next_consumes {
            score += 55.0 + 0.75 * post_residual as f64;
        }
        if post_residual > 0 && post_residual < item_size.min(80) {
            score += 42.0 + 0.5 * post_residual as f64;
        }
        if post_residual > 0 && post_residual < 20 {
            let dead_sliver = 20.0 - post_residual as f64;
            let future_help = if next_consumes { 1.0 } else { 0.0 };
            score += dead_sliver * (1.55 - future_help);
        }

        // Usable-slot reward.
        let slots = post_residual / 10;
        score -= 5.0 * slots as f64;

        // Lookahead on the next item.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 450.0;
            } else if next_consumes {
                let slack = (post_residual - next_item_size) as f64;
                score -= 120.0 * (1.0 - slack / bin_capacity as f64);
                if slack > 0.0 && slack <= 7.0 {
                    score -= 72.0;
                }
                if slack > 0.0 && slack < 12.0 {
                    score += 38.0;
                }
                if post_residual >= next_item_size * 2 {
                    score -= 60.0;
                }
                if post_residual >= next_item_size && post_residual - next_item_size < 3 {
                    score -= 9.0;
                }
                if next_consumes && post_residual >= next_item_size * 2 {
                    score -= 8.0 * (1.0 - progress);
                }
                if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
                    score -= 4.0 * (1.0 - progress);
                }
                if next_consumes && post_residual - next_item_size <= 1 {
                    score -= 5.0 * future_density;
                }
            } else {
                let waste = (next_item_size - post_residual) as f64;
                score += 0.55 * waste;
                if waste > bin_residual as f64 {
                    score += 28.0;
                }
                if post_residual > 0 && next_item_size <= bin_residual {
                    score += 22.0 * (1.0 - progress);
                }
                if post_residual > 0 && post_residual < 30 && next_item_size > post_residual {
                    score += 12.0 * (1.0 - progress);
                }
            }
        }

        // Density coupling with mean residual.
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.8;
        } else {
            score -= (mean_residual - bin_residual as f64) * 0.4;
        }

        // Fill ratio reward.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;

        // Only-fitting-bin consolidation.
        if fitting_bins_count <= 2 && bin_residual < bin_capacity {
            score -= 17.0;
        }

        // Dead-space ratio pressure early in the stream.
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }

        // Stranded residual: cannot host the next item.
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
            if next_item_size > 0 && post_residual > mean_residual * 0.5 {
                score += 6.0 * (1.0 - progress) * stranded;
            }
        }

        // Multiples of item size / 10 in dense regimes.
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }

        // Single-fitting-bin lookahead rescue.
        if fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
    } else {
        // New-bin candidate: cost grows with fitting alternatives and progress.
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
    }

