            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score -= 12.0 * (1.0 - dev / bin_capacity as f64) ;
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity { score -= 17.0 ; }

    // new-bin candidate handling
