    score -= 5.0 * slots as f64 ;
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 460.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 72.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 38.0 ; }
            if post_residual >= next_item_size * 2 { score -= 60.0 * (1.0 - progress) ; }
