pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the leftover space exactly fits the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: moderate reward scaled by tightness of the double fit.
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += 8.0 + 0.3 * gap as f64;
        }
    }

    // Reward tight fits of the current item (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Compare against mean residual: placing into a bin with above-average residual
    // balances the pool of open bins.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless current fit is terrible
    // (large post_residual dead space) or it's a perfect fresh start for a big item.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 5.0 + 0.2 * item_size as f64;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= new_bin_bonus; // item is small: fresh bin may be better
        } else {
            score += 12.0; // prefer existing bins for normal fits
        }
    }

    // Slight late-stream pressure to consolidate into fewer bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = if total_items > step_index { total_items - step_index } else { 0 };
    let future_density = remaining as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;
    let stranded = post_residual as f64 / bin_capacity as f64;

    // core residual shaping (parent)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 18.0;
    if post_residual == 0 { score -= 530.0; }
    else if post_residual <= 4 { score -= 235.0; }
    if post_residual > 0 && post_residual < 10 && !next_consumes { score += 55.0 + 0.75 * post_residual as f64; }
    if post_residual > 0 && post_residual < item_size.min(80) { score += 42.0 + 0.5 * post_residual as f64; }
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // lookahead (parent, strengthened)
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 450.0; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0 * (1.0 - 0.5 * progress); }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
        // prefer residuals close to mean residual
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / bin_capacity as f64);
        }
    }

    score += (mean_residual - bin_residual as f64) * 0.09;

    // sliver dead-space penalty (borrowed from best)
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
