        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
    }

    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on residual waste, scaled by item size.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;
    score -= 0.25 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 3.0;
        }
        // Bonus if post_residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: when many bins are open, discourage opening new bins
    // (consolidate); when few bins, be more willing to spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.02 * open_bins_count as f64 * progress;

    // Mean residual coupling: penalize bins far above/below mean residual
    // to keep residuals homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: neutral base, but make it attractive only when
    // no open bin offers a good fit (post_residual small) or item is large.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * item_size as f64 - 0.1 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

