pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, tight fits (small post_residual) matter most; late in the
    // stream, wasting capacity is increasingly penalized super-linearly.
    let norm_post = post / cap; // in [0,1]
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * progress * progress;
    score += 8.0 * poly;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tightness = 1.0 - norm_post;
    score -= 4.0 * tightness * tightness;

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 6.0 * last_chance * (1.0 - norm_post);

    // Lookahead coupling: penalize leaving post_residual that can't fit next item,
    // reward when post_residual exactly accommodates the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (post - n) / cap;
        score += 3.0 * diff * diff;           // penalize mismatch either way
        score -= 2.0 * (-diff * diff * 200.0).exp(); // reward near-exact accommodation
    }

    // Contextual coupling with mean residual and bin count, smooth in progress.
    let mean_gap = (mean_residual - post) / cap;
    score += 2.0 * mean_gap * mean_gap * (0.5 + progress);
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 0.5;

    score
}

