pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Items are >= 1, but typical small items cluster; classify leftover by
    // divisibility / integer-division thresholds on capacity fractions.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: leftovers that no common item can use.
    if pr > 0 && pr < 10 {
        score += 60.0; // nearly unusable sliver
    }
    // Harmonic classes: leftover exactly divisible by common item sizes is reusable.
    let harmonics: [u32; 6] = [10, 20, 25, 50, 100, 5];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if pr % h == 0 && pr > 0 {
            harmonic_bonus += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Integer-division class of post_residual (how many "medium" slots fit).
    let slots = pr / 30; // medium item proxy
    score -= slots as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= pr {
        let next_class = next_item_size / 10;
        score -= 10.0 + next_class as f64 * 2.0;
        if next_item_size == pr {
            score -= 35.0; // perfect two-item closure
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; leftover risks becoming dead space.
        score += (next_item_size - pr) as f64 * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when residual
    // is small (poor fit) or item is huge relative to residual.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // New bin baseline: its post_residual is large, which already scores high.
        // Reward new bin when current item is large (better to start fresh).
        score -= fill_frac * 40.0;
        // Penalize new-bin opening mid-stream when many bins are open (fragmentation).
        score += open_bins_count as f64 * 1.5;
        // Early stream: opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Tight fit reward: small post_residual relative to item means good packing.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // already "used up" — good to fill it further.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    // Threshold classes on post_residual via integer division by capacity fractions.
    let class = pr / quarter;
    score += match class {
        0 => -5.0,  // tiny leftover, well packed
        1 => 0.0,
        2 => 3.0,   // half-empty bin, moderate
        _ => 6.0,   // mostly empty, wasteful unless new bin
    };

    // Slight tie-break toward earlier bins via step-independent small term.
    score += (pr % 7) as f64 * 0.1;

    score
}

