            // next item would not fit here: penalize proportional to overshoot
            score += 10.0 * (diff / bin_capacity as f64);
        }
        // If after placing next item residual would be tiny, extra reward
        let after_next = post_residual as f64 - nxt;
        if after_next >= 0.0 && after_next <= 5.0 {
            score -= 15.0;
        }
    } else {
        // Last item: just prefer minimal waste
        score -= 5.0;
    }

