        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if no open bin fits well, allow it
        if post_residual as f64 > mean_residual && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

