        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // Post-residual too small for the next item: mild penalty unless it's a near-perfect fit now.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
