    // New-bin candidate handling: opening a new bin is only attractive when the current
    // item is large relative to the residual (poor fit into any open bin) or when open
    // bins are already quite full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
