pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let t = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let n = next_item_size as f64;
    let is_new = (bin_residual == bin_capacity) as f64;

    // base: prefer small post-residual (tight fit)
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let x = pr / c;
    score += 40.0 * (x * x) * (1.0 - t) + 15.0 * (x * x * x) * t;

    // waste penalty relative to mean residual, modulated non-linearly by progress
    let m = mean_residual / c;
    score += 20.0 * (x - m) * (x - m) * (0.5 + 0.5 * t);

    // lookahead: reward leaving room for the next item (smooth coupling)
    let fits_next = (n > 0.0 && n <= pr) as f64;
    score -= 12.0 * fits_next * (1.0 - (pr - n) / c).max(0.0);
    // penalize wasting a bin that could fit next item almost exactly
    let near = ((pr - n) as f64).abs() / c;
    score -= 8.0 * fits_next * (1.0 - near) * t;

    // last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 30.0 + 20.0 * t;
    }

    // new-bin candidate: penalize early, allow late in stream when existing fits are poor
    score += is_new * (35.0 - 25.0 * t * (1.0 - (x * (1.0 - m)).min(1.0)));

    // mild preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln() * x * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small harmonics) are rewarded.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: post_residual == 0 -> perfect fit, huge reward.
    if post == 0 {
        score -= 1000.0;
    }

    // Class B: post_residual in low harmonic band (<= 10): nearly perfect.
    if post > 0 && post <= 10 {
        score -= 60.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by common item-size
    // harmonics (10, 20, 25, 50) are more likely to be reused.
    if post % 10 == 0 && post > 0 {
        score -= 15.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 50 == 0 && post > 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: post_residual / item_size ratio —
    // penalize bins where leftover cannot hold even the smallest item class.
    if post > 0 && post < 10 {
        score += 25.0; // dead space band
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == post as u32 {
            score -= 200.0;
        } else if next_item_size <= post as u32 {
            let slack = post as f64 - next_item_size as f64;
            score -= 30.0 * (1.0 - slack / cap as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (next_item_size as f64 - post as f64) / cap as f64;
            score += 10.0 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * (item_size as f64 / bin_residual as f64) * 100.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it wins
    // only when all open bins have bad fits.
    if bin_residual == bin_capacity {
        score = cap as f64 - post_residual as f64; // = capacity
        score += 20.0; // mild inertia against opening new bins
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // pairing next item with fresh bin is fine
        }
    }

    // Progress-aware tie-break: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap as f64);

    // Crowding: with many open bins, encourage consolidating into fuller bins.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap as f64) * 3.0;

    score
}

