pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10] is unusable dead space
    // (minimum item size is 10 in classic setting; treat small gaps harshly).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Moderately awkward gap: only usable by small items.
        score += 25.0;
    }

    // Reward very tight fits (waste near zero) more than the raw residual does.
    let waste = post_residual as f64;
    score -= (1.0 - waste / bin_capacity as f64) * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Gap still usable by next item: mild reward proportional to fit quality.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fit_ratio;
        } else {
            // Next item cannot use this gap: penalize leaving a gap that strands it.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already low; encourage consolidating into fuller bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) slightly; penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has large post_residual,
    // which naturally scores high (bad). But if all existing bins would be
    // left with awkward dead space, allow the new bin to win by softening
    // its score when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 25.0 + 40.0 * fill;
    }

    // Early-stream: allow slightly more liberal bin opening while few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

