        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        // Dead-space coupling: penalize bins whose post residual is large
        // relative to mean residual yet cannot host the next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        // Reward near-exact next fills scaled by remaining stream density.
        if next_consumes && post_residual - next_item_size <= 1 {
            score -= 5.0 * future_density;
        }
        // Mid-band waste: residuals too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        // Reward post residuals that stay multiples of a common small size.
        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 {
            score -= 3.0 * (1.0 - progress);
        }
        // Tighten dead-space ratio penalty with a milder threshold band.
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        // Mutation: exact-fit lookahead two steps deep — if the next item
        // fills the residual exactly AND the item after could use what remains,
        // strongly favor this bin.
        if next_consumes && next_item_size > 0 && post_residual == next_item_size && item_size <= bin_capacity / 2 {
            score -= 14.0 * future_density;
        }
        // Mutation: discourage leaving residuals just below the mean item size,
        // since most future items won't fit into them.
        if !next_consumes && post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual > 12 {
            score += 7.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so tiny residuals are favored strongly.
    let mut score = pr + 12.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling: residual waste penalized more as stream progresses.
    score += 25.0 * norm_pr * norm_pr * progress;

    // Reward tight fits: coupling of item size ratio with progress.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * (1.0 - norm_pr) * (0.5 + progress);

    // Dead-space term: residual too small for typical future items.
    let dead = ((12.0 - norm_pr * 100.0).max(0.0)) / 100.0;
    score += 8.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits in post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - nxt / cap);
        } else {
            let overshoot = (nxt - pr) / cap;
            score += 5.0 * overshoot * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins) early,
    // and above mean later (consolidation).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * (0.5 - progress);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

