pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic grid: split capacity into deciles for class logic.
    let decade = (bin_capacity / 10).max(1);
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let look = 1.0 - 0.5 * progress; // lookahead trust decays over the stream

    // --- Harmonic class of the post residual ---
    if post_residual == 0 {
        // Perfect closure: exact fit seals the bin — dominant reward.
        score -= 60.0;
    } else {
        let r_class = (post_residual / decade) as f64; // integer-division class 0..=9
        // Steeper best-fit pressure near zero: low-class leftovers strongly favored.
        score -= 6.0 * (9.0 - r_class);
        // Modulo alignment: residual on the decade grid may exactly match a future item.
        if post_residual % decade == 0 {
            score -= 3.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            // Perfect chain: the next item exactly seals this bin.
            score -= 40.0 * look;
        } else if nxt < post {
            // Next item still fits here afterward — mild bonus.
            score -= 5.0 * look;
            if post_residual % next_item_size == 0 {
                score -= 2.0; // harmonic alignment: next divides the leftover
            }
            if fitting_bins_count == 1 {
                score -= 15.0; // last chance before stranding this residual
            }
        } else {
            // Next item does not fit the post residual.
            if next_item_size <= bin_residual {
                // Placing here strands a residual the next item could have used:
                // penalize so a fresh bin (preserving bin_residual) can win instead.
                score += 45.0 * look;
            } else if fitting_bins_count == 1 {
                // Next can't use this bin either way; use it now.
                score -= 15.0;
            }
        }
    } else if fitting_bins_count == 1 {
        // Final item: last chance before a wasted new bin.
        score -= 15.0;
    }

    // --- Global consolidation pressure ---
    // Favor bins whose residual is below the open-bin mean (fill emptier bins first).
    score += 0.08 * (bin_residual as f64 - mean_residual);
    // Mild friction against opening yet another bin when many are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * (open_bins_count.min(20) as f64);
    }

    score
}

