pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual ;
    let tightness = post_residual as f64 / bin_capacity as f64 ;
    score -= (1.0 - tightness) * 18.0 ;
    if post_residual == 0 { score -= 530.0 ; }
    else if post_residual <= 4 { score -= 235.0 ; }
    if post_residual > 0 && post_residual < 10 && ! next_consumes { score += 55.0 + 0.75 * post_residual as f64 ; }
    if post_residual > 0 && post_residual < item_size . min (80) { score += 42.0 + 0.5 * post_residual as f64 ; }
    let slots = post_residual / 10 ;
    score -= 5.0 * slots as f64 ;
    if fitting_bins_count <= 2 && bin_residual != bin_capacity { score -= 15.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 450.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 72.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 38.0 ; }
            if post_residual >= next_item_size * 2 { score -= 60.0 ; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0 ; }
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 0.55 * waste ;
            if waste > bin_residual as f64 { score += 28.0 ; }
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score -= 12.0 * (1.0 - dev / bin_capacity as f64) ;
        }
    }
    score += (mean_residual - bin_residual as f64) * 0.09 ;
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0 ;
    // dead sliver band
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64 ;
        let future_help = if next_consumes { 1.0 } else { 0.0 } ;
        score += dead_sliver * (1.55 - future_help) ;
    }
    // new-bin candidate gating
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 ;
        score += 20.0 * progress ;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0 ; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 { score -= 11.0 * (1.0 - progress) ; }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 { score -= 37.0 * (1.0 - progress) ; }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size { score -= 19.0 * (1.0 - progress) ; }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual { score += 22.0 * (1.0 - progress) ; }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size . max (next_item_size) { score -= 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual < item_size . min (next_item_size . max (1)) { score += 9.0 ; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0 ; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual { score += 12.0 * (1.0 - progress) ; }
    }
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0 ; }
        let remaining = if total_items > step_index { total_items - step_index } else { 0 } ;
        let future_density = remaining as f64 / total_items . max (1) as f64 ;
        let stranded = post_residual as f64 / bin_capacity as f64 ;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress) ;
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density ; }
        }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress) ; }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 { score += 6.0 * (1.0 - progress) * stranded ; }
        if next_consumes && post_residual - next_item_size <= 1 { score -= 5.0 * future_density ; }
        if ! next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual { score += 5.0 * future_density * (1.0 - stranded) ; }
        if dead_ratio > 0.45 && ! next_consumes { score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress) ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // 2-step lookahead: big reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 60.0; // perfect chain: bin fully consumed over two steps
        } else if next_item_size <= post_residual {
            // next item fits too: mild reward proportional to how snugly
            let two_step_waste = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - two_step_waste / bin_capacity as f64);
        } else {
            // next item won't fit in leftover: penalize large leftovers
            let gap = nxt - post_residual as f64;
            score += 0.6 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist and can absorb the item,
    // unless the item is huge and would leave a tiny unusable residual elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - tightness); // new bins OK for big items
        if fitting_bins_count > 0 {
            score += 10.0; // discourage skipping usable open bins
        }
    }

    // Very small post-residuals are dead space; reward near-full packing.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;
    }

