pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 25 are "clean"
    let class = post_residual / 25;
    match class {
        0 => score -= 18.0,           // tiny dead space, near-perfect fit
        1 => score -= 6.0,            // 25..49 residual, still reusable for small items
        2 => score += 4.0,            // 50..74 residual, mediocre
        _ => score += 10.0,           // large leftover, wasteful placement
    }

    // Modulo-5 harmony: residual divisible by 5 pairs well with typical sizes
    if post_residual % 5 == 0 {
        score -= 5.0;
    }
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item slots in perfectly -> strong reward, stronger if exact
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.05 * slack;
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if next_item_size <= bin_residual {
            // next item needs this bin's original space; penalize consuming it
            score += 8.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 20.0 * fragmentation / bin_capacity as f64
