    }

    // Prefer filling bins far below the mean residual (tighter packing)
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Slight preference for high fill ratio
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

