pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: classify the gap left behind.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny unusable gap: nearly as good as a perfect fit.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Mid-size dead space: the worst outcome, penalize heavily.
        score += 30.0;
    } else if post_residual <= 40 {
        // Moderate gap: mildly bad, but potentially reusable by small items.
        score += 8.0;
    } else {
        // Large gap: still usable, mild reward relative to raw residual.
        score -= 5.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual != bin_capacity {
        // Existing bin: subtract pressure (favor it).
        score -= pressure * 6.0;
    } else {
        // New-bin candidate: add pressure (penalize it) unless the fit is bad.
        score += pressure * 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item could use the leftover gap,
    // the residual is less "dead" — soften the penalty.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If the next item almost fits the gap, the gap is truly dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
