        // Slight preference for bins below mean residual (consolidate emptier bins).
        if bin_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with a mild convex penalty for
    // mid-range dead space (worst around rn ~ 0.4-0.6).
    let mut score = r
        + 30.0 * rn * (1.0 - rn) * (1.0 - progress)
        + 15.0 * rn * rn * progress;

    // Tight fits get rewarded more as the stream progresses.
    let tightness = 1.0 - rn;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if r >= nxt {
            let slack_after_next = (r - nxt) / cap;
            score -= 10.0 * (1.0 - slack_after_next) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (nxt - r) / cap;
        }
    }

    // Mean-residual divergence: penalize bins far from the mean residual,
    // encouraging a homogeneous pool that is easier to pack later.
    score += 0.05 * (mean_residual - r).abs();

    // Mild pressure against accumulating too many open bins early.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * rn;

    // New-bin candidate: make an empty bin slightly unattractive unless
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual ;
    let tightness = post_residual as f64 / bin_capacity as f64 ;
    score -= (1.0 - tightness) * 18.0 ;
    if post_residual == 0 { score -= 520.0 ; }
    else if post_residual <= 4 { score -= 220.0 ; }
    if post_residual > 0 && post_residual < 10 && ! next_consumes { score += 50.0 + 0.7 * post_residual as f64 ; }
    if post_residual > 0 && post_residual < item_size . min (80) { score += 40.0 + 0.5 * post_residual as f64 ; }
    let slots = post_residual / 10 ;
    score -= 5.0 * slots as f64 ;
    if fitting_bins_count <= 2 && bin_residual != bin_capacity { score -= 15.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 430.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 65.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 35.0 ; }
            if post_residual >= next_item_size * 2 { score -= 55.0 * (1.0 - progress) ; }
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 0.55 * waste ;
            if waste > bin_residual as f64 { score += 27.0 ; }
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual).abs () ;
            score -= 12.0 * (1.0 - dev / bin_capacity as f64) ;
        }
    }
    score += (mean_residual - bin_residual as f64) * 0.085 ;
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0 ;
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64 ;
        let future_help = if next_consumes { 1.0 } else { 0.0 } ;
        score += dead_sliver * (1.5 - future_help) ;
    }
    if bin_residual == bin_capacity {
        score += 22.0 * fitting_bins_count as f64 + 18.0 * progress ;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 { score -= 37.0 * (1.0 - progress) ; }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual { score += 20.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0 ; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0 ; }
    }
    if post_residual > 0 {
        let remaining = if total_items > step_index { total_items - step_index } else { 0 } ;
        let future_density = remaining as f64 / total_items . max (1) as f64 ;
        let stranded = post_residual as f64 / bin_capacity as f64 ;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress) ;
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density ; }
        }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress) ; }
        if next_consumes && post_residual - next_item_size <= 1 { score -= 5.0 * future_density ; }
        if ! next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual { score += 5.0 * future_density * (1.0 - stranded) ; }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.5 && ! next_consumes { score += 6.0 * (dead_ratio - 0.5) * (1.0 - progress) ; }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 { score += 6.0 * (1.0 - progress) * stranded ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues divisible by common item sizes are reusable.
    // Treat post_residual modulo 10 (items are multiples of 10 in classic streams).
    let r = post_residual % 10;
    if r == 0 {
        score -= 30.0; // "harmonic" residual: likely reusable by future items
    } else {
        score += 10.0 + (r as f64) * 2.0; // dead-space penalty grows with odd residue
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity
    let q = post_residual / (bin_capacity / 4);
    score += match q {
        0 => 40.0,   // tiny leftover: high dead-space risk
        1 => -5.0,
        2 => -15.0,
        _ => -25.0,  // large residual remains useful
    };

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match: next item fills bin completely -> strong reward
            if next_item_size == post_residual {
                score -= 200.0;
            } else {
                score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
            }
        } else {
            // next item won't fit here; penalize more if leftover is awkward
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Late in the stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins below mean residual (tighter bins) slightly
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        if post_residual >= 40 && item_size <= 50 {
            score -= 50.0; // large item into fresh bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 100.0; // no good alternative -> open new bin
        }
    }

    score
}

