pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: opening a new bin is only attractive when the current bin
    // would leave a large, awkward gap and the lookahead item needs fresh space.
    if bin_residual == bin_capacity {
        score = 200.0
            - 40.0 * progress
            - (if next_item_size > 0 && next_item_size > bin_residual - item_size { 30.0 } else { 0.0 })
            - (if fitting_bins_count == 0 { 100.0 } else { 0.0 });
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

