    let pr_norm = pr / cap;

    // Base: prefer small post residual, smoothed non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate residual slack; late, penalize it harder.
    score += 40.0 * (pr_norm * pr_norm) * (0.25 + 0.75 * progress);

    // Reward tight fits (post_residual near zero) with a smooth dip.
    score -= 30.0 * (-pr_norm * 12.0).exp();

    // Penalize large dead space that likely becomes unusable.
    score += 25.0 * (pr_norm - 0.35) * (pr_norm - 0.35);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
