        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress); }

        // Dead-space coupling: large residual relative to mean that can't host next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }

        // Mid-band waste: too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }

        // NEW: harmonic-fit bonus — post residual that can be split into a
        // plausible future item plus a small remainder stays valuable.
        if next_item_size > 0 && post_residual >= next_item_size * 3 {
            score += 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold anything useful
    // (nothing but the smallest possible items) are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0; // unusable sliver
    } else if post_residual == 0 {
        // Perfect fill is the best possible outcome.
        score -= 300.0;
    } else {
        // Smooth reward for tight fits: the smaller the leftover, the better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Penalize leaving a gap that is *just* below typical item sizes but not zero:
    // medium dead zones (e.g. 11..=19) rarely get filled.
    if post_residual >= 1 && post_residual <= 19 {
        score += 40.0 * (20 - post_residual) as f64;
    }

    // If the next item fits exactly into the post residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 80.0 - (gap as f64).min(80.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty so chains of compatible items stay together.
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling
    // existing bins rather than creating new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and remaining stream,
        // but relax when the current fit is terrible (large post_residual elsewhere).
        score += 120.0 + pressure;
    } else {
        score -= pressure * 0.1;
    }

    // Slight preference toward bins below the mean residual when many bins are open
    // (balance load, avoid many near-empty bins).
    if bin_residual as f64 > mean_residual && open_bins_count > 2 {
        score += 10.0;
    } else if bin_residual as f64 <= mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
