    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact / near-exact fill rewards.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 4 {
        score -= 220.0;
    }

    // Dead slivers.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Slot-count discount.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 430.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 65.0; }
            if slack > 0.0 && slack < 12.0 { score += 35.0; }
            if post_residual >= next_item_size * 2 { score -= 55.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
    }

    // Sliver penalty scaled by future density.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.5 - future_help);
    }

    // Balance load mildly.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bonus.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 { score -= 11.0 * (1.0 - progress); }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 { score -= 37.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size { score -= 19.0 * (1.0 - progress); }
        if fitting_bins_count >= 2 && post_residual >= item_size { score += 12.0 * (1.0 - progress); }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 { score += 9.0 * (1.0 - progress); }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) { score += 9.0; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress); }
        if dead_ratio > 0.45 && !next_consumes { score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress); }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0; }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 { score -= 10.0 * (1.0 - progress); }

        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density; }
        }

        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress); }

        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }

        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, mild residual penalty; later, stronger push to fill bins tightly.
    let progress_coupling = pr * (0.5 * progress + 1.5 * progress * progress * (1.0 - progress));
    score += progress_coupling;

    // Reward tight fits via a smooth saturating term.
    let tightness = 1.0 - norm_pr;
    score -= item_size as f64 * tightness * (1.0 + progress);

    // Dead-space penalty: residuals too small to hold the smallest plausible item.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (2.0 + 3.0 * progress);
    }

    // Lookahead: favor bins whose post-residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 2.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bins attractive only when open bins are quite full.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap);
        score = cap * (0.35 + 0.4 * mean_fullness * mean_fullness + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
