        score -= 235.0;
    } else if post_residual <= 8 {
        score -= 60.0; // NEW: extend the near-exact reward band slightly.
    }

    // Penalize dead slivers that cannot host typical future items.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Slot-count discount: residual divisible into chunks is reusable.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead pairing: exact next fit is gold; tight slack is great; wasted slack is bad.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
