            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
            if post_residual - next_item_size <= 1 { score -= 5.0 * future_density; }
            // NEW: chain-fit bonus — residual that fits next item AND leaves room for
            // a typical item afterwards is a strong compaction signal.
            if slack >= 8.0 && slack as u32 >= next_item_size.min(40) { score -= 18.0 * (1.0 - progress); }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
            // NEW: if the wasted next item would fit in a fresh bin together with
            // this item's remainder, mildly discourage stranding it here.
            if item_size + next_item_size <= bin_capacity && open_bins_count > 1 {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // Sliver dead-space penalty scaled by future stream density.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Balance load mildly.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 { score -= 11.0 * (1.0 - progress); }
