        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }

        // Mid-band waste: too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }

        // NEW: residual that can host next item AND the item after a split
        // (residual - next >= typical small size) is doubly reusable.
        if next_consumes && post_residual - next_item_size >= 20 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10
    let cls = post_residual % 10;
    // Small residues (1..=9) are awkward slivers; penalize them progressively
    if post_residual > 0 && post_residual < 10 {
        score += (10 - cls) as f64 * 4.0;
    }

    // Perfect fits are golden
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic fraction thresholds on residual capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 && post_residual > 0 {
        score += 15.0; // nearly-full bin leaves nothing usable
    } else if frac >= 0.25 && frac < 0.50 {
        score -= 8.0; // quarter-to-half space is versatile
    }

    // Lookahead coupling: does post_residual fit next item harmonically?
    if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits exactly into the leftover: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            let next_left = post_residual - next_item_size;
            // harmonic bonus decays with the new dead space created
            score -= 12.0 - (next_left % 10) as f64 * 0.5;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item would fit this bin now but not after placing current item:
        // penalize destroying that possibility, scaled by how close it was
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): open new bins only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 40.0 + 60.0 * progress;
        // large items justify fresh bins; tiny items should reuse space
        if item_size >= bin_capacity / 2 {
            open_cost -= 20.0;
        }
        if item_size <= bin_capacity / 10 {
            open_cost += 25.0;
        }
        // if few bins can fit the item, new bin is less wasteful
        if fitting_bins_count <= 1 {
            open_cost -= 15.0;
        }
        score += open_cost;
    }

    // Prefer tightest bins overall: couple with mean residual
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    score
}

