            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) { score += 9.0; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        // NEW: reward bins whose post_residual exactly matches a plausible future chunk.
        if post_residual > 0 && post_residual % 25 == 0 && post_residual >= 25 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        // Dead-space ratio penalties.
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress); }
        if dead_ratio > 0.45 && !next_consumes { score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress); }

        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0; }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 { score -= 10.0 * (1.0 - progress); }

        // Stranded residual: cannot host next item -> penalize, worse early.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density; }
        }

        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress); }

        // Dead-space coupling: large residual relative to mean that can't host next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }

        // Mid-band waste: too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }

        // NEW: dead-space ratio refinement — extra pressure on very high waste when the
        // stream still has plenty of items to place.
        if dead_ratio > 0.75 && future_density > 0.4 && post_residual < item_size {
            score += 7.0 * (dead_ratio - 0.75) * future_density;
        }
        // NEW: mild reward when post_residual remains above the mean (bin stays flexible).
        if post_residual as f64 >= mean_residual * 1.1 && next_consumes {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does it fall in?
    let q = bin_capacity / 4; // 25
    let class = if post_residual == 0 { 0 }
        else if post_residual <= q { 1 }          // tiny dead space
        else if post_residual <= 2 * q { 2 }
        else if post_residual <= 3 * q { 3 }
        else { 4 };                               // huge leftover

    // Penalize dead space super-linearly within classes
    match class {
        0 => score -= 30.0,                       // perfect fit: strong reward
        1 => score -= 8.0,                        // good fit
        2 => score += 6.0,
        3 => score += 18.0,
        _ => score += 30.0,
    }

    // Modulo-arithmetic coupling: does next item fit into post_residual?
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if next_fits {
        // Reward bins whose leftover matches the lookahead's harmonic class
        let r = post_residual % q;
        let nr = next_item_size % q;
        if r >= nr { score -= 10.0; } else { score -= 4.0; }
        if post_residual == next_item_size { score -= 25.0; }
    } else if next_item_size > 0 {
        score += 8.0; // leftover likely unusable for next item
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 { score -= 40.0; }
        if post_residual as i64 - next_item_size as i64 >= 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progress-aware mild normalization against mean residual
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * (mean_residual - post_residual as f64) * (0.5 + progress);

    // Integer-division threshold bonus: leftover in [10, 20] is highly reusable
    if post_residual >= 10 && post_residual <= 20 { score -= 12.0; }
    if post_residual > 20 && post_residual < 10.min(20) { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
