        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0; }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 { score -= 10.0 * (1.0 - progress); }

        // Stranded residual: cannot host next item -> penalize, worse early.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density; }
        }

        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress); }

        // Dead-space coupling: large residual relative to mean that can't host next item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }

        // Mid-band waste: too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }

        // NEW: graded dead-space penalty — residual that is a small fraction of the item
        // just placed is nearly unusable; scale penalty smoothly with the ratio.
        let usable_ratio = post_residual as f64 / item_size.max(1) as f64;
        if usable_ratio < 0.5 && !next_consumes {
            score += 7.0 * (0.5 - usable_ratio) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post residual that is too small for the smallest item (1) is perfect;
    // but small-but-nonzero gaps that cannot fit the next item are dead space.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to lookahead: strong penalty.
            let dead = (next_item_size - post_residual) as f64;
            score += 3.0 * dead;
        }
        // Absolute tiny-gap penalty: gaps that likely can't fit anything useful.
        if post_residual <= 10 {
            score += 15.0;
        } else if post_residual <= 25 {
            score += 8.0;
        }
    } else {
        // Perfect fit: big reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // all alternatives are terrible. Penalize the empty-bin candidate,
    // more so when many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize placements that leave large residuals there).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already below the mean (tighter bins).
    score += 0.1 * (post_residual as f64 - mean_residual);

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Slight late-stream tightening: as stream progresses, be greedier.
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

