        score += 40.0;
        score += 2.0 * open_bins_count as f64;
        // Early in the stream, a fresh bin is cheap (more future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If item is large, a fresh bin gives maximal future flexibility.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
