pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual (favor tight fits), with non-linear saturation
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr + 0.15 * norm_pr * norm_pr * norm_pr;

    // Smooth interaction: as stream progresses, tolerate less dead space
    score *= 1.0 + 0.6 * progress * norm_pr;

    // Penalize residuals that are too small to ever be useful again (smooth ramp)
    let useless = ((50.0 - pr) / cap).max(0.0);
    score += 1.2 * useless * useless;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((next_item_size as f64 - pr).abs() / cap).min(1.0);
        score -= 0.8 * fits * closeness;
        // Penalize post-residual that neither fits next item nor is tiny
        score += 0.5 * (1.0 - fits) * norm_pr;
    }

    // Mild preference to fill bins when many are open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins with less residual (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64) / cap;

    score
}

