        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class of post_residual: dead space in low classes is more usable.
    let class = post_residual / 10; // integer division: 0..10 harmonic bands
    score -= (10 - class.min(10)) as f64 * 3.0;

    // Penalize post_residuals that cannot host common item sizes (1..100).
    let mut usable = 0u32;
    for s in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if s <= post_residual {
            usable += 1;
        }
