    score -= usable as f64 * 15.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 50.0;
        } else {
            // next item won't fit here; residual becomes waste unless small
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so we prefer filling open bins,
    // unless the item fits poorly everywhere (handled by above rewards).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is good if mean residual across open bins is tiny
        // (nothing can absorb the item well).
        if mean_residual < item_size as f64 {
            score -= 150.0;
        }
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Many open bins: prefer spreading into emptier bins (larger residual).
    if open_bins_count > 4 {
        score += (mean_residual - bin_residual as f64) * 0.3;
