        // Mid-band waste: too large for slivers, too small for future items.
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }

        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }

        // NEW: penalize residuals that are just barely below the next item (wasted near-miss).
        if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 7.0 * (1.0 - next_item_size.saturating_sub(post_residual) as f64 / 6.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits: subtract proportional to how well the item fills the bin.
    score -= 12.0 * fill_frac * fill_frac;

    // Penalize dead space non-linearly: small residuals that can't host typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (1.0 - post_frac); // marginal dead zone
    } else {
        // Larger residuals are partially reusable; reward proportionally to reusability.
        score -= 4.0 * post_frac.min(0.8);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by how snugly it will fit.
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize blocking the next item slightly.
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than opening new ones.
    let consolidation_pressure = open_bins_count as f64 * (mean_residual / cap).clamp(0.0, 1.0);
    score -= 3.0 * consolidation_pressure.min(10.0) * (1.0 - progress * 0.5);

    // New-bin candidate handling: penalize opening a new bin, more so as the stream
    // progresses and consolidation matters more; relax slightly early on.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * progress;
        // If nothing else fits well (this is the only fitting candidate anyway),
        // soften the penalty so a new bin can be opened when necessary.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Early stream: opening bins cheaply builds a diverse residual portfolio.
        if progress < 0.1 {
            score -= 8.0;
        }
    }

    // Mild time-horizon modulation: later in the stream, prefer minimizing
    // absolute waste more aggressively.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
