    score += 0.05 * (mean_residual - pr).abs();

    // Mild new-bin aversion growing with open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

