    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual waste quadratically.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - lookahead_fit);
