    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bins of leftover space.
    let post_class = post_residual % 10;
    // Dead space penalty: leftovers < 10 are nearly unusable (min item = 10 in classic case,
    // but sizes go down to 1, so weight small classes less harshly at late steps).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - 0.5 * post_class as f64;
    }

    // Integer-division thresholds on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter && post_residual > 0 {
        score += 6.0; // tiny leftover: bad unless last-chance
    } else if post_residual > half {
        score -= 4.0; // big leftover retained: good bin flexibility
    }

    // Perfect fit reward: post_residual exactly divisible by common item classes.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead harmonic coupling: can next item land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item still fits here
        } else {
            score += 4.0; // next item won't fit: this leftover is stranded
            // modulo-class match between next item and leftover
            if next_item_size % 10 == post_class && post_residual >= 10 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual < 10 {
            score -= 5.0; // even better: nearly full use
        }
    }

    // New-bin candidate handling: empty bin gets a mild default so it wins only
    // when all open bins score poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 10.0; // next item huge: fresh bin attractive
