    // Stream progression: tighten thresholds as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Prefer bins with residual close to item (tight packing) via mean coupling.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

