        if next_consumes {
            let slack2 = post_residual - next_item_size;
            if slack2 > 30 && slack2 as f64 > mean_residual {
                score += 3.0 * (slack2 as f64 - 30.0) * 0.1;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual is "dead" if it is smaller than the smallest plausible item (assume ~10)
    // but nonzero. The tighter the gap, the worse the waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else {
        // Mild penalty for large leftover space that could have been used elsewhere.
        score += 0.05 * post_residual as f64;
    }

    // Open-bin pressure: penalize placements that keep many bins open with slack,
    // but reward consolidating into nearly-full bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.3 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
        score -= 25.0;
    } else if next_item_size > post_residual as u32 {
        // Next item won't fit here anyway; slightly neutralize dead-space penalty
        // since the gap cannot serve the next item regardless.
        score -= 5.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when open bins
    // are congested (high pressure) or the fit is poor.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: neutral residual, but apply pressure so that when
        // open bins are numerous and slack-rich, we prefer them instead.
        score = 100.0 + 2.0 * open_bins_count as f64 - pressure * 1.5;
        if fitting_bins_count == 1 {
            // Never open a new bin when this item fits nowhere else.
            score += 100.0;
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (fewer chances to consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

