            if frac > 0.7 {
                score -= 30.0 * (frac - 0.7) / 0.3;
            } else {
                score += 120.0; // keep using open bins
            }
        }
    }

    // Mild preference to balance load across bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.05 * (mean_residual - post).max(0.0);
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
