    // reward a residual that fits next_item_size exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < dead_zone {
                score -= 20.0 * (1.0 - slack / dead_zone); // next item will seal this bin
            } else {
                score += 4.0;
            }
        } else if post_residual > 0 {
            score += 8.0; // next item cannot use this gap
        }
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when the item is large (would leave big waste in any open bin) or no good fit exists.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_cost = 30.0 + 40.0 * (1.0 - size_frac); // small items should NOT open bins
        if fitting_bins_count == 0 {
