            // Next item won't fit: penalize wasted small gap, worse if gap tiny.
            score += 20.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
            if post_residual < 10 {
                score += 15.0; // dead space penalty
            }
        }
        // Coupling: if post_residual matches next item exactly AND this is the last fitting bin, extra reward.
        if diff < 0.5 && fitting_bins_count == 1 {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post_residual (fill bins tightly).
        score -= 10.0;
    }

