    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin gives
    // a good fit (post_residual near zero) or when few bins are open.
    if bin_residual == bin_capacity {
        // Empty-bin candidate: base cost plus scaling with how many bins already open.
        score = bin_capacity as f64 * 1.2 + 5.0 * open_bins_count as f64;
        // If the item is large relative to capacity and many bins open, slightly cheaper to open new bin.
        if item_size as f64 > 0.7 * bin_capacity as f64 && open_bins_count > 2 {
            score -= 30.0;
        }
        // If next item is tiny, opening a fresh bin wastes capacity potential.
        if next_item_size > 0 && next_item_size <= 15 {
            score += 25.0;
        }
    }

    // Mild stream-progression coupling: late in the stream, be more conservative (prefer filling existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

