    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fill is the best possible outcome.
    if post_residual == 0 {
        score -= 560.0;
    } else if post_residual <= 4 {
        score -= 245.0;
    } else if post_residual <= 8 {
        score -= 90.0 * (1.0 - progress);
    }

    // Dead-space avoidance: residuals too small to hold anything useful.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 60.0 + 0.8 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 45.0 + 0.5 * post_residual as f64;
    }

    // Reward residual slots divisible by common item granularity.
    let slots = post_residual / 10;
    score -= 5.5 * slots as f64;

    // Lookahead: exact match with next item is a strong chain signal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 470.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 125.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 78.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 40.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 65.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 15.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 6.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 20.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
            if waste > bin_residual as f64 {
                score += 30.0;
            }
        }
    }

    // Medium dead zones (1..=19) rarely get filled unless the next item consumes them.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.6 - future_help);
    }

    // Balance toward the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.10;

    // Last-chance pressure: only bin that fits.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE: penalize proportionally to fitting alternatives and progress.
        score += 21.0 * fitting_bins_count as f64;
        score += 21.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 32.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 44.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 28.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 18.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 39.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 20.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 14.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 21.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 13.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 28.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        // New: opening a bin is attractive when its leftover exactly matches a common
        // future granularity (post_residual % 5 == 0) and space is scarce overall.
        if post_residual > 0 && post_residual % 5 == 0 && mean_residual < item_size as f64 {
            score -= 9.0 * (1.0 - progress);
        }
    } else {
        // Open-bin branch: keep chains of compatible items together.
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 23.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 13.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 10.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 15.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 7.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 13.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 27.0 * (1.0 - progress);
        }
        // New: reward near-perfect two-item packing (residual after both items <= 3).
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.5 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.5 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 10.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 11.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 15.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 11.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.5;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 16.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.5 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.5 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 {
            score -= 3.5 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 13.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.5 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        // New: mild penalty for large stranded residual late in the stream when the
        // mean residual is small — those leftovers rarely get reused.
        if !next_consumes && progress > 0.5 && post_residual > 40 && mean_residual < post_residual as f64 * 0.4 {
            score += 6.0 * (post_residual as f64 - 40.0) / 60.0;
        }
    }

    score
}

