        // (dead space) but nonzero.
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when the
    // item fits reasonably well elsewhere. The empty bin has
    // post_residual == bin_capacity - item_size, which is large, so the
