pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (dead space grows super-linearly).
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress: early on, waste is cheap;
    // late in the stream, tighten packing aggressively.
    score *= 1.0 + 1.2 * progress * (1.0 - progress) * 4.0 * norm_pr * (1.0 - norm_pr);

    // Reward tight fits: interaction of item size with residual.
    score -= 25.0 * norm_item * (1.0 - norm_item) * (1.0 - norm_pr);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let fit = norm_next / (norm_pr + 0.05);
        score -= 18.0 * fit / (1.0 + fit * fit);
    }

    // Penalize crowded bin pools slightly to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
