pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by modulo classes
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Perfect fit bonus (harmonic class 0: post_residual == 0 or exactly divisible thresholds)
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: leftover that no future item (sizes 1..100) can use efficiently
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // tiny unusable sliver
    }

    // Harmonic coupling with lookahead: if next item fits exactly in post_residual, big reward
    if next > 0.0 {
        if next == post {
            score -= 300.0;
        } else if next < post {
            // next item fits: reward proportional to how well it fills the remainder
            let fill = next / post;
            score -= 100.0 * fill;
            // harmonic class check: post % next small => good chaining
            let m = (post_residual as u64) % (next_item_size.max(1) as u64);
            if m == 0 {
                score -= 50.0;
            } else {
                score += 20.0 * (m as f64 / next);
            }
        } else {
            // next item won't fit here; penalize leaving large gap that blocks lookahead
            score += 40.0 * (next - post) / cap;
        }
    }

    // Fraction-of-capacity classes: reward leaving residuals in "useful" harmonic bands
    let frac = post / cap;
    if frac >= 0.5 {
        score -= 30.0; // half-full or more room left is flexible
    } else if frac >= 0.25 {
        score -= 10.0;
    } else if frac > 0.0 {
        score += 60.0 * (0.25 - frac); // small residuals are risky
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer bins tighter than average (best-fit style)
    score += (post - mean_residual) * 0.5;

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 80.0 + 120.0 * progress;
        if next > 0.0 && next <= cap {
            score -= 20.0; // fresh bin is fine early
        }
    } else if open_bins_count > 0 && progress > 0.7 {
        score -= 25.0; // pack into existing bins late
    }

    score
}

