    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of old bins;
    // penalize it unless the item is large and no open bin is a good fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
