pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space (dead space aversion).
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Reward filling the bin deeply (item large relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward; if next item would be blocked by tiny leftover, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fits here later: keep bin usable
            score -= 6.0 * (1.0 - (nxt / (post + 1.0)));
        } else {
            // leftover too small for next item: dead-space risk scaled by tightness
            score += 4.0 * (1.0 - nxt / bin_capacity as f64);
        }
    } else {
        // Last item in stream: any residual is wasted, minimize it hard.
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor fits (large mean residual mismatch) or item is huge.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins early and when existing bins fit reasonably.
        let mut nb = 30.0 + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            nb -= 8.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
        }
        nb += mean_gap * 0.15;
        // Huge items near capacity justify fresh bins.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            nb -= 10.0;
        }
        // Many open bins with scattered residuals: consolidation is cheap.
        nb += open_bins_count as f64 * 0.3;
        score += nb;
    }

    // Mild bonus for keeping bins balanced: prefer bins near the mean residual.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

