}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" dead-space classes.
    let post = post_residual;
    let residue = (post % 10) as f64;

    // Reward post-residuals that are near-zero or near multiples of 10 (harmonic fit).
    if post == 0 {
        score -= 1000.0; // perfect closure
    } else {
        score += residue * 0.8; // penalize off-class residuals
        if post % 10 == 0 {
            score -= 12.0; // harmonic class bonus
        } else if post % 25 == 0 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds: small post-residuals are dead space.
    if post > 0 && post < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 150.0;
        } else if next_item_size <= post {
            let r = (post - next_item_size) % 10;
            score -= 20.0 - r as f64 * 1.5;
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when current fits are bad.
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so decent fits win
        score += 15.0;
        if post_residual == bin_capacity {
            // empty bin with large item: fine
            score -= item_size as f64 * 0.1;
        }
    }

    // Progress-based tuning: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += (open_bins_count as f64) * 0.3;

    // Mean residual alignment: prefer bins close to the mean residual (balance).
    let diff = (post as f64 - mean_residual).abs();
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

