    // encouraging consolidation; but if this is the last fitting bin, reward strongly.
    if fitting_bins_count == 1 {
        score -= 50.0; // last-chance bin: use it rather than opening a new one
    } else {
        score += (open_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual naturally;
    // penalize opening a new bin unless the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
