    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space too small for the smallest plausible item (1..100 range),
    // but only if the leftover cannot host the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space that blocks the lookahead item.
        score += 4.0 + 0.08 * post_residual as f64;
    }
    // Reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 0.05 * (post_residual - next_item_size) as f64;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is penalized, more so when
    // good fitting options exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.5 * open_bins_count as f64;
        // But if the item is huge relative to typical residual, opening may be wise.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size as f64 > mean_residual + 15.0 {
            score -= 22.0 * (1.0 - progress);
