        if open_bins_count < 2 {
            score += 10.0;
        }
    } else {
        // Mild preference for emptier bins among open ones.
        score -= 0.06 * bin_residual as f64;
        // Prefer bins below mean residual (keeps a spread of capacities).
        if (bin_residual as f64) > mean_residual {
