            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 5.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
            // NEW: slack that still accommodates a mid-size follow-up is fine.
            if slack >= 12.0 && slack as u32 >= next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Medium dead zones (1..=19) rarely get filled unless the next item consumes them.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Balance toward the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance pressure: only bin that fits.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE: penalize proportionally to fitting alternatives and progress.
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        // NEW: opening a bin whose post-residual cannot hold next_item is wasteful
        // when some open bin could have hosted the item instead.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 40 {
            score += 18.0 * (1.0 - progress) * (1.0 - post_residual as f64 / 40.0);
        }
        // NEW: a fresh bin is attractive when its residual matches the next item
        // exactly (perfect chain start).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 24.0 * (1.0 - progress);
        }
    } else {
        // Open-bin branch: keep chains of compatible items together.
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
