        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // New: prefer bins whose leftover stays divisible by the next item's granularity.
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
