    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Class 1: post_residual <= 8 -> essentially perfect fit, strong reward.
    if post_residual <= 8 {
        score -= 60.0;
    } else if post_residual <= 16 {
        score -= 35.0;
    } else if post_residual <= quarter as u32 {
        score -= 15.0;
    } else if post_residual <= 2.0 * quarter {
        score += 5.0;
    } else {
        // Very large leftover: bad, unless a big next item can use it.
        score += 10.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual (mod 10 / mod 25).
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0; // aligned residual likely reusable by future items
    } else if m10 >= 8 {
        score -= 4.0;
    } else {
        score += (10 - m10) as f64 * 0.8; // misaligned fragments penalized
    }

    // Integer-division threshold: which harmonic class (item_size/20) does the item belong to?
    let item_class = item_size / 20; // 0..4
    match item_class {
        0 => score -= 3.0,  // tiny items: keep them in near-full bins
        1 => score -= 1.0,
        2 => score += 0.0,
        3 => score += 3.0,  // large items: prefer tight fits strongly
        _ => score += 6.0,
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // exact chain fit is excellent
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            if post_residual > 16 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score = pr;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // current item is large and no tight option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64 / cap) > 0.6;
        let crowded = open_bins_count as f64 > 8.0 + 20.0 * progress;
        if big_item || crowded {
            score -= 12.0;
        } else {
            score += 55.0; // prefer filling existing bins early on
        }
        // Prefer fresh bins when mean residual across open bins is low.
        if mean_residual < 0.15 * cap {
            score -= 18.0;
        }
    }

    // Mild preference to balance load across many open bins.
    score += 0.05 * (open_bins_count as f64);
    // Slight drift term keyed to stream progress to adapt thresholds over time.
    score += (pr / cap) * (1.0 - 0.5 * (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
