pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like shaping
    score += poly * (pr * pr / cap) * 0.5;

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * item_size as f64 * 0.05;

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when open bins could fit, unless post_residual here is huge
    if bin_residual == bin_capacity {
        let newbin_base = cap * 0.35 + open_bins_count as f64 * 0.5;
        score += newbin_base;
        // lookahead: new bin is fine if next item is large
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score -= (nxt / cap) * (nxt / cap) * 20.0;
        }
    }

    // Lookahead coupling: penalize leaving residual that neither wastes nor helps next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score += diff * 0.05;
        if pr >= nxt {
            score -= 3.0 * (1.0 - diff / cap);
        }
    }

    // Mean residual deviation penalty: prefer bins whose residual deviates from mean
    let dev = (pr - mean_residual).abs();
    score += dev * 0.03 * (1.0 - poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
