pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes (1..100 stream, so multiples of 10, 20, 25, 50) is more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 7.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 4.0; } // inharmonic residue: harder to fill later
    }

    // Integer-division thresholds on post_residual: small leftovers are dead space.
    if pr <= 5 && pr > 0 {
        score += 25.0;
    } else if pr <= 10 && pr > 0 {
        score += 12.0;
    }

    // Capacity-fraction view of the bin's fill state.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0; // prefer packing into well-filled bins

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Harmonic bonus if post_residual and next item share a divisor class.
            let g = gcd(pr, next_item_size as u32);
            if g > 5 { score -= 8.0; }
            score -= 6.0; // next item still fits here: good
        } else if pr > 0 && pr < next_item_size {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size as f64 - pr as f64) * 0.3;
        }
    } else {
        // Last item: just minimize waste.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): mild default preference, but discourage
    // opening new bins when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Stream progression: as the stream matures, be more conservative about
    // leaving inharmonic residuals (fewer chances to fix them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if pr > 0 && pr % 10 != 0 {
        score += progress * 10.0;
    }

    // Slight tie-break toward bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

