        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * (1.0 - progress); }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 { score -= 4.0 * (1.0 - progress); }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * (1.0 - progress) * (1.0 - stranded);
        }
        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 { score -= 3.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0; }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: mild reward proportional to tightness.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space.
            let waste = post_residual as f64 - next_item_size as f64;
            score += 20.0 + waste;
        }
    } else {
        // Last item: just minimize residual (already base score).
    }

    // Relative residual compared to mean residual across open bins.
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 250.0;
        // If many bins fit the item, opening a new bin is less attractive.
        score += 40.0 * (fitting_bins_count as f64);
        // If the lookahead item pairs well with the current item in a fresh bin, reward.
        if next_item_size > 0 {
            let combined = item_size + next_item_size;
            if combined <= bin_capacity && bin_capacity - combined < 15 {
                score -= 400.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    } else {
        // Mild reward for keeping bins consolidated when few open bins.
        if open_bins_count > 1 {
            score -= 10.0;
        }
    }

    score
}

