pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Perfect / near-perfect fit gets extra discount.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that cannot plausibly fit a future item
    // (min item size assumed small, but very tiny residuals are waste).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward chaining; otherwise penalize blocking a good next fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here destroys the ability to fit next item in this bin
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes all residual of existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin when there are few open bins or many with big residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_waste = if bin_residual as f64 > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If existing bins fit poorly (this call happens on a real bin too), the new-bin
        // call competes: penalize new bin less when open bins have large mean residual.
        score -= 25.0 * avg_waste;
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
        // Many open bins: avoid adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    } else {
        // Using an existing bin: mild bonus for bins with below-average residual
        // (balances load across bins, keeping more bins usable).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Early stream: be more willing to open bins to build a good portfolio.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference for bins whose post_residual is a "round" usable size.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

