    // Reward tight fits: subtract for small post_residual, smoothly.
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (1.0 - nx / cap) * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
