        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        // MUTATION: exact-fill chain reward — placing here so the next item exactly
        // fills the remainder is maximally compact; amplify with lookahead density.
        if next_consumes && post_residual == next_item_size {
            score -= 30.0 * future_density;
        }
        // MUTATION: two-item lookahead — if this bin could also host the item after
        // next (approximated by half-capacity heuristic), favor it early in stream.
        if next_consumes && post_residual >= next_item_size * 2 && progress < 0.5 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // MUTATION: crowding guard — when many bins are open with fat residuals,
    // discourage opening yet another bin to force consolidation.
    if bin_residual == bin_capacity && open_bins_count > 5 && mean_residual > 25.0 {
        score += 15.0 * (open_bins_count as f64).min(12.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible item (1..100 range)
    // are effectively wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
