pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic discount as post_residual -> 0
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold a plausible small item (min size 1..10 band)
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect bin
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0; // still usable by small items
    } else if post_residual > 60 {
        score += 8.0; // large hole, wasteful placement
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize less if bin will be very full anyway
            score += 3.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, be frugal with open bins; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (mean_residual - post_residual as f64).abs() * 0.5;

    // Global state: many open bins -> prefer consolidation into existing bins
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: empty bin gets a mild penalty so real fits win,
    // but if no open bin fits well (high mean residual mismatch), allow opening.
    if bin_residual == bin_capacity {
        let mismatch = (mean_residual - item_size as f64).abs();
        if mismatch > 25.0 {
            score -= 12.0; // poor fits elsewhere -> open fresh bin
        } else {
            score += 20.0; // decent fits exist -> avoid new bin
        }
    }

    // Small bonus for filling bins above the mean residual (balance control)
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
