            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual >= 8 && post_residual % 8 == 0 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        // NEW: dead-space penalty sharpened by fitting scarcity — a large dead zone in a
        // nearly-unusable bin is worse when few alternatives exist.
        if !next_consumes && dead_ratio > 0.5 && fitting_bins_count >= 2 {
            score += 5.0 * (dead_ratio - 0.5) * (fitting_bins_count.min(6) as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets — small residues are dead space.
    let r = post_residual;
    let cls = r % 10;
    score += (10 - cls) as f64 * 0.6; // residue just below a decade is worse

    // Perfect-fit classes: post_residual divisible by common item sizes
    if r == 0 { score -= 50.0; }
    else if r % 25 == 0 { score -= 8.0; }
    else if r % 20 == 0 { score -= 5.0; }
    else if r % 10 == 0 { score -= 3.0; }

    // Next-item harmonic coupling: can next item land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == r { score -= 40.0; }
        else if next_item_size < r {
            let gap = r - next_item_size;
            let gap_cls = gap % 10;
            score += gap as f64 * 0.3 + (10 - gap_cls) as f64 * 0.2;
            if gap % 25 == 0 { score -= 4.0; }
        } else {
            // next item cannot fit here regardless — mild penalty for hoarding space
            score += 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bin is very full or fit is terrible
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        if tight > 0.7 { score -= 6.0; } else { score += 15.0; }
    }

    // Tight fit reward (integer division threshold on fill fraction)
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 { score -= 10.0; }
    else if fill > 0.75 { score -= 5.0; }

    // Stream progression: late in stream, prefer consolidating into fewer bins
    let prog = step_index as f64 / total_items.max(1) as f64;
    score -= prog * (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
