    // penalize placing into unusually roomy bins unless the fit is very tight.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for using many open bins when plenty of bins fit the item
    // (prefer consolidating into tighter ones via score ordering anyway).
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
