    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Strong reward for tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 18.0;

    // Perfect fit: massive reward for filling a bin exactly.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Penalize dead space too small for typical future items.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Divisibility bonus: residual that can host multiples of common sizes.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Last-chance bonus: only fitting open bin -> strongly prefer it.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 17.0;
    }

    // Lookahead pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0 * (1.0 - progress);
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
