    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * t;

    // New-bin candidate handling: keep it competitive only when current fit is bad
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 12.0 * (1.0 - norm_item) * (1.0 - t);
    }

    score
}

