pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "clean" fractions
    // of capacity are more reusable (e.g. exact halves/quarters/divisors of 100).
    let post = post_residual;
    if post > 0 {
        let reusable = (bin_capacity % post == 0) || (post % 10 == 0) || (post % 25 == 0);
        if reusable {
            score -= 12.0;
        } else {
            // penalize awkward dead space, worse the smaller the residual
            let frac = post as f64 / cap;
            score += 8.0 * (1.0 - frac).powi(2);
        }
    } else {
        // perfect fill: strongly reward
        score -= 40.0;
    }

    // Tight fit reward: item occupies most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * fill_ratio;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            // harmonic class match between next item and post residual
            if post % next_item_size == 0 {
                score -= 10.0;
            }
            score += (post - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += post as f64 * 0.1;
        }
    } else {
        // last item: minimize waste aggressively
        score += post as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 - 5.0 * pressure.min(6.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // reserving a fresh bin for bigger items helps
        }
    }

    // Late in the stream: consolidate, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.3;

    // Mild preference toward bins with below-mean residual (balance preservation)
    score += (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Exact-fill potential with lookahead: if the next item can consume
    // the remaining gap, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap -> gap likely becomes dead space
        score += 12.0;
    }

    // Tightness bonus: fraction of residual consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins when
    // residuals are already low; encourage using existing bins when
    // mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity and no open bin fits well (fitting bins exist but poor).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - 40.0 * size_frac;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 25.0; // one last-chance bin: prefer using it
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (small post_residual)
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits perfectly -> big reward
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here -> penalize dead space
            score += 10.0 + gap * 0.3;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving residuals far below mean (fragmentation) unless tight fit
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: neutral-ish, but allow it when current bin
    // would leave a large unusable residual relative to typical item sizes
    if bin_residual == bin_capacity {
        score = 30.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Early stream: be conservative, prefer fewer bins later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

