pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let nfit = pr / cap;

    // Base: penalize wasted residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: quadratic residual term — small residuals are valuable tight fits
    score += 2.0 * nfit * nfit * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with smooth interaction
    score -= fit * fit * cap * 0.5;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        score = cap as f64 * 1.5 + 20.0 - 15.0 * (avg_waste / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild penalty for bin proliferation late in stream
    score += (open_bins_count as f64).ln() * (0.5 + progress);

    score
}

