pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Modulo classes on post_residual: residuals that divide capacity into
    // common item sizes are reusable; odd dead zones are penalized.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 40.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 30.0;
    }
    if pr >= 1 && pr < 10 {
        score += 25.0; // tiny dead space
    }

    // Coupling with lookahead: reward residuals that can host next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 60.0;
            }
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // unless the current item perfectly pairs with a fresh bin.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * mean_residual;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer tight fits: relative waste penalty.
    score += (post_residual as f64 / cap) * 50.0;

    // Late in the stream, consolidate: favor bins with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - bin_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps less harshly.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: discourage adding to many open bins slightly,
    // but reward using existing bins vs opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: opening a fresh bin is penalized,
    // unless the current bin's post-fit is very poor.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // exact lookahead fit
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to lookahead
        score += 8.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Progress-based tightening: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 40.0;
