    // Reward tight fits relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin bonus: avoid wasting this unique opportunity.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when fit is terrible or no good fit exists.
    if is_new_bin {
        let waste = bin_capacity - item_size;
        score += 30.0 + waste as f64 * 0.4;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;
    if !is_new_bin {
        score -= progress * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
