pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post_residual.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use:
    // small residuals (1..9) are almost unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly favor this bin (chaining good pairs).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            if slack < 10.0 {
                score -= 22.0; // next item chains almost perfectly
            } else {
                score -= 8.0 * (1.0 - slack / cap);
            }
        } else if (post_residual as f64) < nxt && nxt > 0.0 {
            // next item won't fit here after placement; slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is large and global residuals are messy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // Base reluctance to open new bins grows with number of open bins.
        score += 10.0 + 1.5 * open_bins_count as f64;
        // Late in the stream, or with a big item and low mean residual,
        // opening a fresh bin becomes more acceptable.
        score -= 20.0 * item_frac * (0.5 + 0.5 * progress);
        if mean_residual < item_size as f64 {
            score -= 12.0; // existing bins are too full anyway
        }
    } else {
        // Favor bins whose residual is close to the item (minimize leftover).
        let diff = (bin_residual as f64 - item_size as f64) / cap;
        score += 6.0 * diff * diff;
    }

    // Global balance: prefer bins below mean residual when many bins open
    // (keeps residual spread even, preserving future fit options).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev;
    }

    // Mild time-horizon modulation: early stream -> be conservative with
    // near-perfect fits for small items (save space); late -> fill greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size <= 30 {
        score -= 8.0 * (1.0 - progress) * tightness;
    } else {
        score -= 6.0 * progress * tightness;
    }

    score
}

