pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth coupling: large post_residual is worse late in the stream.
    score += 12.0 * progress * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 20.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let closeness = 1.0 - (pr - nx).abs() / cap;
        score -= 8.0 * fits_next * closeness * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * fragmentation * (1.0 - progress);
    }

    score
}

