pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual into capacity-decile classes.
    // Small residuals (< 10, minimum item size) are dead space -> penalize.
    let class = post_residual / 10;
    match class {
        0 => score += 60.0,            // unusable dead space (if min item > 1)
        1 => score += 25.0,            // only tiny items fit
        2 => score += 10.0,
        3 => score += 4.0,
        4 => score += 1.0,
        5 => score -= 1.0,             // half-full: versatile
        6 => score -= 2.0,
        7 => score -= 2.5,
        8 => score -= 3.0,
        _ => score -= 3.5,             // mostly empty
    }

    // Modulo arithmetic on residual vs. common item sizes: reward residuals
    // that are multiples of small harmonic units (10, 20, 25, 50).
    if post_residual % 50 == 0 && post_residual > 0 { score -= 6.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 3.0; }
    else if post_residual % 20 == 0 && post_residual > 0 { score -= 2.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 1.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward leaving a harmonic residual for the next item
            score -= (next_post / 10) as f64 * 1.5;
            if next_post < 10 && next_post > 0 { score += 8.0; }
        } else {
            // next item cannot use this bin's leftover: slight penalty for waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded
    // or the fit would be terrible.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if poor_fit && crowd > 2.0 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 50.0; // discourage opening new bins by default
        }
    }

    // Mild preference for filling bins below mean residual (balance avoidance
    // of many half-empty bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is too small to hold even the smallest item (1).
    // We treat gaps below a tight threshold as wasted capacity.
    let dead_threshold = 4.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // strong penalty for leaving a nearly-full but useless sliver
    }

    // Penalize mid-range dead space that is unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score += tightness * 12.0;

    // Pressure from number of open bins: discourage spreading across too many bins.
    score += (open_bins_count as f64) * 1.5;

    // If this is the only bin that fits, strongly prefer using it (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 15.0;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty if gap is dead.
        if (post_residual as u64) < (next_item_size as u64) && post_residual < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win if current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More expensive to open new bins when many are already open.
        score += (open_bins_count as f64) * 0.8;
        // If no open bin fits, new bin becomes attractive (handled by fitting_bins_count==0 case implicitly).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below mean (tighter bins).
    score += ((mean_residual - bin_residual as f64) * 0.3).max(-10.0).min(10.0);

