    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits into the post_residual,
    // heavily reward this placement (perfect chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_tightness = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 15.0 + 25.0 * next_fit_tightness;
    } else if next_item_size > 0 {
        // Penalize placements that strand a residual the next item cannot use.
        let gap = (next_item_size - post_residual) as f64;
        score += 5.0 + gap * 0.3;
    }

    // Relative to mean residual: prefer bins whose residual is near/below the mean
    // (consolidating space) rather than scattering into large-residual bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.4 * rel;

    // Penalize creating unusable dead space (< 10, smallest possible item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference to fill older/more crowded bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild superlinear penalty
    // on large leftover space so that "almost full" bins are strongly favored.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powf(1.7) * bin_capacity as f64;

    // Dead-space penalty: residuals that are too small to ever hold a typical item
    // (below the minimum plausible item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize bins that would strand the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 25.0 * (nx / 100.0);
        } else {
            score += 15.0 + 0.5 * (nx - post_residual as f64);
        }
        // Bonus if post_residual exactly accommodates next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        score += 0.2 * pr; // dampen if the fit is still wasteful
    }

    // Global pressure: many open bins with large mean residual → consolidate;
    // few open bins or low mean residual → opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln1p() * (mean_residual / bin_capacity as f64);
    score += 8.0 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Make opening a new bin attractive only when no good fit exists: add a fixed
    // opening cost that tight fits elsewhere easily overcome.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, slightly discourage spawning extra bins.
        score += 20.0 * progress;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the fleet mean
    // to keep residual distribution balanced.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Small deterministic tie-breaker based on bin fullness to break symmetric scores.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

