    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let scarcity = (1.0 - mean_norm).clamp(0.0, 1.0);
    let item_norm = (item / cap).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Perfect fits are highly rewarded.
    if post <= 0.0 {
        score -= 10.0 + 6.0 * item_norm;
    } else {
        // Strict penalty for small nonzero "dead" gaps.
        let dead_line = (3.0 + 0.07 * cap) * (0.85 + 0.30 * item_norm);
        if post < dead_line {
            let tight = (dead_line - post) / dead_line;
            let preserved_value = if is_new_bin {
                0.20
            } else {
                (before / cap).clamp(0.0, 1.0) * (0.65 + 0.45 * scarcity)
            };
            score += (20.0 * tight * tight + 6.0 * tight)
                * (0.45 + preserved_value)
                * (1.0 + 0.035 * open);
        }
    }

    // Lookahead: reward leftovers that remain useful for the next item,
    // penalize gaps too small for it.
    if next > 0.0 {
        if post + 1.0 <= next {
            score -= 0.8 + 0.03 * next;
            if post == next {
                score -= 2.0;
            }
        } else {
            let missing = next - post;
            score += 0.25 * missing + 1.2;

            if !is_new_bin && before >= next {
                score += 0.15 * missing
                    * (before / cap).clamp(0.0, 1.0)
                    * (0.45 + 0.75 * scarcity);
            }
        }
    } else {
        // Last item: opening a new bin is almost never justified.
        if is_new_bin {
            score += 28.0 + 2.0 * open + 12.0 * progress;
        } else {
            score -= 7.0 + 0.30 * open;
        }
    }

    if is_new_bin {
        if fitting < 0.5 {
            // No open bin can fit the item: the new bin is mandatory.
            score -= 1000.0;
        } else {
            let alternative_pressure = 1.1 * (fitting - 1.0).max(0.0);
            let mut pressure = (3.5 + 0.60 * open + 7.0 * progress + alternative_pressure)
                * (0.55 + 0.70 * mean_norm);

            // Slightly relax pressure when this would override the only fitting bin.
            if fitting < 1.5 {
                pressure *= 0.85;
            }

            score += pressure;
        }
    } else if fitting < 1.5 {
        // Last-chance open bin, but reward is reduced if it would create dead space.
        let useful_left = if next <= 0.0 {
            0.0
        } else if post + 0.5 >= next {
            1.0
        } else {
            (post / next).clamp(0.0, 1.0)
        };

        score -= (4.0 + 0.25 * open + 4.0 * progress) * (0.35 + 0.65 * useful_left);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let post = post_residual;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post;

    // Perfect closure dominates.
    if post == 0 {
        score -= 500.0;
    } else if post <= 4 {
        score -= 220.0;
    } else if post < 10 && !next_consumes {
        score += 50.0 + 0.7 * post as f64;
    }

    // Harmonic classes.
    if post > 0 && post % 10 == 0 {
        score -= 8.0;
    } else if post > 0 && post % 25 == 0 {
        score -= 5.0;
    }

    // Dead space relative to item size.
    if post > 0 && post < item_size.min(80) {
        score += 35.0 + 0.5 * post as f64;
    }

    // Slot bonus: multiples of 10 leave reusable space.
    let slots = post / 10;
    score -= 4.0 * slots as f64;

    // Lookahead coupling.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 400.0;
        } else if next_consumes {
            let slack = (post - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 60.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 30.0;
            }
            if post >= next_item_size * 2 {
                score -= 50.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 12.0;
            }
        } else {
            let waste = (next_item_size - post) as f64;
            score += 0.5 * waste;
            if waste > bin_residual as f64 {
                score += 25.0;
            }
        }
    }

    // Small-post dead zone unless next item consumes it.
    if post > 0 && post < 20 {
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += (20.0 - post as f64) * (1.4 - future_help);
    }

    // Mean residual alignment.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Fitting-bin scarcity.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 18.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 28.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 35.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 18.0 * (1.0 - progress);
        }
    } else {
        if post > 0 && next_item_size > post && next_item_size <= bin_residual {
            score += 20.0 * (1.0 - progress);
        }
        if post > 0 && post == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 12.0;
        }
        if post > 0 && next_item_size > 0 && post >= item_size + next_item_size && post - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    // Dead ratio penalties.
    if post > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        let stranded = post as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post {
            score += 12.0 * stranded * (1.2 - progress);
