        // Slight preference for using existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
