        // Chain potential: next item fits exactly after this one.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving dead space that cannot fit the next item.
        if post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative residual context: prefer bins tighter than the mean.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
