        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to the bin or no good fit exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 + 120.0 * (1.0 - frac);
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 100.0; // fresh bin sets up a great next fit
        }
    }

    // Late in stream: consolidate harder to avoid many tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, prefer tight fills more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize large post-residual non-linearly (dead space is quadratic bad).
    score += 0.015 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how snugly the next item fits the leftover.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= (1.0 + 2.0 * progress) * snug;
        } else {
            // Penalize stranding the next item if nothing else could fit it.
            score += 0.5 * (next_item_size as f64 - post_residual as f64) * progress;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 + 4.0 * progress;
    }

    // Many open bins: discourage spreading; few open bins: allow spreading.
    if open_bins_count > 4 {
        score += 0.1 * (open_bins_count as f64).ln();
    }

    // Global mean residual: prefer bins close to the mean (balanced packing),
    // penalize outliers relative to the fleet.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere or
    // the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let gap_after = bin_capacity - item_size;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 2.0 };
        // Base new-bin score: post_residual (= capacity - item) plus penalty
        // for abandoning existing fitting bins, relaxed early in the stream.
        score = post_residual as f64 + pressure * (1.0 + 2.0 * (1.0 - progress))
            + 0.02 * gap_after as f64;
        // If the leftover after this item matches the next item, new bin is great.
        if next_item_size > 0 && gap_after >= next_item_size {
            score -= 1.5 * (gap_after - next_item_size) as f64 / bin_capacity as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Strong reward for tight fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 18.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 4 {
        score -= 210.0;
    }

    // Penalize dead space too small for typical future items.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 52.0 + 0.7 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bonus: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 440.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 115.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 70.0;
            }
            // Discourage mid-slack waste that no typical item can fill.
            if slack > 7.0 && slack < 14.0 {
                score += 30.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0 * (1.0 - progress);
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 16.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            if waste > bin_residual as f64 {
                score += 26.0;
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 42.0 - 10.0 * progress;
        score -= crowding * 0.5;
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 8.0;
        }
        // If open bins have plenty of room for item + lookahead, discourage new bin.
        if next_item_size > 0 && mean_residual >= (item_size + next_item_size) as f64 * 0.9 {
            score += 28.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        // Opening a bin that can host both this and the next item is valuable.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
        // If open bins are nearly exhausted for the next item, opening fresh helps.
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 35.0 * (1.0 - progress);
        }
    } else {
        // Keep large residuals usable for the big lookahead item.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 20.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual >= item_size.max(next_item_size)
            && post_residual < item_size.max(next_item_size) + 6 {
            score -= 14.0 * (1.0 - progress);
        }
        // Reward bins whose post-residual exactly fits next item with minimal slack.
        if next_consumes && post_residual - next_item_size <= 2 && fitting_bins_count <= 3 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Slight preference for using more filled bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Early-stream exploration.
    if open_bins_count < 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Stranded residual penalty late in the stream.
    if next_item_size == 0 || next_item_size > post_residual {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual > 0 && post_residual < 25 {
            score += 10.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Dead-ratio penalty: bins left with large unusable fraction.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
