    // Lookahead coupling: prefer bins whose post residual fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 5.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }
    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
