        if pr % 3 == 0 { score -= 5.0; }
        if pr % 7 == 0 { score -= 4.0; }
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0; // perfect chain
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.8; // tighter is better
        } else {
            score += 20.0; // next item can't use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

