            score -= 8.0;
        }
        // Open bins have room for item and lookahead -> discourage new bin.
        if next_item_size > 0 && mean_residual >= (item_size + next_item_size) as f64 * 0.9 {
            score += 28.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 20.0;
        }
        if open_bins_count > 3 && mean_residual < next_item_size as f64 * 0.9 {
            score -= 32.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 {
            score += 18.0 * fitting_bins_count as f64;
        }
    } else {
        // Keep large residuals usable for the big lookahead item.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual >= item_size.max(next_item_size)
            && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        // Pairing item + next exactly into residual.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 12.0;
        }
    }

    // Mild preference for bins below mean residual.
    score += (mean_residual - bin_residual as f64) * 0.085;

    // Slight preference for using more-filled bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Early-stream exploration.
    if open_bins_count < 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Stranded residual penalty late in the stream.
    if next_item_size == 0 || next_item_size > post_residual {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual > 0 && post_residual < 25 {
            score += 10.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Dead-ratio penalties on remaining space.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to host typical items are wasted.
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits relative to bin residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 20.0;
    }

    // Lookahead: bonus if next item fits into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
