pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if nxt <= post {
            // next item fits here: reward proportional to how well it fills remaining space
            score -= 15.0 * (nxt / post.max(1.0));
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 8.0 * (post / cap);
        }
    }

    // Prefer bins whose residual deviates from the mean (tight packing diversity)
    let dev = (post - mean_residual).abs();
    score -= 3.0 * (1.0 - dev / cap.max(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (item_size as f64 / cap);
    }

    // Early in stream: slightly favor consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect fit is nearly free.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward if the next item fits in the post residual (k=2 chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            // Penalize leaving a residual that just barely misses the next item.
            let miss = (next_item_size as f64) - (post_residual as f64);
            if miss < 15.0 {
                score += 0.6 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: when many bins are open, prefer consolidation (lower mean residual bins).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        // Favor bins with residual below the mean (more filled bins).
        score += 6.0 * dev;
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prioritize tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (item fills well or all fits are terrible).
    if bin_residual == bin_capacity {
        let fill_ratio = (item_size as f64) / cap;
        let base_new = 55.0 - 25.0 * fill_ratio;
        // If only this new bin fits, it must win.
        if fitting_bins_count == 0 {
            score = base_new - 40.0;
        } else {
            // Escalate cost of opening a new bin as more bins could fit.
            score = base_new + 12.0 * (fitting_bins_count as f64);
            // Late in stream, opening new bins is cheaper than fragmenting.
            score -= 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
