pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * 2.0;
    score += poly * cap * 0.35;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (8.0 + 12.0 * progress);

    // Penalize dead space that no typical item can use
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (pr - nx) / cap;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    score
}

