pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes that are "dead zones"
    // (very small leftovers) should be heavily penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit: best possible outcome
    } else if pr < 5 {
        score += 40.0; // nearly-full but wasted sliver
    } else if pr < 10 {
        score += 20.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are
    // more reusable. Harmonic buckets of width 10.
    let bucket = (pr / 10) as f64;
    score -= bucket * 2.0; // reward larger, more usable residual buckets

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: residual likely dead if small
            if (next_item_size as f64) > score + pr as f64 {
                score += 5.0;
            }
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // penalize opening a new bin for small items
        score += 60.0 * (1.0 - fill_frac);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // pairing potential in a fresh bin
            score -= 10.0 * ((bin_capacity - item_size - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fits).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
    }

    // Progress-based modulation: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (pr == 0) as i32 as f64;

    // Slight penalty for spreading across many open bins when mean residual is high.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 2.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are unusable; exact fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 45.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Lookahead: reward if next item fits the post-residual gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 8.0; // gap likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage opening new ones.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: make it mildly unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins tighter than average residual.
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match leaves zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small unusable residuals (dead space below minimum item size 1..100).
        if post_residual < 10 {
            score += 25.0;
        }
        // 2-step lookahead: reward when next item fits the residual exactly or nearly.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 40.0;
            } else if next_item_size < post_residual {
                let slack = (post_residual - next_item_size) as f64;
                // Reward tight 2-step fits, scaled by how tight the chain is.
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            } else {
