                let waste = (next_item_size - post_residual) as f64;
                score += 5.0 + 0.3 * waste.min(50.0);
            }
        }
    }

    // Compare residual to mean residual across open bins:
    // prefer bins that are already relatively full (small residual) to consolidate.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer using open bins over opening new ones: penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If next item is large and no tight fit exists, opening a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidation matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

