pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Detect brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if is_new_bin {
        // Opening a new bin is generally costly: apply a strong penalty so we only
        // open when no existing bin offers a decent fit.
        score += 40.0 + 30.0 * (1.0 - progress);

        // If the item is large relative to capacity, a fresh bin is more acceptable
        // (big items waste less when placed alone).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * size_frac * size_frac;
    } else {
        // Reward tight fits: small post_residual already favored by base term.
        // Extra reward for near-perfect packing.
        if post_residual == 0 {
            score -= 15.0;
        } else if post_residual <= 5 {
            score -= 8.0;
        }

        // Last-chance bonus: if this is the only bin that fits, strongly prefer it
        // over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else if fitting_bins_count == 2 {
            score -= 6.0;
        }

        // Lookahead: if the next item fits exactly in the post residual, reward;
        // if the next item would fit but barely, slight reward too.
        if next_item_size > 0 {
            let next_fits = next_item_size <= post_residual;
            if next_fits {
                let slack = post_residual - next_item_size;
                if slack == 0 {
                    score -= 12.0;
                } else if slack <= 10 {
                    score -= 4.0;
                } else {
                    score -= 1.0;
                }
            } else {
                // Next item won't fit here; mildly penalize leaving a residual that
                // is too small to be useful for typical items.
                if post_residual < 10 {
                    score += 5.0 * (1.0 - progress);
                }
            }
        }

        // Global state coupling: if mean residual across open bins is already low,
        // preserving tight bins matters more; penalize wasting space in a tight fleet.
        let tight_fleet = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 * tight_fleet * (post_residual as f64 / bin_capacity as f64);

        // Many open bins: prefer consolidating into existing bins rather than
        // letting the fleet sprawl (implicitly discourages new-bin behavior which
        // is handled above, but also favors bins that reduce fragmentation).
        if open_bins_count > 4 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;
    let cap = bin_capacity as f64;

    // Tightness reward.
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness) * 18.0;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Penalize dead slivers too small for typical future items.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward leaving residuals that are multiples of a common chunk size.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Last-chance bonus.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // Lookahead pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 5.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Dead-sliver penalty scaled by future usefulness.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Mild preference for bins below mean residual.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / cap;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Tightness reward.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 18.0;

    // Perfect / near-perfect fit.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 4 {
        score -= 220.0;
    }

    // Dead-space penalties for unusable slivers.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Dead-sliver penalty scaled by future density.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help) * (0.5 + 0.5 * future_density);
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 440.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 115.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 68.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0 * (1.0 - progress);
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 26.0;
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 35.0 + 15.0 * progress;
        score -= crowding * 0.5;
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 8.0;
        }
        if next_item_size > 0 && mean_residual >= (item_size + next_item_size) as f64 * 0.9 {
            score += 25.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
        if open_bins_count > 2 && mean_residual < next_item_size as f64 * 0.9 {
            score -= 35.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 2 {
            score += 18.0 * fitting_bins_count as f64 * (0.5 + progress);
        }
    } else {
        // Keep large residuals usable for the big lookahead item.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 20.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual >= item_size.max(next_item_size)
            && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins below mean residual.
    score += (mean_residual - bin_residual as f64) * 0.085;

    // Slight preference for more filled bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Early-stream exploration.
    if open_bins_count < 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Stranded residual penalty.
    if next_item_size == 0 || next_item_size > post_residual {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual > 0 && post_residual < 25 {
            score += 10.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Dead-ratio shaping.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 6.0 * (dead_ratio - 0.75) * (1.0 - progress);
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress) - 12.0 * progress * fit_norm * (1.0 - fit_norm);

    // Reward tight fits (small post_residual relative to capacity)
    score -= 10.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 + progress);
        } else {
            score -= 4.0 * (pr / nxt - 1.0).min(1.0) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it only when post_residual is large relative to mean residual
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (mean_residual / cap).min(1.0);
    }

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes.
    let class = post_residual / 10;
    // Dead space penalty grows superlinearly for small unusable fragments.
    if post_residual < 10 {
        score += 60.0;
    } else {
        score += (10 - class as f64) * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Compatibility with the lookahead item: if the next item fits exactly
    // into the post residual, this is an excellent pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Reward proportional leftover usefulness, penalize awkward slivers.
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 {
                score += 15.0;
            } else {
                score -= (nxt_post / 10) as f64 * 4.0;
            }
        } else {
            // Next item cannot fit here; residual likely becomes dead space.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer fuller bins overall: compare residual to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Mild encouragement to open new bins early when many bins are open
    // and residuals are fragmented (avoid spreading too thin).
    if open_bins_count > 8 && post_residual > 40 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Slight stream-progression pressure: as the stream advances, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: neutral baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest
    // plausible item (min size 1, but small gaps < ~15 are hard to fill).
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    // Perfect fit: full reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted space for next arrival).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward a bin that can also host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.2;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; with few bins, new bins are cheap.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when
    // existing bins have genuinely bad fits, scaled by how bad fits are.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Mild stream progression: late in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
