pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leave as little dead space as possible.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 250.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly or closely
    // match the next item size (this bin becomes reusable next step).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 400.0;
        } else if diff <= 5.0 {
            score -= 150.0 - diff * 10.0;
        } else {
            score += diff * 0.5;
        }
        // Penalize leaving a gap the next item cannot use at all.
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is above/below
    // the mean depending on what keeps the residual distribution tight.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no open bin fits well (post_residual huge waste otherwise).
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        // A fresh bin's residual after placement is compared to mean residual:
        // open a new bin only if existing bins are too fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.4 {
            score += 600.0; // existing bins are roomy enough; don't open new
        } else if waste < 20.0 {
            score -= 200.0; // large item: a fresh bin is fine
        } else {
            score += 100.0 * (waste / bin_capacity as f64);
        }
        // Late in the stream, avoid opening new bins with big dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild preference for tighter bins among equals.
    score += (bin_residual as f64) * 0.05;

    score
}

