pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks for mid-range residuals, small for tiny/huge residuals
    score -= 12.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as the stream progresses
    score += progress * x * x * cap * 0.3;

    // Reward tight fits (small post residual) with smooth quadratic term
    score -= (1.0 - x) * (1.0 - x) * item_size as f64 * 0.25;

    // Last-chance bin: strong smooth reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward bins whose post residual matches the next item size smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 6.0 * (-diff * diff * 40.0).exp();
        // Penalize leaving residual just below next item size (unusable sliver)
        if pr < nx {
            score += 3.0 * progress * (nx - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins close to mean (balance), smooth Gaussian
    let md = (pr - mean_residual) / cap;
    score += 2.0 * md * md;

    // Mild penalty for spreading across too many bins late in stream
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
