pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions
    let post_frac = post_residual as f64 / cap;
    let post_class = (post_frac * 10.0).floor(); // 0..10 integer class

    // Reward tiny post-residuals (near-perfect fits) with a strong non-linear bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_class <= 1.0 {
        score -= 12.0;
    }

    // Penalize dead space that is unusable for typical item sizes:
    // residual classes in (0, 10] and (10, 20] are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes (10, 20, 25, 50)
    // are "harmonic" and likely to be filled exactly by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / cap;
            let nxt_class = (nxt_frac * 10.0).floor();
            // Harmonic match between next-item class and post-residual class
            if nxt_class >= post_class {
                score -= 18.0;
            } else {
                score += (post_class - nxt_class) * 2.0;
            }
        } else {
            // Next item cannot use this bin's remainder; dead space likely persists
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // decent fits exist, but allow it if the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        let mean_use = 1.0 - mean_residual / cap;
        // open new bin if item is large and open bins are already crowded
        score += 15.0 - 20.0 * pressure + 10.0 * mean_use;
        // early in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
    }

    // Mild preference for tighter (fuller) bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Penalize spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are essentially unusable -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10.min(bin_capacity) {
        score += 200.0;
    }
    // Dead space that cannot fit the lookahead item is partially wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, new bins ok.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual + 20.0 * progress;
        // But if this bin is a poor fit elsewhere, allow escape: new bin looks better
        // when post_residual here would be tiny dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    } else {
        score += 0.5 * pressure * (1.0 - progress);
    }

    score
}

