pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the leftover exactly matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            // Perfect chain: next item fills this bin completely afterwards
            score -= 60.0;
        } else {
            // Closer match to next item is better
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space creation
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins tightened toward the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.2;

    // Mild penalty on opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space avoidance: small unusable gaps heavily penalized,
    // but softened if the lookahead item can consume the gap.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 50.0 + 0.8 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 38.0 + 0.5 * post_residual as f64;
    }

    // Exact lookahead match: near-perfect chaining.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 420.0;
    } else if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        // Reward hosting the next item, scaled by how tight the leftover is.
        score -= 110.0 * (1.0 - slack / bin_capacity.max(1) as f64);
        if slack > 0.0 && slack <= 7.0 {
            score -= 65.0;
        }
        if slack > 0.0 && slack < 12.0 {
            score += 34.0;
        }
        if post_residual >= next_item_size * 2 {
            score -= 55.0;
        }
        if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.55 * waste;
        if waste > bin_residual as f64 {
            score += 26.0;
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 22.0;

    // Consolidation pressure: many open bins => prefer existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 15.0;
    }

    // New-bin candidate: penalize scaled by alternatives and stream progress;
    // only open a new bin when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 + 18.0 * progress + mean_residual * 0.25;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
    }

    // Late in the stream, waste hurts more.
    score += post_residual as f64 * 0.5 * progress;

    // Stranded-space pressure when the gap is unusable for the lookahead.
    let stranded = post_residual as f64 / bin_capacity.max(1) as f64;
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 10.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Mean-residual anchoring: prefer bins whose leftover tracks the fleet average.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Two-item chain: bin can host current + next with near-zero leftover.
    if post_residual > 0 && next_item_size > 0
        && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size <= 3 {
        score -= 22.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively as stream progresses.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * (0.3 + 0.7 * t) / bin_capacity as f64 * 20.0;

    // Penalize dead space that is too small for likely future items.
    let dead_zone = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.1;
        } else {
            score += 4.0;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins
    // are fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 10.0
            + open_bins_count as f64 * 0.5
            - if post_residual >= next_item_size && next_item_size > 0 { 12.0 } else { 0.0 }
            + fragmentation * 0.2;
    }

    // Global pressure: many open bins with high mean residual -> discourage
    // leaving large residuals behind (consolidate).
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual - item_size) as f64).powf(1.3) * 0.05;

    // Early-stream exploration: tolerate looser fits early to keep options open.
    score *= 1.0 - 0.15 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), weighted by progress
    let mut score = pr * (1.0 + progress * (pr / cap)) + norm_pr * norm_pr * 40.0;

    // Smooth polynomial coupling: residual quality interacts with stream progress
    let fit_quality = 1.0 - norm_pr;
    score -= fit_quality * fit_quality * (1.0 - progress) * 25.0;
    score += fit_quality * fit_quality * fit_quality * progress * 30.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-misses
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 + (-gap / cap) * 20.0;
        }
    }

    // Penalize bins far from mean residual (fragmentation pressure)
    score += ((pr - mean_residual) / cap).abs() * 12.0;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: prefer opening a new bin early or when fit is terrible
    if bin_residual == bin_capacity {
        score -= 20.0 + 30.0 * (1.0 - progress) * fit_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect and near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space penalty: tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 50.0 + 0.7 * post_residual as f64;
    }

    // Lookahead: exact fit for the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 420.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 65.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 35.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 26.0;
            }
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 22.0;

    // Consolidation pressure with many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize proportionally to how many alternatives exist.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 18.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 28.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
    }

    // Dead-ratio penalty scaled by remaining stream.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by small integers is more "usable"
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 2 == 0 { score -= 2.0; }
        else { score += 4.0; } // odd residuals are awkward

        // Integer-division thresholds: very small unusable slivers are dead space
        if pr < 10 {
            score += 25.0; // sliver below min item size is wasted
        } else if pr < 20 {
            score += 8.0;
        } else if pr <= 30 {
            score -= 4.0; // sweet zone: fits small items exactly
        }

        // Fraction-of-capacity classes of post_residual
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.5 { score -= 5.0; }
        else if frac < 0.1 { score += 10.0; }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic bonus: post_residual % next_item_size == 0
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (few fitting bins, high mean residual waste)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin anyway
        } else {
            // penalize new bin when decent fits exist; scale with open bins
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        }
    }

    // Mild preference to fill bins with low residual relative to mean
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

