            score -= 0.35 * pr;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer tighter bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (bin_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to residuals) or the item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let best_gap = (mean_residual - item_size as f64).max(0.0);
        // Penalize opening new bins normally; discount when open bins fit poorly.
        score += 50.0 - 40.0 * (best_gap / 30.0).min(1.0) + 30.0 * fill;
        // Lookahead: if next item is large, a fresh bin is less attractive.
        if next_item_size > 0 {
            score += 0.15 * next_item_size as f64;
        }
    } else {
        // Lookahead synergy: reward bins whose post_residual can host next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Mild stream-progression term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
