pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer minimal post-residual, with a non-linear (quadratic) penalty
    // on wasted space that grows with stream progress (late in the stream,
    // dead space is more costly since fewer items remain to fill it).
    let mut score = pr + 30.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: when post_residual is small relative to capacity,
    // subtract a smooth non-linear bonus.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead coupling: if the next item could exactly fill the post-residual,
    // reward strongly (smooth Gaussian-like coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap * gap / 200.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // Discourage spreading across many open bins when mean residual is large:
    // prefer bins below the mean residual (tighter bins) via smooth coupling.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // Mild penalty for opening a brand-new empty bin when other bins fit,
    // scaled by how much of the item fills the new bin.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in a "usable"
    // class (multiples of 10, or >= 10) are rewarded; tiny dead space penalized.
    let pr = post_residual;
    if pr > 0 {
        let dead = if pr < 10 { 40.0 } else { 0.0 };
        score += dead;
        // class reward: residual divisible by 10 is reusable by typical items
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // integer-division thresholds: big chunks are attractive
        let chunk = pr / 20; // 0..5
        score -= chunk as f64 * 3.0;
    } else {
        // perfect fit
        score -= 60.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // fits, but not perfectly: mild reward scaled by tightness
            let tight = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 + 15.0 * tight;
        } else {
            // next item won't fit here: penalize small leftovers more
            let waste = (next_item_size - pr) as f64;
            score += 5.0 + waste.min(30.0) * 0.3;
        }
        // harmonic class match: next item size class equals post_residual class
        if pr > 0 && (next_item_size % 10) == (pr % 10) && next_item_size <= pr {
            score -= 6.0;
        }
    } else {
        // last item: prefer tightest fill overall
        score -= 20.0;
    }

    // Capacity fraction term: reward filling bin close to capacity
    let fill_frac = (bin_residual - item_size.min(bin_residual)) as f64 / cap;
    score -= 25.0 * (1.0 - fill_frac) * (1.0 - fill_frac);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when all open bins would leave heavy dead space.
    if bin_residual == bin_capacity {
        let spread = mean_residual - score;
        score += 12.0 + (mean_residual * 0.15);
        if mean_residual < 15.0 {
            score -= 10.0; // open bins are nearly full anyway -> new bin fine
        }
        let _ = spread;
    } else {
        // prefer bins with below-mean residual (use up emptier bins first)
        score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.4;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Many open bins: encourage closing them out (tight fits preferred).
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits via post_residual, but with a dead-space twist.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead space: residuals that are too small to be useful (below min item size 1..~10)
    // are worthless; penalize them heavily. Usable residuals are mildly penalized
    // proportionally to waste.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty proportional to wasted space.
        score += 30.0 + pr * 2.0;
    } else {
        // Usable residual: mild waste penalty, superlinear to avoid many mid-gaps.
        score += (pr * pr) / cap;
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 10.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate gets penalized), encouraging consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + (open_bins_count as f64) * 2.0 + progress * 10.0;
        // If residual after placing in an existing bin is still usable, new bin is bad.
        if post_residual < bin_residual {
            score += 10.0;
        }
    } else {
        // Existing bins get a small open-count pressure to prefer fuller bins.
        score += (open_bins_count as f64) * 0.2;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
        // Extra reward if next item nearly fills the leftover (chain of tight fits).
        let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= chain_tightness * 5.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Leftover can't host next item: mild penalty unless it's near zero.
        if post_residual > 0 {
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), gently steering toward bin consolidation.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    score
}

