pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: exact match of next item into post_residual is ideal.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize wasting residual.
        score += 6.0 + 0.05 * post_residual as f64;
    } else if next_item_size == 0 {
        // Last item: prefer filling as much as possible.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean bonus: below-average residual is a good target.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Mild penalty for scattering across many open bins.
    score += 0.15 * open_bins_count as f64;

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep neutral baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward residuals with many useful slots.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 5.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Small-sliver penalty softened when next item fits.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Deviation from mean residual.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Fine-grained residual shaping.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize small dead space that nothing (min item ~1) can use later;
    // dead space is worse when it's tiny but nonzero.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Wasted residual relative to next item's needs.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into
    // already-open bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 10.0 + 2.5 * (open_bins_count as f64);
        // Opening a new bin is more attractive early in the stream
        // (long horizon ahead amortizes the bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // Don't open a new bin for a large item if existing bins fit it well.
        if bin_residual >= item_size && (item_size as f64) < 0.7 * (bin_capacity as f64) {
            score += 5.0;
        }
    } else {
        // Existing bin: slight preference when it's below-average residual
        // (keeps bins balanced, avoids fragmenting one bin while others fill).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins harder (penalize leaving big residuals).
    if open_bins_count > 3 {
        score += 0.04 * post_residual as f64 * (open_bins_count as f64).ln().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: penalize large residuals more as the stream progresses
    score += pr * pr * (1.0 + 60.0 * progress);

    // Reward tight fits with a smooth cubic term
    score -= (1.0 - pr) * (1.0 - pr) * (1.0 - pr) * 12.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr);
    }

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr * bin_capacity as f64 {
            score -= 8.0 * (1.0 - pr * bin_capacity as f64 / 100.0).abs() * 0.0
                     + 6.0 * (pr * bin_capacity as f64 - nx) / 100.0;
        } else {
            score += 5.0 * (nx - pr * bin_capacity as f64) / 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64 - pr).abs();

    // New-bin candidate penalty: prefer filling existing bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues in the "usable band" (multiples
    // of small item sizes) are more valuable than odd dead space.
    let band = post_residual % 10;
    let band_penalty = match band {
        0 => -6.0,               // perfectly reusable residue
        1 | 2 | 3 => 2.0,        // sliver, likely dead space
        4 | 5 | 6 => 0.0,        // neutral mid band
        7 | 8 | 9 => 1.5,        // awkward residue
        _ => 0.0,
    };
    score += band_penalty;

    // Strongly reward near-perfect fits (harmonic closure of the bin).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Reward tight packing measured in integer-division thresholds.
    let fill_class = post_residual / 10; // 0..=9
    score += fill_class as f64 * 1.2;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 3.0;
        } else {
            // next item won't fit here; slight penalty if residual becomes waste
            score += 2.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large and would leave a poor residue elsewhere (dead-space avoidance).
    if bin_residual == bin_capacity {
        let base = post + 8.0; // default: prefer existing bins
        // If the item is large (> 60), placing it in a fresh bin preserves
        // flexibility of small residuals in existing bins.
        let large_bonus = if item_size > 60 { 10.0 } else { 0.0 };
        // If many open bins have plenty of mean residual, opening new bins is wasteful.
        let crowd = (open_bins_count as f64) * 0.3;
        score = base - large_bonus + crowd;
        // If no other bin fits at all, this call is effectively the only option;
        // fitting_bins_count==1 with empty bin means it's fine.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Slight time-dependent tightening: later in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Mean-residual coupling: if open bins are already loose, penalize loose placements.
    score += (mean_residual - post).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
