pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps in the awkward band 10..=25 are rarely reusable; scale penalty.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0 + (25.0 - post_residual as f64) * 0.8;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage scattering when many bins are already open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0
            && (post_residual as i64 - next_item_size as i64) < 10
        {
            // Sets up an unusable sliver for the next item -> penalize.
            score += 20.0;
        }
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item, or no bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 && mean_gap < 20.0 {
            // Open bins fit reasonably well -> discourage new bin.
            score += 15.0;
        } else {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild aversion to leaving residual far below the mean (fragmenting).
    if (mean_residual - post_residual as f64).abs() > 40.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with next item is highly desirable ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big reward (subtract heavily)
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Reward closeness to next item size, scaled by relative gap
            let rel = diff / (next_item_size.max(1) as f64);
            score += rel * 25.0;
            // Penalize residuals too small for next item (dead space trap)
            if (post_residual as i64) < (next_item_size as i64) {
                score += 12.0 + diff * 0.5;
            }
        }
    }

    // --- Tight fit reward: small post residual is good ---
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for bins with less residual among many candidates
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // --- New bin candidate: penalize opening a new bin unless current bin wastes a lot ---
    if bin_residual == bin_capacity && item_size > 0 {
        // Fresh bin: score equals wasted space for this item (item_size residual is implicit)
        score = (bin_capacity - item_size) as f64;
        // Prefer opening a new bin when existing bins would leave huge dead space
        // and when many bins are already open (fragmentation pressure)
        if next_item_size > 0 && (post_residual as i64) < (next_item_size as i64) {
            score -= 10.0;
        }
        score += open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    } else {
        // Existing bin usage slightly favored as stream progresses
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
