    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 420.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 65.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 34.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
