    score *= 1.0 + 0.5 * progress * norm_post;

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 10.0 * (fitting_bins_count as f64).min(5.0);
        // If many bins already open and mean residual is low, opening new bin is less attractive.
        score += 0.05 * open_bins_count as f64;
    } else {
        // Reward using an existing bin, more so if it's the only fitting bin (last chance).
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
