    let mut class_bonus = 0.0;
    for &d in &[0u32, 10, 20, 25, 30, 40, 50, 60, 75, 80] {
        if post_residual == d {
            class_bonus = 18.0;
        }
    }
    score -= class_bonus;

    // Modulo penalty: residual that wastes awkward remainders (mod 10 in 1..9)
    let m = post_residual % 10;
    if m != 0 && post_residual > 0 {
        score += (m as f64) * 0.6;
    }

    // Integer-division thresholds on post_residual: tiny dead space is bad
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // nearly-full bin, unusable sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Prefer filling bins with small residuals relative to mean (compact the stream)
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate: allow opening fresh bins early in stream or when
    // current fit is poor (large post_residual waste relative to capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new empty bin: neutral baseline, penalize slightly unless fit is bad
        score += 6.0;
        if post_residual as f64 > 0.6 * cap {
            score -= 10.0; // large item, fresh bin is fine
        }
        if progress < 0.1 {
            score -= 4.0;
        }
    }

    // Mild pressure to keep open bin count low
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0; // gap just under min item size is pure waste
    } else if dead >= 10.0 && dead < 25.0 {
        score += 12.0; // awkward gap: only fits tiny items
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as u32) < 10 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // and avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // If this bin is the only one that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if existing bins would
    // leave very bad fits (large dead space) or no bins fit well.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 30.0 + pressure + 20.0 * bad_fit;
        // Lookahead: opening a bin is fine if next item can use the remainder.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Reward bins whose residual matches the next item (chaining).
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64
            && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 8.0;
        }
        // Penalize leaving a residual that no small item could use.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
        // Slight bonus for bins tighter than the mean residual (better packing).
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    // Reward bins whose post_residual will be closely consumed by the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= 25.0 * (-gap / 12.0).exp();
        }
        // Penalize post_residual that is too small to ever fit the next item usefully
        // (dead space), but not so small it's negligible.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 5.0;
    }

    // Tightness reward: smaller post_residual is generally better.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // prefer filling them further only if the fit is good.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means reusing is clearly better; a fresh bin
    // should lose to any reasonable fit).
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: new bin is the only option
        } else if fitting_bins_count == 1 {
            score += 10.0; // another bin fits and is last chance: keep new bin unattractive
        }
        // Slightly more willing to open new bins early in the stream.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fits: strong rewards.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Divisible residual slots: easier to fill later.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead: exact match for next item is a huge win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
            if post_residual - next_item_size <= 1 { score -= 5.0 * future_density; }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
    }

    // Sliver penalty near threshold, softened when next item fits.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Mean-residual alignment: prefer bins whose leftover tracks the average.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance consolidation.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // ---- New-bin candidate logic (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size)
            && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        // Existing-bin refinements.
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0
            && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2
            && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0; }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward bins whose residual becomes "dead" (unusable waste locked in)
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward gap
    }

    // Lookahead: bonus if post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (item_size as f64 / bin_capacity as f64).powi(2)
        };
        let global_waste = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = 40.0 + 60.0 * pressure - 15.0 * global_waste;
        if next_item_size > item_size {
            score -= 10.0; // new bin gives room for a bigger follower
        }
    }

    // Early in stream: be slightly conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 + progress) * 6.0;

    // Dead space penalty: residual too small to fit typical future items
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * gap * (1.0 + progress);
    }

    // Penalize opening new bins when many fitting bins exist
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (open_bins_count as f64).sqrt();
    } else if fitting_bins_count <= 1 {
        score -= 5.0;
    }

    // Mild preference for bins deviating from mean residual (balance avoidance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: exact-fit class (residual 0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Class by integer division thresholds on post_residual.
    let post_class = post_residual / 10; // 0..=9
    score += post_class as f64 * 3.0;    // larger dead space penalized progressively

    // Small residuals (<10) are near-perfect fits: strong reward.
    if post_residual < 10 {
        score -= 50.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            score -= 40.0 - chain_post as f64 * 0.5;
            // harmonic class of chained residual
            if chain_post == 0 { score -= 150.0; }
            else if chain_post < 10 { score -= 20.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Capacity-fraction coupling: reward when item fills a harmonic fraction of the bin.
    let fill = item_size as f64 / cap;
    if (fill * 4.0).round() * 25.0 == item_size as f64 {
        score -= 15.0; // quarter/half/three-quarter fills
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - (post_residual as f64);
        if fragmentation < 5.0 && fitting_bins_count > 0 {
            score += 120.0; // open bins are tight enough; keep using them
        } else {
            score -= 20.0; // open bins too fragmented; fresh bin is fine
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;

    // Reward bins whose residual is below the mean (tighter than average).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) mildly via non-linear shaping.
    score -= 30.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize creating a residual that no plausible next item can use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 25.0;
    }
    // Reward bins whose leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when the current bin would leave
    // a large awkward residual relative to mean residual, otherwise keep it costly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        if waste > mean_residual * 0.8 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 15.0 + mean_residual * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted pairing potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64).min(80.0) // post_residual == capacity for new bin
        };
        // Base penalty for opening new bin; reduced late in stream or with many open bins.
        score += 150.0 - 50.0 * progress - (open_bins_count as f64).min(5.0) * 5.0;
        // But if next item is huge, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 60.0;
        }
        let _ = poor_fit;
    }

    // Prefer filling fuller bins (lower residual before placement).
    score += (bin_capacity - bin_residual) as f64 * (-0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect and near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 540.0;
    } else if post_residual <= 4 {
        score -= 240.0;
    }

    // Dead slivers that the next item cannot consume.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward residual divisible into plausible small chunks.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead coupling.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 460.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity.max(1) as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
            if post_residual - next_item_size <= 1 { score -= 5.0 * future_density; }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
    }

    // Small-gap penalty softened when next item consumes it.
    if post_residual > 0 && post_residual < 20 {
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += (20.0 - post_residual as f64) * (1.55 - future_help);
    }

    // Prefer bins with residuals above the mean (keeps big gaps usable).
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance consolidation.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size)
            && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0
            && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2
            && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity.max(1) as f64;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress); }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity.max(1) as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Lookahead: penalize creating residuals too small for the next item ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how well the leftover matches the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover is dead space relative to the next item: penalize more
            // when the leftover is small and useless.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead.min(40.0);
        }
    }

    // ---- Last-chance bin: strongly reward using the only fitting bin ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to encourage spreading across bins.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // ---- Tight fit reward: prefer bins where the item fills most of the space ----
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // ---- Global state coupling ----
    // Prefer to drain bins with residuals near the mean (balance residuals),
    // but only early-to-mid stream; late in the stream, prefer tightest fits.
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.10 * dev * (1.0 - t);
        score -= 8.0 * t; // late-stream consolidation bias
    }

    // ---- New-bin decision ----
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Opening a bin is more acceptable early in the stream.
        score -= 30.0 * (1.0 - t);
        // More open bins -> discourage opening yet another one.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If the item is large, a fresh bin is relatively attractive.
        score -= 0.25 * item_size as f64;
        // If many bins already fit the item, opening a new bin is wasteful.
        score += 12.0 * fitting_bins_count as f64;
    }

    // Small tie-breaker favoring lower post-residual squared (compact packing).
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: strongly prefer tight fills (small post_residual).
    // Late: dead space is costlier, so amplify quadratic term.
    let poly = fit_norm * fit_norm * (1.0 + 3.0 * progress) + 0.5 * fit_norm * (1.0 - progress);

    let mut score = pr + 60.0 * poly;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 3.0 * (1.0 - progress) * (nxt / cap);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight pressure to consolidate into fewer bins.
    score -= 0.05 * open_bins_count as f64 * (1.0 - fit_norm);

    // New-bin candidate: neutral baseline with mild smoothing vs mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 0.2 * (mean_residual - pr).abs();
    }

    score
}

