pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" classes (small or exactly matching likely item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Dead-space penalty grows quadratically for small-but-unusable gaps
        let frac = pr as f64 / cap_f;
        score += 40.0 * frac * frac;
        // Reward residuals in low modulo classes (likely fillable by small items)
        let m = pr % 10;
        score -= (10 - m) as f64 * 1.5;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 + 0.3 * next_item_size as f64;
        // extra reward if next item nearly fills the bin after placement
        let after2 = pr - next_item_size;
        if after2 <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > pr {
        // stranded residual: penalize proportionally
        score += 0.2 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer fuller bins among many open bins (mild pressure to close bins)
    let fill = (bin_capacity - bin_residual) as f64 / cap_f;
    score -= 15.0 * fill;

    // New-bin candidate: only attractive when current bin fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open a new bin early in stream or when open bins are empty-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if item_size > 50 {
            score -= 10.0; // large items do better in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Coupling with mean residual: avoid bins far below mean fullness
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
