    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins with residual close to mean (keeps balanced residuals)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: neutral baseline with mild preference when current fits are poor
