    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward tight placements.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post-residual relative to capacity (non-linear).
