        score += tightness * tightness * 40.0;
    }

    // Penalize leaving residual that is large but useless for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u64 as u32 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

