    // Non-linear coupling of post-residual with stream progress:
    // early on, prefer tight fits less strongly; later, minimize waste aggressively.
    let progress_weight = 4.0 * progress * (1.0 - progress); // smooth bump peaking mid-stream
    score -= 30.0 * (1.0 - norm_pr * norm_pr) * (1.0 + progress_weight);

