    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Smooth new-bin bias: opening a bin is penalized more as stream progresses,
    // but slightly attractive early when residual would be tiny anyway.
    if bin_residual == bin_capacity {
        let open_penalty = 12.0 + 20.0 * progress * progress;
        score += open_penalty;
        score -= 8.0 * (-norm_item * 6.0).exp() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers in the "dead zone" (small, unusable
    // slivers) are heavily penalized; large clean leftovers are rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;
    // dead-zone thresholds via integer division on post_residual
    let dead1 = post_residual / 10; // decade class
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver for any realistic future item
        score += 40.0;
    } else if dead1 <= 2 && post_residual > 0 {
        // 10..=29 : only fits tiny items -> mild penalty
        score += 12.0;
    } else if dead1 <= 4 {
        // 30..=49 : medium class, neutral-ish
        score += 3.0;
    } else {
        // 50+ : highly reusable leftover -> reward
        score -= 8.0 + 10.0 * frac;
    }

    // Perfect or near-perfect fit is golden
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: does the next item fit exactly / well into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            if waste <= 10 {
                score -= 15.0; // near-perfect chain
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            }
        } else {
            // next item cannot use this bin's leftover at all
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large (would leave a bad leftover in an existing bin) or when
    // open-bin leftovers are fragmented.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // large items pair poorly with existing fragmented space
        if item_size >= 50 {
            score -= 20.0;
        }
        if item_size >= 70 {
            score -= 15.0;
        }
        // if existing bins are already full-ish, a new bin is fine
        if mean_residual < 20.0 {
            score -= 20.0;
        }
        // late in the stream, avoid spawning bins for small leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size <= 30 {
            score += 30.0 * (1.0 - progress);
        }
    }

    // Prefer bins whose residual is close to the item (tight packing)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Modulo harmonic bonus: leftovers that are multiples of common item
    // granularity (10s) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Slight preference for reusing existing bins over proliferation
    if bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
