pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit).
    score = post_residual as f64;

    // --- 2-step lookahead: reward post_residual that exactly matches next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: next item fills this bin exactly.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too; reward proportional closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: dead-space penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 50.0).min(2.0);
        }
    } else {
        // Last item: pure tightness matters.
        score += 5.0;
    }

    // --- Relative-to-mean coupling: bins with residual near mean are flexible ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Last-chance bonus: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: only attractive for large items ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes the current item's fit opportunity;
        // penalize unless item is large and no open bin fits well.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count <= 1;
        if large_item && poor_fits {
            score -= 20.0; // justified fresh bin
        } else {
            score += 30.0; // discourage opening bins needlessly
        }
        // New bin post_residual == capacity - item; lookahead still applies via base term.
    }

    // --- Mild stream-progression pressure: late in stream, consolidate harder ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // --- Prefer spreading across many open bins when they're all loose ---
    if open_bins_count > 0 && mean_residual > 40.0 && !is_new_bin {
        score -= 3.0; // slight reward to use existing loose capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
