}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += residual_frac * residual_frac * 12.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if the next item can also fit in the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        }
        // Penalize leaving a gap that is just barely too small for the next item (dead space).
        if next_item_size > post_residual && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += residual_frac * 8.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and crowding.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + 10.0 * (1.0 - progress);
        // If many bins are open with large residuals, discourage opening yet another.
        if open_bins_count > 0 {
            new_bin_cost += (open_bins_count as f64).ln().max(0.0) * 2.0;
        }
        // If mean residual across open bins is small, opening a new bin is reasonable.
        new_bin_cost -= (mean_residual / bin_capacity as f64).max(0.0) * 8.0;
        // If this is the only fitting option anyway, soften the new-bin cost.
        if fitting_bins_count == 0 {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost.max(1.0);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.05;

    // Mild penalty for very small post-residuals that can never host another item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);

    let mut score = pr + 30.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Last-chance bin gets a smooth bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            let waste = pr - nx;
            score += 0.1 * waste * waste / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes modulo key divisors.
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are "usable" pockets.
    let r = post_residual;
    let usable = (r % 10 == 0) as f64 * 6.0
        + (r % 20 == 0) as f64 * 4.0
        + (r % 25 == 0) as f64 * 3.0
        + (r % 50 == 0) as f64 * 5.0;
    score -= usable;

    // Penalize awkward dead space: small nonzero residuals that likely become waste.
    if r > 0 && r < 10 {
        score += 25.0;
    }
    // Modulo-3 classes on residual: mid-range odd residuals are less reusable.
    if r % 3 == 1 && r > 10 && r < 40 {
        score += 4.0;
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // Next item fits but leaves new residual; grade by resulting class.
            let nr = r - next_item_size;
            score -= 10.0 - (nr % 10) as f64;
        } else {
            // Next item won't fit here; slight penalty if this bin becomes dead.
            if r < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when current fit is bad.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Opening fresh is attractive early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: closeness to mean residual signals good packing.
    score -= (bin_residual as f64 - mean_residual).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small post-residuals are likely unusable dead space; punish them hard
    // (they lock away capacity without future value).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // almost certainly dead space
        } else if post_residual < 20 {
            score += 20.0;
        } else if post_residual < 35 {
            score += 5.0;
        }
    }

    // --- Lookahead (k=2): reward bins that can also host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // extra reward for a near-perfect two-item packing
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 8.0; // next item won't fit here either
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer existing bins in general; pressure grows with open_bins_count
        score += 25.0 + open_bins_count as f64 * 4.0;
        // But if this is the only option, force the new bin open
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Last-chance bonus: sole open bin that fits -> avoid wasting it
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // --- Open-bins pressure: when many bins are open, favor tighter fills ---
    // (bins with small residual relative to capacity get a slight discount)
    score -= open_bins_count as f64 * 0.08 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // --- Mean-residual coupling: if average residual is high, discourage
    // leaving this bin with yet another large residual (spread consolidation) ---
    if post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Mild progression term: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize dead space that can never fit the next item.
        if (post_residual as i64 - next_item_size as i64) < 0 {
            score += 10.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Penalize large unusable dead space (below minimum item size 1 is fine, but
    // small residuals relative to mean residual are wasted capacity).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 8.0;
    }

    // Last-chance bin: only bin that fits -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if item is huge relative to capacity, opening fresh is reasonable.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual before placement).
    score += 0.15 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills non-linearly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty for small awkward leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item can't use this bin's leftover; penalize large leftovers mildly.
            score += 0.04 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below mean residual (keep balance) when many bins open.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; slight penalty
        // when many bins already open.
        score += 8.0 * progress + 0.3 * (open_bins_count as f64).ln().max(0.0);
        // Allow new bin early or when item is large relative to mean residual.
        if progress < 0.3 || (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Strong rewards for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space penalty for unusable slivers
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Harmonic slots bonus: residual divisible into many 10-sized slots
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: exact match with next item is highly desirable
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 5.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Sliver penalty softened if next item consumes it
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin: prefer using it before opening a new one
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let dead_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * dead_penalty;

    // Reward tight fits (small post_residual) with smooth term
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits the post residual, smooth falloff
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_frac = nx / pr.max(1.0);
            score -= 20.0 * fit_frac * (1.0 - fit_frac) * 4.0 * (1.0 + progress);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins are open and this placement wastes space
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * openness * norm_pr;

    // Mean residual context: prefer bins near the mean residual (smooth term)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space is much worse when it
    // falls into "useless" small classes. Class boundaries at multiples of
    // capacity/8 (small items >= 10 can still fill >= 10 residual).
    let class = post_residual / (bin_capacity / 8);
    match class {
        0 => score += 40.0,                      // nearly full: perfect close-out
        1 => score += 18.0,                      // 12-ish residual: awkward
        2 => score += 8.0,                       // 25-ish: mid dead space
        3 => score += 2.0,                       // 37-ish: usable
        4 => score -= 4.0,                       // 50-ish: half bin, very reusable
        _ => score -= 2.0,                       // large residual: flexible
    }

    // Exact-fit bonus (post_residual is a harmonic divisor class of 0 mod small ints).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;                           // residual aligns with min item size
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward, scaled by how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 10.0 - snug * 0.15;
        } else {
            // Next item won't fit here: penalize wasting capacity this bin
            // could have used for a better pairing.
            score += 6.0;
        }
        // Integer-division threshold: if next item is a "big" item (> cap/2),
        // prefer bins whose post-residual is in the complementary class.
        if next_item_size > bin_capacity / 2 && post_residual < bin_capacity / 4 {
            score += 4.0; // keep big bins open for big items
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0; // near-perfect squeeze
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 20.0;
        // More attractive late in the stream or when open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        if mean_residual < cap * 0.15 && open_bins_count > 0 {
            score -= 12.0; // existing bins are nearly full: open fresh one
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: a fresh bin is valuable
        }
    }

    // Mild preference for tighter bins among equals (small residual spread).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Tie-break by fill ratio (favor fuller bins) via capacity fraction.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 15.0; // using the last bin is fine if residual stays usable
        } else if post_residual > 0 {
            score += 25.0; // dead space in the only option is bad
        }
    }

    // Lookahead: favor bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: only attractive when existing residuals are large/wasted.
        score += 30.0 - 2.0 * mean_residual + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space penalty for tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward leaving room divisible into likely future chunks.
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead: next item fits exactly or nearly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 430.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 70.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 34.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Small sliver penalty softened if next item consumes it.
    if post_residual > 0 && post_residual < 20 {
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += (20.0 - post_residual as f64) * (1.55 - future_help);
    }

    // Prefer bins whose residual is below the mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance / few-fitting-bin consolidation.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate gating.
    if is_new_bin {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
    } else {
        // Chain-fit lookahead: bin can host item then next item with tight slack.
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving dead space smaller than any plausible next item.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Penalize bins whose residual deviates from mean (keep bin pool homogeneous).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist, especially late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        // New bin is attractive only if no open bin gives a tight fit.
        if post_residual as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild reward for very tight placements (small leftover).
    if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

