    score -= progress * 10.0;

    // New-bin candidate: penalize unless item is huge or bin state is bad
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * big_item;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Slight preference for perfectly full bins
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

