    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    } else {
        score -= 4.0;
    }

    // Lookahead: bonus if next item fits the post residual (smooth term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 12.0 * (1.0 - fits) * (pr >= nxt) as i32 as f64;
        // penalize leaving residual just below next item size (smooth)
        let gap = nxt - pr;
        if gap > 0.0 {
            score += (gap / cap).min(1.0) * 8.0;
        }
    }

    // Mild preference against spreading across many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress) * 0.8;

    // Mean-residual alignment: favor bins near mean residual (smooth quadratic).
    let d = (pr as f64 - mean_residual) / cap;
    score += d * d * 10.0;

    // New-bin candidate handling: only attractive if current bin would leave bad residual.
    if bin_residual == bin_capacity {
        score = pr * 0.9 + 30.0 * progress + (x * (1.0 - x) * 4.0) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity used by placing the item here
    let used_frac = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: dead space if it cannot fit typical items
    let harmonic_class = post_residual % 10;
    if post_residual > 0 {
        // penalize post residuals in awkward classes (small slivers)
        if harmonic_class < 3 {
            score += 6.0 * (3 - harmonic_class) as f64;
        } else if harmonic_class > 7 {
            score -= 2.0;
        }
    }

    // Reward tight fits: post_residual small relative to capacity
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_frac < 0.10 {
        score -= 15.0;
    } else if post_frac < 0.25 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how well it fills
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fill;
            // extra reward if next item exactly fills the bin
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // next item won't fit: penalize wasting residual
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items or when existing bins fit poorly
        let pressure = mean_residual / bin_capacity as f64;
        if post_frac > 0.5 {
            // large item into fresh bin keeps residual usable
            score -= 8.0 * (1.0 - pressure);
        } else {
            // small item into a fresh bin is wasteful
            score += 20.0 + 10.0 * used_frac.recip().min(5.0);
        }
    }

    // Stream progression: late in the stream, prefer closing bins (fill them tightly)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_frac);

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * (post_frac - 0.5).abs() * 0.1;

    // Penalize divergence from mean residual (keep residuals homogeneous)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space penalties for tiny unusable remainders
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Slot-friendly remainders (multiples of 10)
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
            if post_residual - next_item_size <= 1 { score -= 5.0 * future_density; }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
    }

    // Sliver penalty near 20 boundary, softened when next item consumes
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Fragmentation awareness: compare bin residual to mean residual
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // General dead-ratio and stranded-space analysis
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress); }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0; }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical future items are heavily penalized (unusable gap).
    let dead_threshold = 10.0_f64.min(cap * 0.10);
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post == 0.0 {
        score -= 25.0;
    }

    // Reward tight fits relative to what remains.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and penalize spreading; with few bins, be less aggressive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chains well).
    if next_item_size > 0 && (post_residual as u64) == next_item_size as u64 {
        score -= 18.0;
    }
    // Penalize if post residual is just barely too small for the next item
    // (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0;
    }

    // Mild preference for bins whose residual is near the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    // Early in the stream, allow opening new bins more freely; later,
    // consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;
    score += progress * 3.0;

    // New empty bin candidate: make it unattractive unless current bins
    // would create severe dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a chained perfect fit -> very attractive.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 100.0 - (after_next as f64).min(100.0);
        } else {
            // Next item cannot use this space: penalize dead space, worse when small.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize leaving unusable slivers relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 * (10.0 - pr);
    }

    // Compare against mean residual: placing into a bin with more residual than
    // average preserves tighter bins; reward that.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin is
    // nearly full or the item is large relative to residual.
    if bin_residual == bin_capacity {
        // Opening new bin is fine when the current item is big and no tight fit exists.
        let pressure = (item_size as f64 / bin_capacity as f64) * 120.0;
        score = 150.0 - pressure
            + if next_item_size > 0 && next_item_size >= item_size { 40.0 } else { 0.0 }
            + if fitting_bins_count <= 1 { -300.0 } else { 0.0 };
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress;

    // Slight penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: high fill ratio lowers score.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fill * fill;

    // Penalize small dead space that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 1.5;
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins slightly unattractive unless
    // the item fits poorly everywhere or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 - 4.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 5.0; // nothing fits well anywhere; open fresh bin
        }
    }

    // Prefer filling bins with large residuals when many bins are open.
    score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mild time-horizon term: later in the stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

