            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    // Early stream: prefer tight fits (low post_residual) mildly; late stream: strongly
    let coupling = 2.0 + 6.0 * prog2 + 4.0 * prog3;
    score += coupling * prn * prn * cap * 0.1;

    // Penalize post_residual that cannot fit the lookahead item (smooth soft penalty)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * cap * (0.5 + 2.0 * progress);
        // Reward if post residual still accommodates next item
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= fits_next * cap * 0.4;
    }

    // Last-chance bin bonus: strongly favor using a bin when few alternatives fit
    if fitting_bins_count <= 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Slight preference for bins with residuals below mean (consolidate small leftovers)
    let dev = (mean_residual - pr) / cap;
    score += dev * cap * 0.3 * (1.0 - progress);

    // Discourage spreading across many bins when progress is high
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);

    // New-bin candidate: penalize so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + prn * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
