        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality by residue class mod 10
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,          // perfectly clean residual (fits multiples of 10)
        1 | 9 => score += 3.0,      // nearly useless sliver
        2 | 8 => score += 1.5,
        5 => score -= 2.0,          // half-class, decent
        _ => {}
    }

    // Integer-division thresholds: does post_residual fit the next item exactly?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fit quality: exact fit is golden
            if pr == next_item_size {
                score -= 12.0;
            } else {
                let slack = (pr - next_item_size) as f64;
                score -= 5.0 - slack * 0.05;
                // harmonic coupling: next item divisible by 10 pairs well with class-0 residual
                if next_item_size % 10 == 0 && pr % 10 == 0 {
                    score -= 3.0;
                }
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportional overshoot
            score += ((next_item_size - pr) as f64) * 0.08;
        }
    }

    // Capacity fraction coupling: favor filling to high fraction of capacity
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * fill_frac * 8.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        if fragmentation > 0.35 || fitting_bins_count == 0 {
            score -= 4.0 + fragmentation * 6.0;
        } else {
            score += 15.0; // keep using open bins when they are healthy
        }
    }

    // Late-stream consolidation: as stream progresses, prefer tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.15;

    // Penalize bins whose residual deviates far from the mean (balance harvesting)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
