pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item (min item size 1, but practically small gaps are waste).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        }
    } else {
        score -= 40.0; // perfect fit: eliminate residual entirely
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // next item cannot use this gap
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize using open bins when many are open and
    // residual is large (favor consolidation), but encourage filling bins
    // when few are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: neutral-ish baseline; open a new bin only
    // if this placement would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 - item_size as f64;
        let mut new_score = new_bin_base;
        if new_bin_base < 10.0 { new_score -= 60.0; }
        else if new_bin_base < 20.0 { new_score -= 25.0; }
        if next_item_size > 0 && new_bin_base >= next_item_size as f64 {
            let slack = new_bin_base - next_item_size as f64;
            new_score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Opening a new bin is costly when existing bins fit poorly but exist.
        if fitting_bins_count > 0 {
            new_score += 12.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        return new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
