pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted residual: quadratic dead-space term
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closed after next item
        } else if next_item_size <= post_residual {
            // partial chain: reward tightness of the follow-up fit
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
        } else {
            // next item cannot follow here: penalize proportionally to leftover
            score += 15.0 + (post_residual as f64) / (bin_capacity as f64) * 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias)
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Slight preference for opening new bins early in the stream (build diversity),
    // and for consolidating into open bins later in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    // Penalize opening yet another bin when many are already open with room
    if bin_residual == bin_capacity && open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
