    score -= 0.15 * ((bin_residual as f64) - mean_residual);

    // Slight preference to drain bins with large residuals (consolidation).
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let t = progress;
    // Smooth interaction: wasted space penalized more as stream progresses.
    score += 8.0 * prn * prn * (0.5 + t);
    score += 4.0 * prn * t * (1.0 - t);

    // Reward tight fits (low post residual) with smooth decay.
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness * tightness * (0.5 + t);

    // Lookahead coupling: penalize if next item cannot use remaining space (smooth).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = ((pr - ni) / bin_capacity as f64).max(0.0);
        score += 5.0 * gap * gap * (1.0 - t);
        // Bonus if next item fits exactly-ish in the post residual.
        let fit_quality = 1.0 - (pr - ni).abs() / bin_capacity as f64;
        if fit_quality > 0.0 {
            score -= 3.0 * fit_quality * fit_quality * t;
        }
    }

    // Last-chance bin: strong smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let obn = open_bins_count as f64;
    score += 0.5 * (obn / (obn + 5.0)) * t;

    // Mean residual coupling: prefer bins near the mean residual (smooth).
    let dev = (pr - mean_residual) / (bin_capacity as f64);
    score += 2.0 * dev * dev;

    // New-bin candidate: smooth penalty that shrinks as stream ends.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
