pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: classify leftover by capacity fraction.
        let frac = post_residual as f64 / cap;
        let class = if frac > 0.5 { 4 } else if frac > 0.3 { 3 } else if frac > 0.15 { 2 } else if frac > 0.05 { 1 } else { 0 };
        // Dead space penalty grows super-linearly for tiny unusable leftovers.
        let dead = (cap - post_residual.min(bin_capacity as u32) as f64) * 0.0;
        score += match class {
            0 => 12.0, // sliver: nearly dead space
            1 => 4.0,
            2 => 0.0,
            3 => -3.0,
            _ => -6.0, // roomy leftover is reusable
        };

        // Lookahead coupling: reward if next item fits the post residual.
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                score -= 8.0 + slack * 0.05; // chain-friendly placement
            } else {
                // Next item won't fit here: penalize slightly, more if leftover tiny.
                score += 3.0 + (20.0 - frac * 40.0).max(0.0);
            }
        } else {
            // Last item: just minimize leftover.
            score += post_residual as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin; cheaper late in the stream / with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = cap * 0.45 + 5.0 * (1.0 - progress);
        // If no open bin can fit (fitting_bins_count==0 means only new bin fits), must open.
        if fitting_bins_count == 0 {
            new_bin_score -= 1000.0;
        }
        // Prefer new bin if mean residual is large but fragmented (many open bins).
        new_bin_score += (open_bins_count as f64) * 0.8;
        score = new_bin_score;
    } else {
        // Mild preference to balance load: slightly favor bins below mean residual.
        score += (mean_residual - bin_residual as f64) * 0.02;
    }

    // Modulo harmonic: leftovers that are multiples of common small sizes are reusable.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 2.0;
        } else if pr % 5 == 0 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // tiny gaps cost 20..56 extra
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits in post_residual, reward; else penalize blocking.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced residual use).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack left after it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating dead space that neither the next item nor typical items can use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }
    if post_residual < 10 {
        score -= 15.0; // tiny dead space is fine (bin nearly full)
    }

    // Compare against mean residual: prefer bins that are relatively fuller.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad waste.
    if bin_residual == bin_capacity {
        let waste_if_used = (bin_residual - item_size) as f64;
        let bad_fit = next_item_size > 0 && waste_if_used < next_item_size as f64 && waste_if_used > 0.0;
        score = 100.0 + if bad_fit { -10.0 } else { 30.0 };
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Late in stream: tighten packing, avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: heavy reward.
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead slivers that nothing small can fill later.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Reward divisible post-residuals (multiple future small items fit).
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 420.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 65.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 34.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 55.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin before opening a new one.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 22.0 * fitting_bins_count as f64 + 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 35.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size.max(1)) {
            score -= 14.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 9.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 3 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead: exact pair fit.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        score -= 20.0 * (1.0 - progress);
        if bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if bin_residual - item_size - next_item_size <= 3 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
    }

    // Open-bins consolidation pressure.
    score += open_bins_count as f64 * 1.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space penalized super-linearly)
    let waste = post_residual as f64;
    score += 0.8 * (waste * waste) / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; small penalty if post_residual is tiny dead space
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild preference among many options toward tighter bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins relative to mean residual
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open bins (penalize new-bin less later? actually
    // early exploration: favor spreading items when few bins exist)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: penalize normally, discount penalty as stream progresses
        score += 30.0 * (1.0 - 0.5 * progress);
        // avoid opening new bins when many are open with large mean residual
        score += 0.3 * mean_residual * (open_bins_count as f64).sqrt();
    } else {
        // early phase: slight bonus for using open bins to consolidate
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins whose residual after placement stays "usable" (>= typical small item)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (large post penalty); later, dead space
    // matters more since fewer future items remain to fill gaps.
    let tightness = (1.0 - norm_post).powi(2);
    score -= 12.0 * tightness * (1.0 - progress);

    // Dead-space penalty grows smoothly with progress^3 (late-stream gaps
    // are unlikely to be filled).
    score += 18.0 * norm_post * norm_post * (0.3 + progress * progress * progress);

    // Reward near-perfect fits with a smooth quadratic valley around post=0.
    score -= 8.0 * (-norm_post * 6.0).exp();

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: reward bins whose post_residual can still host
    // the next item, penalize gaps that are too small to matter.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - progress) * (post / (post + nxt));
        } else {
            score += 4.0 * (nxt - post) / cap * (0.5 + progress);
        }
    }

    // Mild preference for consolidating into fewer bins as stream advances.
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near the mean (keeps
    // residual distribution balanced, smooth quadratic term).
    score += 2.0 * (post - mean_residual) * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect or near-perfect fills are strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
