    // could use is nearly worthless; penalize by its "usability class".
    let dead = match post_residual {
        0 => 0.0,
        1..=10 => 0.5,        // only small items fit
        11..=20 => 2.0,
        21..=34 => 4.0,
        35..=49 => 6.0,
        50..=100 => 8.0,
        _ => 10.0,
    };
    score += dead;

    // Modulo structure: post_residual divisible by common item sizes (5,10,20,25)
    // is more likely reusable later; reward such residuals.
    if post_residual > 0 {
        if post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 5 == 0 {
            score -= 7.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
