        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer filling already-open bins over opening new ones when fit is decent.
    if bin_residual < bin_capacity {
        score -= 10.0;
    } else {
        // New-bin candidate: base cost so it only wins when open bins fit poorly.
        score += 25.0;
        // Opening a new bin is more attractive early / when many bins are open
        // with fragmented residuals (high mean residual relative to capacity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        score += 0.05 * open_bins_count as f64;
        score -= 0.2 * (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
    }

    // Large items should go into bins with proportionally matching residuals.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.6 && post_residual <= 20 {
        score -= 50.0;
    }

    score
}

