    // applied only when the new-bin candidate is not in play.
    if bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fit_ratio * 12.0;
        score += open_bins_count as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..)
    // are unusable dead space; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 + 2.0 * post_residual as f64;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (consolidating fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early stream: be slightly more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual < 15 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
