    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 400.0;
    } else if post_residual <= 4 {
        score -= 150.0;
    }

    // Dead-space avoidance: small unusable gaps heavily penalized.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold && !next_consumes {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 35.0 + 0.5 * post_residual as f64;
    }

    // Lookahead: exact match for the next item is a great outcome.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
