    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Open-bins pressure: consolidation over proliferation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
