        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 20.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
    }

    // Dead ratio pressure: large fraction of bin becoming unusable is bad.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity.max(1) as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity.max(1) as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 18.0 * (1.0 - progress);
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
    }

    // Mild stream progression: late in the stream, waste hurts more.
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fits (small post_residual) already favored by starting score.

    // --- Aggressive 2-step lookahead: does the NEXT item fit into this bin's post-residual? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            // Reward: next item can chain into this bin.
            // Reward magnitude grows as the match becomes tight (post - nxt small),
            // capped to avoid overwhelming the base score.
            let slack = post - nxt;
            let tightness = 1.0 - (slack / bin_capacity as f64);
            score -= 30.0 * tightness;
            // Extra bonus for near-exact 2-step completion (dead-space elimination).
            if slack <= 10.0 {
                score -= 20.0;
            }
        } else {
            // Penalize post_residual that is unusable for the next item but not tiny:
            // creates dead space unless it's small enough to be a fine final gap.
            let waste = post;
            if waste > 10.0 {
                score += 0.5 * (waste - 10.0);
            }
        }
    } else {
        // Last item: just prefer minimal post_residual (score already does this).
    }

    // --- Mean residual coupling: prefer bins whose residual is far from the mean ---
    // (normalize outlier bins, keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - no open bin fits well (fitting_bins_count small), or
        //  - open bins are already crowded (mean_residual low relative to item size).
        let crowded = mean_residual < (item_size as f64) * 1.5;
        if fitting_bins_count == 0 || (crowded && fitting_bins_count <= 1) {
            // Neutral/slightly attractive new bin: score = post_residual (= 100 - item),
            // subtract a bit to make it competitive.
            score -= 5.0;
        } else {
            // Discourage opening a new bin when decent fits exist.
            score += 45.0;
        }
    }

    // --- Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins harder to avoid leftover fragmentation. ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Small penalty per open bin: encourage bin-count minimization pressure ---
    score += 0.05 * open_bins_count as f64;

    score
}

