        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest possible item (1) are fine,
    // but residuals that waste large chunks are bad. Quadratic waste penalty.
    let waste = post_residual as f64;
    score += 0.012 * waste * waste / (1.0 + mean_residual / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves new slack; mild reward proportional to combined fill
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * combined;
        } else {
            // next item cannot follow here; penalize slightly more for larger overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; the waste penalty already
    // pushes it up. Add extra penalty proportional to how many open bins exist (prefer reusing),
    // but relax late in the stream when many bins are nearly full.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    // Global state: when mean residual is high, bins are loose; prefer concentrating items
    // into the emptier bins (lower residual than mean gets a bonus).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more conservative (penalize slack) since fewer
    // chances remain to fill gaps.
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

