    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Smooth coupling of post-residual quality with stream progress:
    // later in the stream, tighter fits matter more
    score += prn * prn * (progress * 20.0);

    // Reward nearly-full bins (small dead space) via cubic term
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 - prn) * 5.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - prn);
    } else {
        // mild penalty when many bins fit (choice is easy, prefer best fits anyway)
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // post residual too small for next item: penalize proportionally
            score += (nxt - pr) / cap * 6.0;
        }
    }

    // Contextual: penalize spreading across many open bins when mean residual is high
    score += (open_bins_count as f64) * (mean_residual / cap) * 0.3;

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // with progress; opening fresh bins early is cheap, late is expensive
    if bin_residual == bin_capacity {
        score = 25.0 * (1.0 - 0.6 * progress) + 0.2 * (open_bins_count as f64);
