pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly fit a future item. Classify post_residual into capacity
    // fractions and integer-division bands.
    let pr = post_residual;
    if pr > 0 {
        // Modulo-10 band: residuals not multiples of 10 are "awkward" dead space
        let awkward = pr % 10;
        score += (10 - awkward) as f64 * 0.15;

        // Integer division threshold: tiny residuals (< 10) are pure waste
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Harmonic class by capacity fraction: residuals near half capacity
        // are the most reusable (highest chance any item fits).
        let frac = pr as f64 / bin_capacity as f64;
        let harmonic_penalty = (frac - 0.5).abs();
        score += harmonic_penalty * 20.0;

        // If the residual can fit the lookahead item, reward strongly.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0;
            // Perfect chaining: post_residual exactly matches next item
            if pr == next_item_size {
                score -= 15.0;
            }
        } else if next_item_size > 0 {
            // Lookahead won't fit here: penalize if it would fit a fresh bin
            score += 6.0;
        }
    } else {
        // Perfect fill: best outcome
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should win only when current
    // residual is poor relative to item or lookahead.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.6;
