        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 25.0;
        }
        // If many bins are open with large mean residual, prefer consolidation
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.1;
    }

    // Late in the stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

