pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor placements that leave little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small-but-nonzero dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Waste that cannot serve the next item: penalize proportionally.
            score += 0.10 * post_residual as f64;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: fill as much as possible.
        score -= 10.0 * fit_ratio;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere else (large post_residual waste avoided).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 10.0;
        // Early in stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 0.5 + 1.5 * progress;
        // If few fitting bins exist, this bin may be a last resort.
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty *= 0.6;
        }
        // If the item is large relative to capacity, prefer existing bins
        // that fit tightly; new bin gets mild penalty.
        score += new_bin_penalty;
    } else {
        // Existing bin: slight reward for using open bins (bin consolidation).
        score -= 1.0;
        // Last-chance bin (only fitting bin): strong reward to avoid new bin.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer consuming
    // from bins with residual far below mean (rebalance toward emptier bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer bins whose residual is close to item size (near-exact fit),
    // with a non-linear bump near perfect fit.
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.08 * gap;
    if gap < 5.0 {
        score -= 5.0;
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    if open_bins_count > 8 {
        score += 0.02 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
