    if post_residual == 0 { score -= 520.0 ; }
    else if post_residual <= 4 { score -= 230.0 ; }
    if post_residual > 0 && post_residual < 10 && ! next_consumes { score += 50.0 + 0.7 * post_residual as f64 ; }
    if post_residual > 0 && post_residual < item_size . min (80) { score += 40.0 + 0.5 * post_residual as f64 ; }
    let slots = post_residual / 10 ;
