    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 + 18.0 * progress + 0.5 * item_size as f64 ;
        if mean_residual > item_size as f64 + 10.0 { score += 28.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
    } else if fitting_bins_count <= 2 { score -= 16.0 ; }
    if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size . max (next_item_size . max (1)) { score -= 12.0 * (1.0 - progress) ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let tightness = 1.0 - (pr / cap).powi(2);
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score -= tightness * progress_weight * (cap * 0.25);

    // Penalize large dead space non-linearly, scaled by mean residual context.
    let waste = (pr / cap).powi(3);
    score += waste * cap * (0.5 + mean_residual / cap);

    // Lookahead: reward bins whose post_residual can fit the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score -= (1.0 - fit_gap / cap).max(0.0) * cap * 0.15 * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= cap * (0.3 + 0.4 * progress);
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for filling bins with larger residual relative to capacity.
    score -= (bin_residual as f64 / cap) * 0.1;

    score
}

