pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo common item sizes
    let pr = post_residual;
    let cap_frac = bin_residual as f64 / bin_capacity as f64;

    // Reward residuals that belong to "useful" harmonic classes:
    // multiples of 10 or 20 are easy to fill later.
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit
    } else if pr % 20 == 0 {
        25.0
    } else if pr % 10 == 0 {
        15.0
    } else if pr % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize awkward dead space: small but not zero residuals
    if pr > 0 && pr < 10 {
        score += 30.0 * (1.0 - pr as f64 / 10.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if pr >= next_item_size {
            score -= 0.3 * (pr - next_item_size) as f64;
        } else {
            // next item cannot fit here; penalize proportionally to wasted space
            score += 0.2 * next_item_size as f64 * (1.0 - cap_frac);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // opening cost grows with stream progression and open bins
        score += 40.0 + 2.0 * open_bins_count as f64
            + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // but if item is large, a fresh bin is more acceptable
        score -= 0.2 * item_size as f64;
    }

    // Mild preference for tighter existing bins (smaller residual before placement)
    score += 0.1 * (1.0 - cap_frac) * bin_capacity as f64 * 0.1;

    // Mean-residual coupling: prefer bins near the mean (avoid fragmentation outliers)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest plausible item (<=10)
    // are essentially unusable; penalize them heavily and super-linearly.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Small gaps are risky: harder to fill later.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use this dead space either -> extra penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // make the new-bin candidate (full residual) less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.5 + progress * 8.0;
    } else {
        score -= open_bins_count as f64 * 0.4;
    }

    // Prefer bins whose residual is below the mean residual (i.e. fuller bins),
    // consolidating filling.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 150.0;
            // extra reward for chained near-perfect fit
            let chain = (post_residual - next_item_size) as f64;
            score -= (bin_capacity as f64 - chain).max(0.0) * 0.5;
        } else {
            // dead space penalty scaled by how much next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
        }
    }

    // Penalize small unusable post-residual (dead space) but not perfect fits
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fits poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // open new bin only if best alternative leaves large dead space
        if poor_fit < 25.0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 500.0; // keep using open bins when they chain well
        } else {
            score += 120.0; // mild default penalty for opening new bins
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Time horizon: early in stream, be pickier (prefer near-perfect fits);
    // late in stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (1.0 - fit_ratio.abs());

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 3 {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 12.0 * consolidation;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, tight existing bins) or stream is early and item is large.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let early_bonus = (1.0 - progress) * 15.0 * (item_size as f64 / bin_capacity as f64);
        score = bin_capacity as f64 - desperation - early_bonus
            + 20.0 * fit_ratio; // discourage opening new bins for small items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space penalty for tiny unusable residuals
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward larger usable residuals (slots of 10)
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // 2-step lookahead
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Mean residual coupling: tighter packing preference
