pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Tight fits (small post_residual) are rewarded more strongly as the stream advances.
    let tightness = (post / cap).powi(2); // 0 = perfect fit, 1 = empty bin
    let progress_weight = 0.35 + 0.65 * progress * progress;
    score += progress_weight * 40.0 * tightness;

    // Reward exact / near-exact fits with smooth exponential decay.
    if post == 0.0 {
        score -= 25.0;
    } else {
        score -= 20.0 * (-post / 8.0).exp();
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits in the post-residual, reward saving space for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (nxt / post.max(1.0)) * 0.5);
        } else {
            // Penalize leaving residuals that are awkwardly large but unusable for next item.
            let waste = post - nxt;
            score += 4.0 * (waste / cap).powi(3);
        }
    }

    // Mild preference for fuller bins relative to the fleet average.
    score += 3.0 * ((mean_residual - post) / cap).clamp(-1.0, 1.0);

    // Penalize spreading across many open bins slightly, encouraging consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * tightness * 6.0;

    // New-bin candidate: keep it attractive early (spread items), discourage late when
    // open bins can absorb the item; make it smooth via a logistic in progress.
    if bin_residual == bin_capacity {
        let logistic = 1.0 / (1.0 + (-(progress - 0.5) * 8.0).exp());
        score += 14.0 * logistic - 10.0 * (1.0 - logistic);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on dead space.
    let pr = post_residual;
    let class = pr % 10; // residue class of dead space
    // Penalize "orphan" residues that are hard to fill (small odd remainders).
    match class {
        0 => score -= 12.0,          // perfectly aligned dead space
        1 | 3 | 7 | 9 => score += 6.0, // awkward odd remainders
        5 => score -= 3.0,           // multiples of 5 are semi-usable
        _ => score += 1.5,           // even but not aligned
    }

    // Integer-division thresholds on post_residual: big chunks remain usable.
    let chunk = pr / 10;
    score -= chunk as f64 * 1.2;

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; dead space penalty grows with tightness
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    let residual_frac = post_residual as f64 / cap;
    score -= (mean_residual / cap - residual_frac) * 4.0;

    // Mild exploration pressure: encourage opening bins early when many fit elsewhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when it yields a clean harmonic class
        // or when open bins are crowded.
        let clean = (item_size % 10 == 0) as f64;
        score -= clean * 8.0;
        score += (open_bins_count as f64) * 0.4 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 3.0; // don't open fresh bin if next item is bigger anyway
        }
    }

    // Small tie-break toward bins whose fill fraction is high.
    score += (1.0 - (bin_residual as f64 / cap)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible future item
    // (items >= 1 per interface note; treat gaps < 12 as likely unusable dead space).
    if post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the resulting residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item then fills bin nearly exactly.
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap.
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin is below average residual (already tight),
    // it is a good target; a very roomy bin is less urgent.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist:
    // the empty-bin candidate has post_residual = capacity - item_size which is large,
    // but give it an explicit handicap unless it would create a near-perfect fill later.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space is the enemy).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this placement is perfect — big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item can also fit here afterwards: good chaining.
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit in leftover: penalize dead space.
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins below mean residual are "tighter"
    // than average — prefer filling them (reduces fragmentation spread).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit is loose.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Early in stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // chain bonus: next item leaves small gap too
            let next_post = post_residual as i64 - next_item_size as i64;
            score -= 10.0 * (1.0 - (next_post as f64 / bin_capacity as f64).abs());
        } else {
            // next item won't fit: penalize creating a dead gap next_item_size can't use
            score += 5.0;
        }
    }

    // Last chance: this is the only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: late in stream, prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> discourage opening new ones
    if bin_residual == bin_capacity {
        // new-bin candidate
        score = post_residual as f64 + 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 12.0; // fresh bin fits next item
        }
        if progress > 0.8 {
            score += 15.0; // late stream: avoid new bins
        }
    } else {
        // penalize bins whose residual is far below mean (already fragmented)
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.07;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    let last_chance = fitting_bins_count == 1;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear waste penalty: squared normalized dead space
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Cubic coupling of post_residual with stream progress:
    // late in the stream, dead space is increasingly costly
    score += 60.0 * waste_frac * waste_frac * waste_frac * (0.5 + progress);

    // Reward bins whose post_residual still matches the next item (lookahead fit)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let gap_frac = (gap / cap).clamp(0.0, 1.0);
        score += 30.0 * gap_frac * gap_frac;
        // Smooth bonus when next item fits exactly into the post residual
        let fit_quality = 1.0 - gap_frac;
        score -= 25.0 * fit_quality * fit_quality * fit_quality;
    }

    // Interaction with mean residual: penalize bins deviating from fleet average
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Smoothly discourage opening new bins, except when it's the last chance
    // or when no open bin leaves a small residual anyway.
    let open_pressure = 1.0 / (1.0 + open_bins_count as f64);
    let new_bin_penalty = 80.0 * (1.0 - progress) * open_pressure * (1.0 - waste_frac);
    if is_new_bin {
        score += new_bin_penalty;
        if last_chance {
            score -= 70.0;
        }
    } else if last_chance {
        // Favor using the only bin that fits rather than opening a new one
        score -= 20.0 * (1.0 - waste_frac);
    }

    // Mild preference for consolidating into fewer bins early on
    score += 3.0 * open_bins_count as f64 * (1.0 - progress) * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers in "useful" classes
    // (multiples of common item sizes / large chunks) and penalize dead zones.
    let cap = bin_capacity as f64;

    // Dead-space penalty: leftovers too small to hold even the smallest item (1..=10)
    // are wasted. Penalize sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class reward: leftover divisible by common granularity (10) is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Class of post_residual via integer division thresholds.
    let pr = post_residual as f64;
    if pr >= cap * 0.5 {
        score -= 12.0; // bin still very roomy: good
    } else if pr >= cap * 0.25 {
        score -= 4.0;
    } else if pr > 0.0 {
        score += 10.0; // small scraps are low value
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.1;
            // harmonic bonus: leftover exactly matches next item size class
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // leftover cannot host next item: penalize if leftover is dead scrap
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 3.0;
            }
        }
    } else {
        // last item: prefer tightest fit overall
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current item is large
    // relative to typical residuals, or when all fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so it wins only for bad fits elsewhere.
        score = cap * 0.75;
        // Opening a new bin is more attractive early (plenty of stream left to fill it)
        // and when many bins are already open with small residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        score -= (open_bins_count as f64) * 0.5;
        if item_size >= 50 {
            score -= 10.0; // big items pair well in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // next item also big: fresh bin can host both
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), unless it's a near-perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Tiny dead gaps are bad unless next item fills them.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0; }
            if post_residual - next_item_size <= 1 { score -= 5.0 * future_density; }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 { score += 28.0; }
        }
    }

    // Dead sliver penalty, softened when next item consumes it.
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bin: keep it attractive.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 19.0 * (1.0 - progress);
        }
        if post_residual >= item_size.max(next_item_size) && post_residual < item_size.max(next_item_size) + 6 {
            score -= 13.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        if fitting_bins_count >= 2 && post_residual >= item_size {
            score += 12.0 * (1.0 - progress);
        }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 {
            score += 9.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) { score += 9.0; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0; }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

