pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
