        if chain_waste == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space too small for anything (typical min size).
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize spreading across many open bins; encourage consolidation when bins are many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Reward using bins with large residuals relative to mean (drain the emptiest).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 40.0 * large_item;
        // Late in the stream, opening new bins is less costly (fewer future items to serve).
        score -= 50.0 * progress;
        // If many bins fit the item, a new bin is almost never preferable.
        if fitting_bins_count > 2 {
            score += 100.0;
        }
    }

    // Mild penalty for very small post-residual fragments that can't fit typical items.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - progress);
    }

    score
}

