    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless it's genuinely better
    // than dumping into a bin that would leave a tiny dead gap.
    if bin_residual == bin_capacity {
        score = 150.0 + open_bins_count as f64;
        // Allow new bin early in stream or when item is huge relative to capacity.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.05 {
            score -= 120.0;
        }
        if item_size > 80 {
            score -= 60.0;
        }
        // If the item would leave a small dead gap in every fitting bin,
        // opening a fresh bin is competitive.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count >= 1 {
            score -= 80.0;
        }
    }

    // Lookahead: if the next item could use this bin's post residual exactly,
    // reward leaving that gap; if the gap is unusable for next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild normalization toward mean residual state.
    score -= 0.3 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize proportionally to waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // residual is wasteful unless it enables the lookahead fit.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when post residual of the new bin is small relative to item
    // (i.e., item nearly fills a fresh bin) or late in the stream.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 120.0 * fill_frac - 40.0 * progress;
        if next_item_size > 0 && next_item_size >= post_residual {
            // next item also needs a fresh bin -> opening is fine
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Strong rewards for exact / near-exact closures
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Penalize unusable slivers (< min item size) unless next item consumes them
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 55.0 + 0.75 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 42.0 + 0.5 * post_residual as f64;
    }

    // Reward leaving residuals that are multiples of a common chunk size
    let slots = post_residual / 10;
    score -= 5.0 * slots as f64;

    // Two-step lookahead around next_item_size
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 72.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 14.0;
            }
            if post_residual - next_item_size <= 1 {
                score -= 5.0 * future_density;
            }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size.min(20) {
                score -= 18.0 * (1.0 - progress);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.55 * waste;
            if waste > bin_residual as f64 {
                score += 28.0;
            }
        }
    }

    // Dead sliver band 10..20
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Align with mean residual field
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance existing bin: keep it attractive
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if post_residual == 0 && mean_residual >= item_size as f64 {
            score += 17.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 37.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size.max(next_item_size) {
            score -= 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize dead space: residuals too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if this was a tight fit anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score -= pressure * 0.5;

    // Time horizon: early in stream, tolerate new bins; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when fits exist
        score += 20.0 * (0.5 + progress);
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0; // next item is large, a fresh bin may be wise
        }
    } else {
        // Existing bin: bonus for matching mean residual (harmonious packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 4.0 / (1.0 + dev);
        score += (1.0 - progress) * 2.0; // slight early conservatism toward big residuals
    }

    // Prefer leaving residuals that are multiples of common small item sizes
    let mod_bonus = (post_residual % 10) as f64;
    score -= (10.0 - mod_bonus) * 0.2;

    score
}

