pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: prefer tight fits; dead-space penalty grows non-linearly with progress
    let mut score = pr * (1.0 + 0.9 * p2 + 0.6 * p3);

    // Smooth quadratic coupling between post_residual and fit ratio
    let coupling = (pr / cap) * (pr / cap) * (1.0 - fit_ratio);
    score += 25.0 * coupling;

    // Reward filling bins deeply, stronger mid-stream (smooth bump via sin-free polynomial)
    let bump = 4.0 * progress * (1.0 - progress);
    score -= bump * fit_ratio * (cap - pr);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Penalize opening new bins when plenty of fitting bins exist (smooth in open_bins_count)
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 8.0 + 15.0 * scarcity * (1.0 - p2);
    }

    // Lookahead: reward residual compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 6.0 * (1.0 - diff / cap) * (1.0 - diff / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" residue class (small, well-dividing remainders) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Modulo classes on post_residual: multiples of 10 and 5 are reusable slots.
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold: dead space is leftover too small for the
    // smallest plausible item (<= 10). Penalize tiny unusable remainders.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fraction of capacity wasted: quadratic penalty on large post_residual,
    // since big leftovers signal poor packing.
    let waste_frac = prf / cap;
    score += 18.0 * waste_frac * waste_frac;

    // Harmonic coupling with next item: reward if next_item_size divides or
    // nearly fits into post_residual (exact / near-exact chaining).
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx == pr {
            score -= 40.0; // next item exactly fills this bin
        } else if nx <= pr {
            let ratio = pr as f64 / nx as f64;
            // favor when next item consumes a large share of the leftover
            score -= 15.0 * ratio;
            if pr % nx == 0 {
                score -= 8.0; // harmonic divisibility bonus
            }
        } else {
            // next item cannot use this leftover: mild penalty scaled by gap
            let gap = (nx - pr) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
