    // New-bin candidate handling: an empty bin should only win when open bins
    // fit poorly. Base cost plus discount as stream matures / bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits: new bin is necessary
        }
    }

    // Mild preference for tighter bins relative to mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
