pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Tight fit (waste <= 5 but nonzero): moderate reward.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual closely matches the item (best-fit sharpening).
    let diff = bin_residual as f64 - item_size as f64;
    score += diff * 0.3;

    // Open-bins pressure: when many bins are open, discourage opening new ones;
    // when few are open, allow new bins more freely.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 - pressure * 4.0;
        // If the only fitting bin is this new bin, opening is necessary.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to use it rather than open a new bin.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is smaller than next item and nonzero, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.5;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (fills fuller bins first, keeps large-residual bins for future items).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late-stream urgency: as stream progresses, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    score
}

