            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless the current
    // item would leave a huge unusable gap in every fitting bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is more acceptable early (more future items to fill them).
        let openness = 1.2 - 0.8 * progress;
        let gap = post_residual as f64; // equals bin_capacity - item_size for new bin
        score += 25.0 * openness - 0.15 * gap;
    } else {
        // Slight preference for already-open bins as they accumulate.
        score += 0.02 * open_bins_count as f64;
    }

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (drain the small leftovers first).
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // Mild reward for filling bins completely (post_residual near zero).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    let mut score = prn * prn * cap;
    // smooth coupling of post-residual with stream progress
    score += (0.5 * prn * prn - 0.75 * prn + 0.25) * (progress * 30.0);
    // penalize dead space more as stream advances
    score += prn * prn * prn * (progress * 40.0 + 5.0);
    // last-chance bonus
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }
    // prefer bins whose residual matches next item size smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 10.0 * (-diff * diff * 200.0);
    }
    // crowd penalty: many open bins with low mean residual -> favor filling existing
    if !is_new_bin {
        score -= (mean_residual / cap) * 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    } else {
        // opening a new bin: penalize mildly, less late in stream
        score += 8.0 * (1.0 - 0.5 * progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets create discrete
    // "goodness" tiers for residual space (small residues in {0,5} are ideal).
    let pr = post_residual;
    let class = pr % 10;
    let class_reward: f64 = match class {
        0 => 12.0,
        5 => 9.0,
        1 | 2 | 3 | 4 => 4.0,
        _ => 0.0,
    };
    score -= class_reward;

    // Integer-division threshold: residuals that are dead space (too small
    // for the smallest plausible item) are heavily penalized.
    let dead_threshold = 10u32;
    if pr > 0 && pr < dead_threshold {
        score += 40.0 * (dead_threshold - pr) as f64;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // reward this placement (chaining harmony).
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        // Harmonic exact chain: post_residual == next_item_size
        if pr == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && pr > 0 {
        // Next item cannot use this residue at all: mild penalty scaled by
        // how much capacity is being wasted.
        score += 3.0 * (pr as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is big and existing residuals are tight.
        score += 20.0 - 25.0 * big_item - 15.0 * crowded - 5.0 * progress;
        // Modulo harmonic: fresh bin whose post-residual lands in a good
        // class gets an extra nudge toward opening.
        if class == 0 {
            score -= 6.0;
        }
    } else {
        // Favor tighter existing bins: reward small bin_residual fraction.
        score += 6.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 + (min_item - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // If this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave dead space
    // or the fit here is very loose.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; only attractive when this item would
        // leave a large awkward residual in existing bins.
        score = 55.0 - fill_ratio * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Prefer using bins with already-low residuals (consolidate waste).
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

