        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 - 0.5 * diff;
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            score += 0.3 * diff;
        }
    }

    // Reward tight fits (low post_residual) more aggressively
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize bins with residuals far from mean (avoid fragmenting average state)
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Penalize dead space that can't fit typical smallest items
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate: make it less attractive unless current fits are all poor
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 12.0;
        // but if lookahead suggests a fresh bin is better (item + next item pair well in fresh bin)
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0;
        }
        // late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    score
}

