pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into this bin's post-residual,
    // reward chaining placements; otherwise penalize leaving a gap that
    // only the next item's size could fill badly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely: reward proportionally to how snug.
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 40.0 * chain_tight;
        } else {
            // Dead space the next item cannot use: penalize.
            score += 15.0 * ((post_residual - next_item_size + 1) as f64 / item_size as f64);
        }
        // If next item exactly fills post-residual, big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream as
        // fragmentation typically grows.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 90.0 - 40.0 * progress;

        // Attractive if item is huge (fits poorly anywhere else).
        if item_size >= 70 {
            score -= 70.0;
        } else if item_size >= 50 {
            score -= 20.0;
        }

        // If open bins are already crowded on average, new bin is less wasteful.
        score -= 0.5 * mean_residual;

        // If few bins can fit the item, new bin is a reasonable fallback.
        if fitting_bins_count <= 2 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild reward scaled by how full it already is
        // (prefer filling nearly-full bins to consolidate).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 20.0 * fill * fill;

        // Prefer bins whose residual is close to the mean (keeps pool uniform),
        // penalize outliers mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Late-stream consolidation: as the stream ends, discourage opening new
    // bins and encourage squeezing into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0 * progress * progress;
    } else {
        score -= 25.0 * progress;
    }

    // Mild penalty for proliferating open bins.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
