}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic in post-residual scaled by stream progress
    score += 0.35 * (pr * pr / cap) * (0.5 + progress);

    // Reward tight fits with a smooth saturating term
    score -= 12.0 * tightness.powi(3) * (1.0 + 0.5 * progress);

    // Penalize dead space: small post-residual that is unusable relative to typical item sizes
    let dead = (pr / cap).powi(2);
    score += 8.0 * dead * (1.0 - fit_frac);

    // Last-chance bonus: smooth exponential reward when few fitting bins
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 6.0 * last_chance * (1.0 - progress);

    // Lookahead: reward if next item fits smoothly in post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        let miss = (nxt - pr).max(0.0) / cap;
        score -= 5.0 * fits_next.powi(2);
        score += 4.0 * miss.powi(2) * (0.5 + progress);
    }

    // Mild dispersion penalty relative to mean residual (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: smooth penalty/bonus via residual saturation
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress - 10.0 * (1.0 - last_chance) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space penalty: small unusable gaps heavily penalized, less if next item fits.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold && !next_consumes {
        score += (dead_threshold - post_residual) as f64 * 10.0 * (1.0 + future_density);
    }

    // Penalize gaps that cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0 * (0.5 + future_density);
    }

    // Reward bins that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + slack * 0.2;
        if slack <= 7.0 {
            score -= 60.0; // near-exact two-item fit
        }
        if post_residual >= next_item_size * 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3 + 20.0 * progress;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
    } else {
        // Placement into an existing bin whose post-residual exactly matches next item.
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        // Stranded-space penalty scaled by capacity fraction.
        if !next_consumes && post_residual > 0 {
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        // Exact lookahead match reward.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 {
            score -= 20.0;
        }
        // Dead ratio penalty for wasteful placements.
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
    }

    // Mild stream progression: late in the stream, waste hurts more.
    score += post_residual as f64 * 0.5 * progress;

    score
}

