        score += 25.0; // dead space (<12.5% of bin)
    } else if post_residual >= quarter && post_residual <= 2 * quarter {
        score -= 15.0; // sweet spot: half-to-three-quarters reusable space
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward tighter coupling.
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
            // Extra reward if next item exactly fills the bin afterwards.
            if next_item_size == post_residual {
                score -= 80.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow gap,
            // but less if this bin is the only fitting option (last chance).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin unless the item is large
    // relative to residual space in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early and for large items; penalize otherwise.
        score += 30.0 - 0.4 * item_size as f64 - 20.0 * progress;
        // If many open bins, discourage spreading.
        score += open_bins_count as f64 * 2.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.3;
    }

    // Mild preference for tighter existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are the worst outcome.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // unusable dead space (min item size 1..100, but small gaps rarely reused)
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap > 50.0 {
            // large residual is fine, mildly reward leaving big reusable space
            score -= 5.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Open-bins pressure: penalize accumulating too many open bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        score -= 8.0 + 0.1 * next_gap as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting this bin's slot
        score += 3.0;
    }

    // Progress-based tightening: as stream advances, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // Prefer bins below mean residual (consolidating emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            // reward chained fits, scaled by how tight the chain is
            score -= (30.0 * (1.0 - chain_waste as f64 / post_residual as f64)).max(0.0);
            // penalize if next item still leaves dead space
            if post_residual - next_item_size < 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize large post_residual that becomes dead space
            score += 5.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual above mean (keeps spread balanced)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin early in the stream or when many bins are open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but allow new bin if current item is huge and would leave bad residue elsewhere
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
