pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: only this bin fits the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            score -= (next_waste as f64).min(20.0) * 0.8;
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Prefer existing bins over opening new ones, more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by number of open bins and progress.
        score += 40.0 + 20.0 * progress + open_bins_count as f64 * 3.0;
    } else {
        score -= 15.0 + 10.0 * progress;
    }

    // Global residual pressure: if mean residual is low, conserve space in fat bins.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = (1.0 - progress) * norm_pr.powi(2) + progress * norm_pr;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 2.0 * progress) * 30.0 * tightness * (item_size as f64 / cap);

    // Penalize dead space that likely cannot host the next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 15.0 * (1.0 + progress);
    } else if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        score += 5.0 * (gap / cap).powi(2);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residuals near the mean (keeps bin population balanced)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: keep it attractive only when post_residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that can never be reused are wasteful.
    // Harmonic classes: classify post_residual into reuse bands via integer division.
    let band = post_residual / 10; // 0..=10 bands of width 10
    match band {
        0 => score -= 40.0,            // near-perfect fit: residual < 10, almost dead but tight
        1 => score -= 55.0,            // sweet spot 10..19: fits the smallest items
        2 => score -= 45.0,            // 20..29
        3 => score -= 35.0,            // 30..39
        4 => score -= 25.0,            // 40..49
        5 => score -= 15.0,            // 50..59
        6 => score -= 8.0,             // 60..69
        7 => score -= 4.0,             // 70..79
        8 => score -= 2.0,             // 80..89
        9 => score -= 1.0,             // 90..99
        _ => score -= 0.5,             // full
    }

    // Tightness reward: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: penalize if the next item cannot fit into the post residual,
    // unless this is the last chance bin (fitting_bins_count == 1).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item won't fit here; if this bin was our only option, opening
            // a new bin for the next item is unavoidable anyway -> mild penalty.
            score += 12.0;
        } else {
            // Next item chains perfectly: strong reward, scaled by how snug it is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 15.0 * snug;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped" and a good candidate to close out.
    let res_gap = mean_residual - post_residual as f64;
    score += 0.3 * res_gap;

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent fit. Penalize it progressively
    // with how many bins are open (prefer consolidating into open bins).
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge, packing it into a fresh bin is natural.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        // Late in the stream, avoid spawning bins that will be mostly wasted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && open_bins_count > 0 {
            score += 10.0 * progress;
        }
    }

    // Harmonic modulo bonus: post_residual divisible by 5 or 10 tends to
    // accommodate more future size combinations (common item sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let dead_zone = 10.0f64; // gaps below min item size (1..10) can never be reused
    if post_residual >= 1 && post_residual < 10 {
        score += dead_zone * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin
