        }
    } else {
        // Prefer filling bins with larger residuals when few bins are open.
        score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;
        // Lookahead: if next item fits exactly in post_residual, reward this placement.
        if next_item_size > 0 && (post_residual as i64) == (next_item_size as i64) {
            score -= 20.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            // next item won't fit here; mildly penalize leaving a gap it could have used.
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
