    // are nearly full; prefer them only if the fit is tight.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless it enables a great
    // 2-step chain (item + next item fill it well).
    if bin_residual == bin_capacity {
        let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if next_item_size > 0 && chain_fill >= 0.98 {
            score -= 150.0 * chain_fill; // open a new bin for a near-perfect chain
        } else {
            score += 80.0; // discourage opening bins when open bins fit fine
