    }

    // Mild progression term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Slight preference for bins below mean residual (denser packing) when fit is decent.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

