pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted residual, damped by stream progress
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that cannot host the lookahead item (smooth gate)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        if gap > 0.0 {
            score += 4.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 3.0 * ((-gap) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open relative to progress (fragmentation control)
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress) * pr_norm;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate: neutral-ish, penalized slightly so it loses to good fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 2.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that fall into "dead zones"
    // (too small for typical items) should be penalized more.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as u32; // 8 harmonic classes of capacity
    let dead = post_residual < 10; // unusable dead space (min item size ~ small)
    if dead {
        score -= 25.0; // perfect fill: strongly reward
    } else {
        // penalty grows for residuals in awkward mid classes
        let class_penalty = match class {
            0 => 6.0,  // tiny leftover, nearly dead
            1 => 2.0,
            2 => 0.0,
            3 => -1.0, // ~40-50% residual is reusable
            4 => -2.0, // ~50% residual is very reusable
            5 => -1.0,
            6 => 1.0,
            _ => 3.0,  // nearly empty bin left behind
        };
        score += class_penalty;
    }

    // Lookahead: reward when post_residual can still hold the next item exactly well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportionally to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item won't fit: penalize if we leave a moderately sized orphan
            score += 4.0 * frac;
        }
        // integer-division threshold coupling: if post_residual is within one
        // harmonic step of next_item_size, treat as a near-perfect chain
        if post_residual >= next_item_size && (post_residual / 8) == (next_item_size / 8) {
            score -= 6.0;
        }
    } else {
        // last item in stream: just fill tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when open bins are congested or mean residual is small
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        let scarcity = (1.0 - (mean_residual / bin_capacity as f64)).clamp(0.0, 1.0);
        score -= 10.0 + 15.0 * congestion * scarcity;
    } else {
        // prefer reusing bins as open bins accumulate
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Stream progression: late in stream, tighten packing (favor exact fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Modulo harmonic bonus: post_residual divisible classes (multiples of 25)
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
    let future_density = (total_items . saturating_sub (step_index)) as f64 / total_items . max (1) as f64 ;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual ;
    let tightness = post_residual as f64 / bin_capacity as f64 ;

    // base tightness reward
    score -= (1.0 - tightness) * 18.0 ;

    if post_residual == 0 { score -= 530.0 ; }
    else if post_residual <= 4 { score -= 235.0 ; }

    // small sliver penalty unless next item consumes it
    if post_residual > 0 && post_residual < 10 && ! next_consumes {
        score += 55.0 + 0.75 * post_residual as f64 ;
    }
    if post_residual > 0 && post_residual < item_size . min (80) {
        score += 42.0 + 0.5 * post_residual as f64 ;
    }
    // reward residuals that are multiples of common sizes (future divisibility)
    let slots = post_residual / 10 ;
    score -= 5.0 * slots as f64 ;

    if fitting_bins_count <= 2 && bin_residual != bin_capacity { score -= 17.0 ; }

    // new-bin penalty: scale with fitting options and progress
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 + 20.0 * progress + 0.6 * item_size as f64 ;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0 ; }
    }

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0 ;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 72.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 38.0 ; }
            if post_residual >= next_item_size * 2 { score -= 60.0 ; }
            if slack >= 10.0 && slack <= 30.0 && slack as u32 >= item_size . min (20) {
                score -= 18.0 * (1.0 - progress) ;
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0 ; }
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 0.55 * waste ;
            if waste > bin_residual as f64 { score += 28.0 ; }
        }
        // prefer residuals close to mean residual (future fit likelihood)
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score -= 12.0 * (1.0 - dev / bin_capacity as f64) ;
        }
        // lookahead: bin can hold item + next item with minimal leftover
        if bin_residual >= item_size + next_item_size {
            let pair_left = (bin_residual - item_size - next_item_size) as f64 ;
            score -= 22.0 * (1.0 - pair_left / bin_capacity as f64) * (1.0 - progress) ;
        }
        // next item fits current residual even after placing item elsewhere
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress) ;
        }
    }

    // dead-space ratio penalty for stranded capacity
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
        if dead_ratio > 0.45 && ! next_consumes { score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress) ; }
        if ! next_consumes && post_residual < 25 {
            score += 10.0 * (25.0 - post_residual as f64) * future_density ;
        }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress) ; }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0 ; }
        // pair-completion: placing item leaves residual exactly matching next item
        if post_residual == bin_residual - item_size && next_consumes { score -= 15.0 * (1.0 - progress) ; }
    }

    score += (mean_residual - bin_residual as f64) * 0.09 ;
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Penalize large post-residuals less when they can hold the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    let open_pressure = open_bins_count as f64 * 0.5;
    score += open_pressure;

    // New-bin candidate: neutral baseline with mild pressure.
    if bin_residual == bin_capacity {
        score = 100.0 + open_pressure - (post_residual as f64);
    }

    // Tight-fit preference: reward small residuals relative to item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Slight phase adjustment for stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
