            score += 9.0;
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual {
            score += 12.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Shared residual-aware terms
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && !next_consumes {
            score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 {
            score -= 6.0;
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 {
            score -= 12.0;
        }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain: post_residual == next_item_size is ideal.
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 200.0 * (1.0 - gap);
            // Bonus if the next item then fills the bin completely.
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // Next item won't fit here afterward; penalize proportionally to waste.
            let waste = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 150.0 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when they fit well.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin opening unless current bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0);
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bin when mean residual is low (open bins nearly full) or item huge.
        let openness = 2.0 * pressure + (1.0 - item_size as f64 / bin_capacity as f64);
        score += 400.0 - 350.0 * openness - 50.0 * progress - 100.0 * crowded;
        // Never open a new bin if a perfect fit exists elsewhere is already handled
        // by their large negative bonuses.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space avoidance: unusable slivers are heavily penalized.
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual < 10 && !next_consumes {
        score += 45.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Exact lookahead fit: strongly reward perfect pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 220.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.3;
            if slack > 0.0 && slack <= 7.0 {
                score -= 30.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 15.0 * (1.0 - progress);
            }
        } else {
            // Next item cannot use the post-residual: penalize small dead gaps.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: only fitting option -> strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count <= 2 && !is_new_bin {
        score -= 8.0;
    }

    // New-bin candidate handling: discourage opening bins unless the item is
    // large and the stream is early (big items benefit from fresh capacity).
    if is_new_bin {
        score += 14.0 + open_bins_count as f64 * 2.5 + progress * 10.0;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.4;
    }

    // Consolidation: prefer fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }
    score += (mean_residual - bin_residual as f64) * 0.08;

    // Dead-ratio pressure: leaving a large fraction of the bin unused is risky
    // late in the stream.
    if !is_new_bin && post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 12.0 * stranded * (1.2 - progress);
        }
    }

    // Two-item lookahead: perfect chain fit (item + next exactly fills residual).
    if next_item_size > 0 && !is_new_bin && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size <= 2 {
        score -= 18.0 * (1.0 - progress);
    }

    // Late-stream tightening: fewer remaining items -> be pickier about fits.
    if post_residual > 0 && !next_consumes && post_residual < 30 {
        score += 10.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: discourage opening new bin unless residual is dead space
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 40.0;
        // Open it if item leaves a residue that no typical next item could use
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // near-perfect fill in a fresh bin is fine, but only if forced
        }
        // Later in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Fewer open bins -> cheaper to open a new one
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: penalize if the next item fits better in this bin's post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Next item can follow: reward leaving usable space, especially near-exact
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: dead-space penalty scaled by progress
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 5.0 + 10.0 * progress;
        }
    }

    // Global state coupling: if mean residual is large, prefer bins below mean
    // (keeps residual distribution tight, preserving flexibility)
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = item_size as f64 / cap;
    let post_frac = post / cap;

    // Base: penalize leftover space with a non-linear (quadratic) blowup on large dead space.
    let mut score = post + 40.0 * post_frac * post_frac;

    // Reward tight fits (small post_residual) more aggressively as the stream progresses.
    score -= (1.0 - post_frac) * (1.0 - post_frac) * (30.0 + 40.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin smoothly, unless the fit
    // into existing bins would be very poor (large post_residual relative to capacity).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Smooth penalty that shrinks when post_residual would be small anyway
        // (i.e., item nearly fills a fresh bin).
        score += 18.0 * (1.0 - post_frac * post_frac) + 10.0 * (1.0 - progress);
    } else {
        // Mild reward for keeping bin count stable, stronger early in the stream.
        score -= 6.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement smoothly (quadratic in how close next_item_size is).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).abs();
        let gap_frac = gap / cap;
        score -= 22.0 * (1.0 - gap_frac) * (1.0 - gap_frac) * post_frac;
        // Penalize leaving residual that no plausible item can use (too small).
        if post < next_item_size as f64 && post > 0.0 {
            score += 8.0 * (1.0 - post / next_item_size as f64);
        }
    }

    // Coupling with mean residual: prefer bins whose post residual moves the
    // fleet mean toward compactness; smooth polynomial interaction.
    let mean_frac = mean_residual / cap;
    score += 10.0 * post_frac * mean_frac - 5.0 * fit_frac * fit_frac;

    // Slight preference for bins with less residual before placement (best-fit flavor).
    score += 0.05 * bin_residual as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes mod 10
    let class = post_residual % 10;
    // Penalize "awkward" residual classes (small nonzero leftovers)
    if class > 0 && class < 5 {
        score += (5 - class) as f64 * 2.5;
    } else if class == 0 {
        score -= 4.0; // perfectly divisible residual is great
    }

    // Large post_residual = wasted capacity; superlinear penalty
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.6;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 3.0; // dead space for the next item
        } else {
            let slack = post_residual - next_item_size;
            score -= (slack as f64).min(10.0) * 0.3;
            // harmonic match: next item leaves residual in a good class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        }
    } else {
        // last item: prefer tightest fit strongly
        score *= 1.2;
    }

    // New-bin candidate handling: neutral-ish baseline so it loses only
    // when an open bin gives a genuinely good fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 6.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin anyway
        }
        // late in the stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Tie-break toward consolidating many open bins
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) after placement.
    // Gaps in (0, 10) are almost certainly unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits (small but harmless leftovers, e.g. exact fill).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // Slight penalty proportional to how much residual this bin holds vs the mean,
    // favoring bins with less remaining space (better packing of fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin is a good fit
    // (i.e. the item barely fits anywhere or many bins would be left with dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // If this is the only fitting option, opening a new bin is reasonable.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect 2-step fit: post_residual exactly equals next item size -> huge reward.
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0;
        } else if post >= nxt {
            // Next item still fits: reward proportionally to how tight the pair-packing is.
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 20.0 * tightness;
        } else {
            // Next item would NOT fit: penalize dead space that cannot serve the next item.
            score += 10.0 + 0.5 * (post / nxt);
        }

        // Combined pair-fill bonus: how full the bin becomes after two items.
        let pair_fill = (item_size as f64 + nxt) / bin_capacity as f64;
        if pair_fill <= 1.0 {
            score -= 15.0 * pair_fill;
        } else {
            score += 5.0 * (pair_fill - 1.0);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight progress-aware pressure: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that neither this nor the next item can use.
    if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead synergy: reward bins whose leftover fits the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0 - gap as f64;
        } else {
            score += gap as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let waste = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let mut penalty = 15.0 + 60.0 * waste;
        if fitting_bins_count == 0 {
            penalty = 0.0; // no alternative, must open
        }
        if fragmentation > 25.0 && item_size > 50 {
            penalty -= 20.0; // large item into fresh bin when bins are fragmented
        }
        if open_bins_count < 3 && progress < 0.2 {
            penalty -= 10.0; // early stream: allow spreading
        }
        score += penalty.max(0.0);
    } else {
        // Slight preference for bins above mean residual (balance load).
        score += (bin_residual as f64 - mean_residual) * 0.1;

        // Fewer fitting bins => scarcer capacity, favor reuse.
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: keep residuals large enough for big arrivals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 15 && progress > 0.5 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
