    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (0.5 + 0.5 * progress) * cap;
    score += 0.8 * coupling;

    // reward tight fits, more so early in the stream
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    // last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * pr_norm;
    }

    // new-bin candidate: penalize opening a bin unless residual is tight
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues modulo capacity quarters
    let q = bin_capacity / 4; // 25
    let r = post_residual % q;
    let class = post_residual / q; // 0..=4

    // Penalize residuals that fall into "dead" classes (too small to fit typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward residuals that are exact multiples of small harmonic units (likely reusable)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize odd residues in the low quarter (hard to pair)
    if class == 0 && r > 0 {
        score += (q - r) as f64 * 0.4;
    }
    // Reward mid-band residuals (class 2) that can absorb medium items
    if class == 2 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            // penalize wasting a bin that cannot host the lookahead item
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are bad
    if bin_residual == bin_capacity {
        // opening a fresh bin: neutral-ish score anchored at capacity
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else if fitting_bins_count <= 2 {
        // scarce fits: reward using an existing bin
        score -= 15.0;
    }

    // Progress-aware mild pressure to consolidate late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.15;

    // Encourage bins far below mean residual (keeps a spread of sizes)
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Tight fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

