    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Non-linear waste penalty grows with progress (parent idea, kept)
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);

