    }
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - pr;
        let future_help = if next_consumes { 1.0 } else { 0.0 };
        score += dead_sliver * (1.55 - future_help);
    }

    // Lookahead: exact fit for next item is a jackpot
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_consumes {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack <= 7.0 { score -= 72.0; }
            if slack > 0.0 && slack < 12.0 { score += 38.0; }
            if post_residual >= next_item_size * 2 { score -= 60.0 * (1.0 - progress); }
