        if bin_residual - item_size - next_item_size <= 3 { score -= 20.0 * (1.0 - progress); }
    }

    // Prefer bins below the mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 17.0;
    }
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize scaled by how many bins already fit the item
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0; }
