    let stranded = pr_norm;
    if next_item_size == 0 || next_item_size > post_residual {
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual > 0 && post_residual < 25 {
            score += 10.0 * (25.0 - pr) * future_density;
