fn slack_like (post : u32 , next : u32) -> u32 { post - next }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: if next item fits exactly into the post residual,
    // this bin is a perfect 2-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills leftover.
            let leftover2 = post_residual - next_item_size;
            score -= 15.0 - (leftover2 as f64) * 0.3;
        } else {
            // Next item does not fit here: penalize leaving a gap that
            // is close to but smaller than next_item_size (dead space).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += (11 - gap) as f64 * 1.5;
            }
        }
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in stream, opening new bins is cheaper than hoarding dead space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Coupling with mean residual: prefer bins whose post residual stays
    // near the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Prefer filling more-full bins (low residual relative to capacity).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creating space the next item cannot use
        }
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 30.0;
        // Early in stream: opening bins is cheaper (future items can fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // Many open bins with slack: opening another is wasteful.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Very poor fit elsewhere: allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: late in stream, be more conservative with slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with progress
    let poly = (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 2.0 * progress);
    score -= poly * 30.0;
    // tight-fit reward, stronger late in the stream
    let tight = 1.0 - (pr / cap).powi(2);
    score -= tight * (10.0 + 25.0 * progress);
    // penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += (-gap) * (1.0 + progress);
        } else {
            score -= (gap / cap) * 8.0 * (1.0 - progress);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // mildly prefer bins with smaller residual relative to mean
    score += (pr - mean_residual) * 0.15;
    // new-bin candidate penalty grows with open bins and progress
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
    }
    score
}

