pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more likely to be filled exactly later.
    let r = post_residual;
    let mut bonus = 0.0;
    for d in [10u32, 20, 25, 50] {
        if d > 0 && r % d == 0 && r > 0 {
            bonus += 6.0 * (d as f64 / 10.0);
        }
    }
    score -= bonus;

    // Penalize small dead space (hard to reuse): residual in (0, 10)
    if r > 0 && r < 10 {
        score += 25.0;
    }
    // Penalize awkward mid-range residuals not divisible by 10
    if r >= 10 && r % 10 != 0 {
        score += 8.0;
    }

    // Lookahead: reward residuals that exactly fit the next item (k=2 lookahead)
    if next_item_size > 0 {
        if r == next_item_size {
            score -= 40.0;
        } else if r > next_item_size && (r - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if r < next_item_size && r > 0 {
            score += 15.0; // next item can't use this residual
        }
        // Harmonic match: next item divides residual evenly
        if next_item_size > 0 && r % next_item_size == 0 && r > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (mean_residual - item_size as f64).abs();
        score = 30.0 + tight * 0.5 - progress * 10.0
            + if next_item_size > 0 && next_item_size >= bin_capacity { 0.0 } else { 5.0 };
        // If only one bin fits, discourage opening a new bin
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * (r as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are wasted.
    if post_residual < 10 {
        score += 60.0; // unusable gap penalty
    } else if post_residual <= 20 {
        score += 15.0; // risky gap: only tiny items can use it
    }

    // Reward tight fits (small post_residual that is still usable).
    score -= (100.0 - post_residual as f64) * 0.25;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space blocks the known next item
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Encourage filling bins that are already relatively full.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with stream progression.
        score += 30.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If many bins are open and fragmented, opening fresh can be fine.
        if open_bins_count > 5 {
            score -= 10.0;
        }
        // Never open a new bin when this is the only fitting option elsewhere.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
