    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement; if next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // next item can't go here; slight penalty unless post residual tiny
            if post_residual >= 10 {
                score += 5.0;
            }
        }
