        if progress < 0.2 && item_size > 60 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild reward scaled by how much room it saves globally.
        score -= 5.0 * (1.0 - progress);
