    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 ;
        score += 20.0 * progress ;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0 ; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 { score -= 11.0 * (1.0 - progress) ; }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 { score -= 37.0 * (1.0 - progress) ; }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size { score -= 19.0 * (1.0 - progress) ; }
        if post_residual >= item_size . max (next_item_size) && post_residual < item_size . max (next_item_size) + 6 { score -= 13.0 * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 { score -= 20.0 ; }
        if fitting_bins_count >= 2 && post_residual >= item_size { score += 12.0 * (1.0 - progress) ; }
        if mean_residual >= item_size as f64 * 1.2 && open_bins_count > 1 { score += 9.0 * (1.0 - progress) ; }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 30 { score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0 ; }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual { score += 22.0 * (1.0 - progress) ; }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size . max (next_item_size) { score -= 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual < item_size . min (next_item_size . max (1)) { score += 9.0 ; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0 ; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0 ; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual { score += 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 { score -= 25.0 * (1.0 - progress) ; }
    }
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
        if dead_ratio > 0.45 && ! next_consumes { score += 4.0 * (dead_ratio - 0.45) * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0 ; }
        let stranded = post_residual as f64 / bin_capacity as f64 ;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress) ;
            if post_residual < 25 { score += 10.0 * (25.0 - post_residual as f64) * future_density ; }
        }
        if next_consumes && post_residual >= next_item_size * 2 { score -= 8.0 * (1.0 - progress) ; }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 { score -= 20.0 * (1.0 - progress) ; }
        if ! next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual { score += 5.0 * future_density * (1.0 - stranded) ; }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic growth of residual cost, tempered by stream progress
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: smooth coupling between fill ratio and progress
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 10.0 * fill * fill * (1.0 - 0.3 * progress);

    // Lookahead: if next item exactly fits post_residual, strongly favor this bin
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 / (1.0 + gap * gap / 25.0);
        score -= 8.0 * fit_next;
        // Penalize leaving residual slightly too small for next item (dead space)
        if pr < next_item_size as f64 {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when residuals are large or stream is early
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 20.0 + 25.0 * (1.0 - pressure) - 10.0 * (1.0 - progress);
    }

    // Mild preference for bins with residuals above the mean (balance preservation)
    score += 3.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division harmonic classes: class 0 = tiny dead space (<=10),
        // class 1 = medium (<=25), class 2 = large. Penalize proportionally non-linearly.
        let class = post_residual / 10; // 0..10 harmonic buckets
        score += (class as f64).powi(2) * 0.8;

        // Dead-space that cannot fit the smallest plausible item (1..100 unknown dist):
        // residual < 10 is nearly unusable -> extra penalty.
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // reward strongly if it fits, penalize if next item would be stranded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 1.5; // tighter follow-up fit is better
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins unless the fit is bad; penalize opening a new bin
    // increasingly when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 90.0;
        score += open_bins_count as f64 * 6.0;
        score += mean_residual * 0.5;
        // Late in the stream, opening new bins is safer (avoid stranding items)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    } else {
        // Reuse bonus scaled by how full the bin already is (encourage packing tight).
        let used = (bin_capacity - bin_residual) as f64 / cap;
        score -= used * 25.0;
    }

    // Mean-residual harmony: bins far below mean residual are good to fill down.
    score -= (mean_residual - post).clamp(-50.0, 50.0) * 0.3;

    // Modulo-style tie-breaker on post_residual to break harmonic symmetry:
    // prefer residuals that are multiples of 10 (likely to fit future round sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
