pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable (min item = 1, but
    // gaps far below typical item sizes waste capacity). Penalize gaps that no realistic
    // item can fill well.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 // tiny gap: essentially dead space
        } else if post_residual < 20 {
            25.0
        } else if post_residual < 30 {
            10.0
        } else {
            0.0
        };
        score += dead;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: mild penalty proportional to tightness
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this is a huge item.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let crowded = if mean_residual < item_size as f64 * 0.8 { 1.0 } else { 0.0 };
        score += 40.0 - 12.0 * pressure - 20.0 * crowded;
        // Late in the stream, slightly discourage proliferating bins.
        score += 10.0 * (step_index as f64 / total_items as f64);
    }

    // Open-bin pressure: mildly favor filling existing bins as their count grows.
    score += 0.6 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual relative to capacity).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: this bin becomes exactly usable by the next item.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: good chaining.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.30 * waste;
        }
    }

    // Compare against mean residual of open bins: favor bins that get
    // closer to (or below) the mean, i.e. consolidating space.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let diff = pr - mean_residual;
        score += 0.15 * diff;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize leaving large unusable gaps (below typical item size range).
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent 2-step chain.
    if bin_residual == bin_capacity {
        // Default penalty so open bins with good lookahead beat it.
        score += 15.0;
        // But if next item is large and current bin would strand it, allow new bin.
        if next_item_size > 0 && next_item_size > post_residual.max(next_item_size) {
            // (post_residual of empty bin == capacity, so chain always fits)
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening fresh bins is less harmful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Slight preference for bins with larger residual when item is large
    // (avoid fragmenting already-tight bins unnecessarily).
    if item_size > bin_capacity / 2 {
        score += 0.10 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space relative to typical item sizes (unknown distribution,
    // so use the mean residual as a proxy for "useful" chunk size).
    if post_residual > 0 {
        let dead = post_residual as f64;
        let useful = mean_residual.max(1.0);
        if dead < useful {
            score -= 8.0 * (1.0 - dead / useful); // small leftover that's still usable
        } else {
            score += 4.0 * ((dead - useful) / useful); // large unusable gap
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item can't fit post-residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer existing bins generally; only prefer a new bin when current bin's
    // post-residual would be very wasteful and many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or when
        // open bins are nearly full on average.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let mut new_bin_cost = 18.0;
        new_bin_cost -= 10.0 * avg_fill;          // open bins nearly full -> new bin cheaper
        new_bin_cost -= 5.0 * progress;           // late stream -> consolidate less
        if open_bins_count == 0 {
            new_bin_cost = -100.0;                // must open a bin
        }
        score += new_bin_cost;
    }

    // Mild pressure toward filling existing bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 4 {
        score -= 150.0;
    }

    // Dead-space avoidance: small unusable gaps penalized.
    if post_residual > 0 && post_residual < 15 && !next_consumes {
        score += 40.0 + 0.8 * (15 - post_residual) as f64;
    }

    // Penalize gaps that cannot host the lookahead item.
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
        if waste > bin_residual as f64 {
            score += 25.0;
        }
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward bins that can host the next item after placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        score -= 90.0 * (1.0 - slack / bin_capacity as f64);
        if next_item_size == post_residual {
            score -= 200.0;
        }
        if slack > 0.0 && slack <= 7.0 {
            score -= 40.0;
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Consolidation pressure with many open bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 * fitting_bins_count as f64 + 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 25.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
    } else {
        // Mean-residual coupling: prefer bins near the fleet's average slack.
        score += (mean_residual - bin_residual as f64) * 0.1;
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // Two-item lookahead: bin can host item + next item snugly.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            let tail = bin_residual - item_size - next_item_size;
            if tail <= 3 {
                score -= 18.0 * (1.0 - progress);
            }
        }
        // Post-residual just above next item: excellent chain fit.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        // Dead ratio penalty late in stream.
        if post_residual > 0 {
            let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
            if dead_ratio > 0.6 && !next_consumes {
                score += 7.0 * (dead_ratio - 0.6) * (1.0 - progress);
            }
            let stranded = post_residual as f64 / bin_capacity as f64;
            if next_item_size == 0 || next_item_size > post_residual {
                score += 12.0 * stranded * (1.2 - progress);
                if post_residual < 25 {
                    score += 8.0 * (25.0 - post_residual as f64) * future_density;
                }
            }
        }
    }

    // Late-stream waste pressure.
    score += post_residual as f64 * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual (waste), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, large residuals are fine (bins get reused later);
    // late in the stream, residual waste is more costly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap * 0.5;

    // Perfect fit reward (smooth quadratic decay around zero residual)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize residuals that can't fit the next item,
    // reward residuals that snugly fit it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let snug = 1.0 - ((pr - n) / cap).abs();
            score -= 12.0 * snug * snug;
        } else {
            let gap = (n - pr) / cap;
            score += 15.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.signum();

    // New-bin candidate: penalize mildly so open bins are preferred,
    // unless its residual dominance (smoothly scaled by progress) wins
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    // Many open bins: encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual classes are good fits.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Reward near-perfect fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Modulo arithmetic: residuals divisible by common item granularities (10s)
    // remain reusable; penalize awkward odd residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    } else if post_residual % 5 == 0 {
        score -= 10.0;
    } else {
        score += 8.0; // awkward dead space
    }

    // Fractional thresholds on capacity fractions.
    if frac < 0.1 {
        score -= 40.0;
    } else if frac < 0.2 {
        score -= 15.0;
    } else if frac > 0.6 {
        score += 40.0; // leaving more than 60% empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 60.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item won't fit here regardless; slight bonus for larger residual
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is large.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 150.0 - pressure * 5.0;
        if bin_residual - item_size >= 70 {
            score -= 100.0; // big item into fresh bin is fine
        }
    }

    // Progress-based scaling: early on, be frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Small tie-breaker toward tighter bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
