    if bin_residual == bin_capacity {
        score += 55.0 + 0.6 * item_size as f64 ;
        score += 18.0 * fitting_bins_count as f64 ;
        score += 18.0 * progress ;
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 40.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 25.0 ; }
        if mean_residual >= item_size as f64 { score += 15.0 ; }
    }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 430.0 ; }
