    // item (or the next item) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 {
        let dead = post_residual < min_item || (next_item_size > 0 && post_residual < next_item_size);
        if dead {
            // Penalize unusable gaps proportionally, worse near end of stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 + 40.0 * progress + post_residual as f64 * 0.5;
