    // Open-bin pressure: with many bins open, discourage opening new bins
    // (a new empty bin has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    } else {
