    // Prefer bins whose residual is below average (tighter bins first),
    // leaving roomier bins for larger future items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // reward; if next item would be blocked by a small gap, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

