pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum plausible item are pure waste.
    let min_item = 1u32.max(next_item_size.min(item_size));
    if post_residual > 0 && post_residual < min_item {
        score += 60.0;
    }
    // Penalize residual that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening yet another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (consolidate space into emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
