pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit).

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // strongly reward this bin (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Reward proportional closeness of next item to leftover.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot use the leftover: penalize dead space.
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // Extra penalty if next item could have fit here instead (misordering).
            if next_item_size <= bin_residual {
                score += 10.0;
            }
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving residual far above mean wastes capacity; near-zero residual is good.
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_mean = if mean_residual.is_finite() { mean_residual / cap } else { norm_post };
    score += 20.0 * (norm_post - norm_mean).max(0.0);
    score -= 10.0 * (norm_mean - norm_post).max(0.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 {
        score -= 25.0;
        // But if residual would still be large and next item is big, new bin may win.
        if post_residual as f64 > cap * 0.5 && next_item_size as f64 > post_residual as f64 {
            score += 15.0;
        }
    }

    // Early in stream: slightly discourage hoarding many open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a neutral-ish score so it only
    // wins when open bins have bad fits.
    if bin_residual == bin_capacity {
        score = cap * 0.45 - 0.1 * (open_bins_count as f64);
        // If next item is small, reusing open bins is cheap; discourage new bin.
        if next_item_size > 0 && next_item_size <= 30 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of score as post_residual shrinks.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Dead-space penalty: post_residual that is too small to ever host a
    // typical future item (below the min item size 1..100 => use 10 as
    // practical floor) is wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.min(40) {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a perfect chain — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot use this bin's remainder; mild penalty that
            // grows with how much space will be stranded.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 18.0;
    }

    // Global pressure: many open bins with low mean residual suggests the
    // stream is fragmenting; prefer consolidating into tighter fits.
    let pressure = mean_residual / bin_capacity as f64;
    score += 10.0 * pressure;

    // If open bins are plentiful and this bin is near-full already, using
    // it closes it out — reward closing bins to reduce open-bin count.
    if post_residual <= 5 && open_bins_count > 2 {
        score -= 10.0;
    }

    // Time horizon: early in the stream, keep bins flexible (penalize
    // very small post residuals slightly more since future variety is
    // unknown); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 10.0 * (0.3 - progress);
    } else if progress > 0.7 {
        score -= 4.0 * progress;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing existing bins with decent fits; only favor a new bin
    // when every alternative would strand a lot of space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fills; later, penalize wasted space quadratically.
    let tightness = pr / cap;
    score += 2.0 * tightness * tightness * (1.0 + 3.0 * progress) * cap * 0.1;

    // Reward near-perfect fits (small post_residual) with a smooth cubic discount.
    let perfect = 1.0 - tightness;
    score -= 1.5 * perfect * perfect * perfect * cap * 0.05;

    // Lookahead coupling: if the next item exactly fits the post-residual, strongly favor.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_q = 1.0 - (gap / cap).min(1.0);
        score -= 4.0 * match_q * match_q * match_q;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (smooth interaction with post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = pr / cap;
        score -= 3.0 * (1.0 - waste) * (1.0 - waste);
        score += 2.0 * waste * waste;
    }

    // New-bin candidate: score proportional to how much space would remain unused
    // relative to current mean residual across open bins; discourage premature opens.
    if bin_residual == bin_capacity {
        score = cap - fit + 0.5 * mean_residual + 5.0 * progress;
        // Allow opening a new bin when open bins are nearly full on average.
        score -= (mean_residual / cap) * 10.0 * (1.0 - progress);
    }

    // Mild penalty for bin sprawl when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
