    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 15 && !next_consumes {
        score += (15 - post_residual) as f64 * 9.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for next arrival).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 18.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        // Exact lookahead fit is extremely valuable.
        if next_item_size == post_residual {
            score -= 150.0;
        }
        // Two-item lookahead: bin can host next item twice.
        if post_residual >= next_item_size * 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // Post-fit slack small enough that only tiny items fit: mild penalty.
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < 8 && slack < item_size.min(15) {
            score += 12.0;
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 22.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize so new bins open only when fits are bad,
    // scaled by mean residual (large mean residual = plenty of room elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.35 + 15.0 * progress;
        // Early large items: opening a fresh bin is fine.
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // If the fresh bin can host both this and the next item, it is attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose post-fit residual stays above the mean (still usable).
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 6.0 * (1.0 - progress);
        }
        // Post-fit residual barely above next item: great chaining opportunity.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 14.0;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // If mean residual is small (bins nearly full), squeeze into existing bins.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    score -= 2.5 * fit_ratio * fit_ratio * (bin_residual as f64);

    // Harmonic classes on post_residual: modulo thresholds of capacity.
    let class = post_residual % 25;
    if class == 0 {
        score -= 8.0; // perfect harmonic slot (0,25,50,75)
    } else if class == 10 || class == 20 {
        score -= 3.0; // mid-friendly classes
    } else {
        score += 1.5; // awkward dead-space classes
    }

    // Dead-space penalty: residuals below 10 are unusable for any item.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let nfit = next_item_size as f64 / pr.max(1.0);
            score -= 5.0 * nfit;
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // no existing bin fits well or mean residual is already tiny.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 20.0 - 15.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin useful for a bigger follow-up item
        }
        if post_residual as u32 == bin_capacity - item_size {
            score += 0.0;
        }
    }

    // Stream progression: early on, be picky; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * fit_ratio;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space that few future items can use (items >= 10).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 0.5 * slack;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: slightly penalize so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-based tightening: later in stream, avoid waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // If post_residual can't fit next item, penalize proportionally
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins with residual near mean are "typical";
    // prefer placing into bins whose residual deviates less after placement.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space creation mildly (good), but large post_residual
    // when few bins are open is acceptable (score already = post_residual).

    // New-bin candidate: keep it moderately attractive only when fit is bad.
    if bin_residual == bin_capacity {
        score = post_residual as f64;
        // neutral baseline; lookahead reward still applies above
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fit: strong rewards (borrowed stronger weights).
    if post_residual == 0 {
        score -= 480.0;
    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space avoidance for tiny slivers that nothing will fill.
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 45.0 + 0.7 * post_residual as f64;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Lookahead chaining: reward bins that can host the next item too.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 320.0;
        } else {
            score -= 60.0 * (1.0 - slack / bin_capacity.max(1) as f64);
            if slack > 0.0 && slack <= 6.0 {
                score -= 45.0;
            }
            if slack > 0.0 && slack < 12.0 && slack as u32 >= item_size.min(10) {
                score += 18.0;
            }
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;

    // Consolidation pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 28.0 + mean_residual * 0.35 + 16.0 * progress;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 38.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        // Don't open a fresh bin when mean residual elsewhere is large.
        if mean_residual > item_size as f64 + 8.0 && open_bins_count > 2 {
            score += 22.0;
        }
    } else {
        // Prefer bins whose post-fit residual stays usable.
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        // Post-fit residual barely above the next item: great chaining.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        // Two-item lookahead: residual fits both this item's slack and next item.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        // Dead-space ratio penalty.
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity.max(1) as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
    }

    // Late-stream waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small vs next item.
    if open_bins_count > 2 && next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item could have used the leftover space,
    // reward if leftover is dead space for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score += 6.0; // next item could also fit here; splitting is fine but keep some penalty
        } else {
            // leftover too small for next item: dead space, but reward if very tight
            let waste = (post_residual as f64) / nx;
            score -= 10.0 * (1.0 - waste);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good open bins exist (empty-bin candidate).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64).ln().max(0.5);
        score += 30.0 + 15.0 * pressure * (1.0 - 0.3 * progress);
        // But if mean residual across open bins is small, opening a bin is reasonable.
        score -= (mean_residual / cap).max(0.0) * 20.0;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 8.0 * gap * gap;

    // Global state coupling: when many bins are open, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fullness * (open_bins_count as f64).sqrt();

    // Time horizon: early on, be exploratory (favor new bins slightly); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fullness;
    score += 8.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let p2 = pr_norm * pr_norm;
    let p3 = p2 * pr_norm;
    score += (p2 + 0.5 * p3) * cap * (0.6 + 0.8 * progress);

    // Reward tight fits: smooth function of post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space relative to smallest plausible future need (10).
    let dead = (post_residual as i64 - 10).max(0) as f64;
    score += 0.05 * dead * dead / cap;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: penalize leaving residual that barely fails to fit next item,
    // reward residuals that can still host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 * (nxt / cap);
        } else {
            let gap = nxt - post_residual as f64;
            score += 4.0 * (gap / cap) * (gap / cap) * cap;
        }
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad;
    // decays with progress (late in stream, filling bins matters more).
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.6 * progress) + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating smoothly from the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 530.0;
    } else if post_residual <= 4 {
        score -= 235.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold && !next_consumes {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.55 * waste;
        if waste > bin_residual as f64 {
            score += 28.0;
        }
        if post_residual < 30 {
            score += 26.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_item_size > 0 && next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 450.0;
        } else {
            score -= 8.0 + slack * 0.2;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual >= next_item_size * 2 {
                score -= 60.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 38.0;
            }
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64;
        score += 20.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 30.0;
        }
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 42.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 27.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 {
            score += 14.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Mean-residual deviation: prefer bins near the average fill state.
    score += (mean_residual - bin_residual as f64) * 0.09;

    // Stranded-space penalty scaled by future stream density.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.75 && !next_consumes && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Late-stream waste hurts more.
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual matches common
    // small-item sizes (mod classes) are more reusable.
    let pr = post_residual;
    let mod10 = pr % 10;
    let mod20 = pr % 20;
    let mod25 = pr % 25;

    // Reward residuals that are "harmonic" multiples of common item sizes
    if pr >= 10 {
        if mod10 == 0 {
            score -= 8.0; // divisible by 10: many item sizes fit cleanly
        }
        if mod20 == 0 {
            score -= 4.0;
        }
        if mod25 == 0 {
            score -= 3.0;
        }
    }

    // Penalize awkward residuals: small dead space that nothing (min size 1)
    // can pair with usefully is fine, but mid-range awkward slivers are bad.
    if pr > 0 && pr < 10 {
        score += 6.0; // tiny dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            // next item fits: residual mod class alignment bonus
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0;
            }
            score -= (slack as f64).ln() * 2.0;
        } else {
            // next item won't fit here: penalize slightly if this residual
            // is in a "lonely" class unlikely to match future items
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score, penalized when open bins
        // are still quite full-capable (avoid bin proliferation)
        score = 55.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count > 0 {
            score += 10.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && next_item_size <= item_size {
            score -= 20.0; // pairing potential in fresh bin
        }
    }

    // Progress-aware tightening: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Waste penalty relative to mean residual: placing into a bin whose
    // residual deviates strongly from mean disrupts harmonic balance
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold on post_residual classes
    let class = pr / 10; // 0..10 coarse class
    score += match class {
        0 => 10.0,
        1 => 0.0,
        2 => -2.0,
        3 => -4.0,
        4 => -5.0,
        5 => -5.5,
        6 => -5.0,
        7 => -4.0,
        8 => -3.0,
        9 => -2.0,
        _ => -1.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Near-perfect fit: leave only tiny slivers, which are easy to fill later.
    if post_residual > 0 && post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 7.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for next arrival).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 22.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        score -= 14.0 + (post_residual - next_item_size) as f64 * 0.2;
        // Exact lookahead fit is extremely valuable.
        if next_item_size == post_residual {
            score -= 300.0;
        }
        // Two-item lookahead: bin can host next item twice.
        if post_residual >= next_item_size * 2 {
            score -= 35.0 * (1.0 - progress);
        }
        // Post-fit slack small enough that only tiny items fit: mild penalty.
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < 8 && slack < item_size.min(15) {
            score += 12.0;
        }
        // Slack just above next item: chaining opportunity.
        if slack > 0 && slack < 4 {
            score -= 18.0;
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 14.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize so new bins open only when fits are bad,
    // scaled by mean residual (large mean residual = plenty of room elsewhere).
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 3.0 * fitting_bins_count as f64;
        // Early large items: opening a fresh bin is fine.
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // If the fresh bin can host both this and the next item, it is attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        // If mean residual is large, existing bins have room; avoid new bins.
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
    } else {
        // Prefer bins whose post-fit residual stays above the mean (still usable).
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        // Post-fit residual barely above next item: great chaining opportunity.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        // Two-item exact chain: residual fits item + next with tiny remainder.
        if next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 2 && fitting_bins_count <= 2 {
            score -= 25.0 * (1.0 - progress);
        }
        // Penalize leaving residual that can't host next item but could have.
        if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.45 * progress;

    // If mean residual is small (bins nearly full), squeeze into existing bins.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 30.0 * (1.0 - progress);
    }

    // Dead-space ratio guard: avoid placements leaving most of the bin empty
    // unless the lookahead can still use the space.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        // Stranded residual: nothing known can fill it later.
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
        }
        // Residual divisible into future items is valuable.
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
