        } else {
            score -= 10.0 / (1.0 + gap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: mild penalty proportional to how much it misses
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few, allow it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless open bins are crowded (low mean residual)
        score += 10.0 + pressure - 0.5 * mean_residual;
        if progress > 0.9 {
            score += 5.0; // late stream: prefer consolidating
        }
    } else {
        // Existing bin: mild reward for keeping bins packed near mean residual
        score -= 0.2 * mean_residual;
    }

    score
}

