        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        let stranded = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += 14.0 * stranded * (1.2 - progress);
            if post_residual < 25 {
                score += 10.0 * (25.0 - post_residual as f64) * future_density;
            }
        }
        if next_consumes && post_residual <= 2 && fitting_bins_count <= 3 { score -= 6.0; }
        if next_consumes && post_residual >= next_item_size * 2 {
            score -= 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 5 == 0 && post_residual >= 10 {
            score -= 4.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual as f64 > mean_residual * 0.5 {
            score += 6.0 * (1.0 - progress) * stranded;
        }
        if !next_consumes && post_residual >= 15 && post_residual <= 40 && (post_residual as f64) < mean_residual {
            score += 5.0 * future_density * (1.0 - stranded);
        }
        if next_consumes && post_residual == next_item_size && fitting_bins_count > 1 { score -= 12.0; }
        if !next_consumes && dead_ratio > 0.75 && open_bins_count > 3 {
            score += 7.0 * (dead_ratio - 0.75) * 10.0 * (1.0 - progress);
        }
        if next_consumes && post_residual % 8 == 0 && post_residual >= 8 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size
            && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = (norm_pr - 0.5) * (norm_pr - 0.5) * (0.5 + progress);
    score += 60.0 * coupling;

    // Reward tight fits, more so late in the stream
    score -= 30.0 * norm_item * (1.0 - norm_item) * (1.0 + progress);

    // Penalize leaving a residual that is small but too small for the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let waste = (next - pr).max(0.0) / cap;
        let smooth_waste = waste * waste;
        score += 25.0 * smooth_waste * (0.5 + progress);
        // Reward post_residual that still fits next item comfortably
        let usable = (pr - next).max(0.0) / cap;
        score -= 15.0 * usable * (1.0 - usable) * (1.0 + 0.5 * progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Prefer bins below mean residual (fill emptier bins first, softly)
    score += 10.0 * (norm_pr - mean_norm) * (0.5 + progress);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-perfect fit: tiny slivers are easy to fill later.
    if post_residual > 0 && post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space avoidance for small unusable gaps.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 45.0 + (12 - post_residual) as f64 * 7.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.2;
        if post_residual < 30 {
            score += 22.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 380.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity.max(1) as f64);
        }
        // Exact two-item lookahead.
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        // Chaining: post-fit residual barely above next item.
        if slack > 0.0 && slack < 4.0 {
            score -= 18.0;
        }
        // Slack in the awkward 8..12 range: mild penalty.
        if slack >= 8.0 && slack < 12.0 {
            score += 16.0;
        }
        // Slack that fits the current item class again: good.
        if slack >= 10.0 && slack <= 30.0 && (slack as u32) >= item_size.min(20) {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.1;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 14.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize scaled by available room elsewhere.
        score += 22.0 * fitting_bins_count as f64 + mean_residual * 0.3 + 18.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            score += 28.0;
        }
        // Early large items: opening a fresh bin is fine.
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // Fresh bin can host both this and next item: attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        // Many open bins with room: strongly discourage new bins.
        if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.2 {
            score += 12.0 * (1.0 - progress);
        }
    } else {
        // Prefer bins whose post-fit residual stays usable.
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        // Post-fit residual barely above next item: chaining opportunity.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 16.0;
        }
        // Post-fit residual can hold both item and next item nearly exactly.
        if next_item_size > 0 && post_residual >= item_size + next_item_size
            && post_residual - item_size - next_item_size <= 3 && fitting_bins_count <= 2 {
            score -= 22.0 * (1.0 - progress);
        }
        // Dead ratio penalty: large leftover fraction of the bin.
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity.max(1) as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.45 * progress;

    // Mean residual pressure: squeeze into existing bins when they are nearly full.
    if open_bins_count > 2 && next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 {
        score -= 30.0 * (1.0 - progress);
    }

    // Stranded residual: unusable for the lookahead item.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity.max(1) as f64;
        score += 12.0 * stranded * (1.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in low classes is more wasteful
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize small unusable remainders (< ~10% of capacity) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-classes: residual congruence classes mod 10; odd/tiny remainders are less reusable
    let class = post_residual % 10;
    if class == 1 || class == 2 {
        score += 25.0;
    } else if class == 5 {
        score += 10.0;
    } else if class == 0 && post_residual > 0 {
        score -= 8.0; // round residuals are reusable
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 15.0; // post_residual can't host next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 300.0 } else { 0.0 };
        score -= pressure;
        score += 40.0; // base penalty to prefer filling existing bins
        // If mean residual across bins is large, discourage new bin
        score += (mean_residual / cap) * 50.0;
    }

    // Mild packing tightness reward: prefer bins with smaller residual before placement
    score += (bin_residual as f64) * 0.05;

    // Progression: as stream advances, be slightly greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 700.0;
    } else if post_residual <= 4 {
        score -= 250.0;
    } else if next_consumes && post_residual - next_item_size <= 2 {
        score -= 90.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        score -= 140.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual >= next_item_size * 2 {
            score -= 55.0;
        }
    } else if next_item_size > 0 {
        // dead space penalty scaled by how much next item misses
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 1.8;
        if post_residual < 30 {
            score += 25.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Penalize small unusable post-residual (dead space) but not perfect fits
    if post_residual > 0 && post_residual < 10 && !next_consumes {
        score += 85.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    } else if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        if poor_fit < 25.0 && next_consumes {
            score += 520.0; // keep using open bins when they chain well
        } else {
            score += 130.0 + 15.0 * progress;
            // open a fresh bin early for large items that would strand open bins
            if progress < 0.1 && item_size > bin_capacity / 2 {
                score -= 60.0;
            }
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.12;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    if bin_residual != bin_capacity {
        score -= (35.0 + 25.0 * progress) * (1.0 - 0.5 * progress);
    }

    // Two-item lookahead: bonus when bin can host item + next item exactly
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let pair_slack = (bin_residual - item_size - next_item_size) as f64;
        score -= 22.0 * (1.0 - pair_slack / 10.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

