    // Dead space is worse if no future item can use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward bins whose residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer reusing open bins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Slight preference for bins tighter than average (consume fragmented space).
    if mean_residual > 0.0 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

