    // Mean-residual alignment: prefer bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 40.0 * progress;
        } else if post_residual > next_item_size {
            // Next item still fits: leftover after both items is what counts.
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - two_step_left / bin_capacity as f64);
            score -= 10.0 * progress;
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap + 20.0 * progress;
        }
    }

    // Tight fit reward relative to capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize residuals far below mean (fragmented bin) mildly, reward above-mean usable space.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless current bins are nearly full.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    // Very small post-residuals are excellent (near-perfect packing).
    if post_residual < 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
