pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where item nearly fills the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 28.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never hold small items
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; penalize leaving awkward slivers
        score += 6.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 0.9 * pressure;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, prefer exact packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow new bin early if current bins are very tight
        if mean_residual < 8.0 && open_bins_count > 0 {
            score -= 30.0;
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Waste fraction penalty
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

