pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled non-linearly by stream progress
    let mut score = pr * (0.8 + 0.6 * progress * progress);

    // Non-linear coupling: quadratic in normalized post residual, modulated by progress
    score += cap * (norm_pr * norm_pr) * (1.0 - progress) * 0.5;
    score -= cap * (norm_pr * norm_pr * norm_pr) * progress * 0.7;

    // Penalize large post residual early (dead space), reward tight fits late
    score += (1.0 - progress) * (norm_pr - norm_item) * cap * 0.3;

    // Lookahead coupling: reward if next item fits in post residual (smooth)
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let smooth = 1.0 / (1.0 + ((next_item_size as f64 - pr) / cap).abs() * 8.0);
        score -= if fits { 12.0 * smooth } else { -4.0 * smooth };
    }

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Mean residual coupling: prefer bins deviating smoothly from mean
    score += ((mean_residual - pr) / cap).abs() * cap * 0.2 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residual is truly unusable
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + pr * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
