pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into capacity
    // fractions are "harmonic" and easy to fill later.
    let r = post_residual;
    if r == 0 {
        score -= 500.0; // perfect fit
    } else if r <= 10 {
        score -= 120.0; // near-perfect
    } else {
        // harmonic residue classes: r % 10 == 0, r % 25 == 0, r % 50 == 0
        let harmonic = (r % 10 == 0) as i32 * 2 + (r % 25 == 0) as i32 * 2 + (r % 50 == 0) as i32;
        score -= 40.0 * harmonic as f64;
        // integer-division thresholds: which small item classes could fill it
        let fillable = (r >= 10) as i32 + (r >= 20) as i32 + (r >= 25) as i32 + (r >= 40) as i32 + (r >= 50) as i32;
        score -= 15.0 * fillable as f64;
        // dead-space penalty for awkward residues (prime-ish, non-harmonic)
        if r % 10 != 0 && r % 25 != 0 {
            score += (r as f64) * 0.35;
        }
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 60.0;
            // exact modular match: post_residual is a multiple of next_item_size
            if r % next_item_size == 0 {
                score -= 80.0;
            }
        } else {
            score += 45.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Prefer tight bins over empty ones; new-bin candidate (residual == capacity)
    // should only win when nothing fits well.
    if bin_residual == bin_capacity {
        score += 70.0 + open_bins_count as f64 * 2.0;
    }

    // Mid-stream: consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual - post_residual as f64).abs() * -0.2 * progress;
    score += progress * 10.0;

    // Penalize large waste relative to current mean residual.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are useless dead space.
    // Penalize residuals in the "unusable" band (1..=10) heavily, since items >= 10
    // can never fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // 55..15 penalty, worst at 1
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else {
        // Larger leftovers: mildly prefer tighter fits (already via base post_residual),
        // but reward leftovers that can still host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward if next item fills it (near-)exactly.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 25.0 - 2.5 * gap as f64;
            }
        } else if next_item_size > 0 {
            // Leftover cannot host next item: penalize proportionally to how close it is.
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += 0.8 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual is pure dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 40.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced late in the stream when consolidation
        // matters less, and reduced if many bins are open (cleanup phase).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * (1.0 - progress);
        // If the next item is large and current item is small, a fresh bin can be
        // reserved strategy is bad; penalize opening when item is small.
        if item_size < 40 {
            score += 10.0;
        }
        // If no open bin can fit (fitting_bins_count==0 means only new bin fits),
        // opening is forced: make score clearly lowest.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If this is the only fitting bin besides opening new, prefer existing bin
        // unless existing bins would create dead space (handled above).
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Slight tie-breaker: prefer bins whose residual is close to item (snug fit).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
