    } else if post_residual <= 4 {
        score -= 200.0;
    }

    // Dead-space avoidance for small unusable gaps, unless lookahead consumes them.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 45.0 + 0.8 * post_residual as f64;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 420.0;
        } else {
            score -= 90.0 * (1.0 - slack / bin_capacity as f64);
            if slack > 0.0 && slack <= 7.0 {
                score -= 55.0;
            }
            if slack > 0.0 && slack < 12.0 {
                score += 25.0;
            }
            if post_residual >= next_item_size * 2 {
                score -= 40.0 * (1.0 - progress);
            }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 {
                score -= 12.0;
            }
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.1;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

