    if bin_residual == bin_capacity {
        score += 22.0 + 20.0 * fitting_bins_count as f64 * 0.5 + mean_residual * 0.3 + 15.0 * progress;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
