            score -= 22.0 * (1.0 - progress);
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Stranded-space pressure: residual that likely nothing can fill.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Dead ratio penalty: leaving large unusable fraction of bin.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        // Post-fit residual divisible by item size: reusable chunk.
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero is best.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that can't fit typical future items (1..100).
        // Small residuals (< next item or < ~10) are nearly unusable.
        if (post_residual as f64) < mean_residual * 0.35 {
            score += 8.0;
