    }

    // Exact-ish fit reward scaled by item size (large items wasting little space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item doesn't fit but is large, prefer leaving bigger residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are chosen only when genuinely better.
        score += 15.0;
        // More open bins with slack -> prefer existing bins.
        score += open_bins_count as f64 * 0.5;
