    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Prefer fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.15;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
