        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        // NEW: triple-chain bonus — bin can absorb the next item repeatedly.
        if next_item_size > 0 && post_residual >= next_item_size * 3 {
