        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual { score += 22.0 * (1.0 - progress) ; }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size . max (next_item_size) { score -= 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual < item_size . min (next_item_size . max (1)) { score += 9.0 ; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0 ; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0 ; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual { score += 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 { score -= 7.0 * (1.0 - progress) ; }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 { score -= 22.0 * (1.0 - progress) ; }
    }
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0 ; }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size . max (1) == 0 { score -= 10.0 * (1.0 - progress) ; }
        if dead_ratio > 0.55 && post_residual < item_size . min (40) { score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress) ; }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 { score -= 12.0 * (1.0 - progress) * future_density ; }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size { score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress) ; }
        if (next_item_size == 0 || next_item_size > post_residual) {
            let stranded = post_residual as f64 / bin_capacity as f64 ;
            score += 12.0 * stranded * (1.2 - progress) ;
            if post_residual < 25 { score += 8.0 * (25.0 - post_residual as f64) * future_density ; }
        }
        if post_residual == item_size { score -= 15.0 * (1.0 - progress) ; }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 { score -= 10.0 * future_density ; }
    }
    score += post_residual as f64 * 0.4 * progress ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero dead space gets a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Strict dead-space avoidance: penalize gaps too small to be useful.
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Tiny unusable gap: heavy penalty proportional to wasted capacity.
            score += (10.0 - gap) * 4.0;
        } else if gap < 20.0 {
            // Marginal gap: moderate penalty.
            score += (20.0 - gap) * 1.5;
        } else if gap >= next_item_size as f64 && next_item_size > 0 {
            // Gap can host the lookahead item: reward tight two-item packing.
            let slack = gap - next_item_size as f64;
            score -= (20.0 - slack.min(20.0)) * 0.8;
        }

        // Reward tight fits (small post_residual relative to item size).
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // prefer filling existing bins rather than the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + pressure * 3.0;
    } else {
        // Filling an existing bin slightly relieves pressure.
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (fill the fullest bins first to consolidate space).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack left over
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // reward tight fits for the next item too
        score -= (30.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space that the next item cannot use
        score += 0.25 * post_residual as f64;
    }

    // Penalize leaving residual far below the mean residual of open bins
    // (i.e., heavily depleting a bin when others are roomier)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.10 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Penalize very small post residuals that become unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // make it more attractive late in the stream or when bins are scarce
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
