    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: bins that end up with small post-residual are excellent fits.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Dead-space penalty: large leftover chunks are wasted unless big items may still come.
    if post_residual > 40 && post_residual < 50 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }
    // If next item cannot fit here, mild penalty so bins that chain well are preferred.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor or stream is early.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // Early in the stream, new bins are cheap (lots of future use).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        score += 2.5 * open_bins_count as f64;
        // If mean residual across open bins is high, opening a bin is wasteful.
        score += 0.3 * mean_residual;
        // If no open bin can fit (fitting_bins_count==0 means only new-bin call), it's mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer fuller bins slightly: closeness of residual to item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild penalty for very fragmented bins as stream matures.
    if progress_like(step_index, total_items) > 0.7 && post_residual > 20 && post_residual < item_size as f64 * 2.0 {
        score += 2.0;
    }

    score
}

