        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.5 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
        if post_residual == item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: quadratic in post_residual with progress-dependent curvature
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // 0..1

    // Early in the stream, prefer tight fills (penalize large residuals more);
    // late in the stream, relax slightly but still reward tight fits.
    let curvature = 1.0 + 1.5 * (1.0 - progress);
    score += curvature * norm_pr * norm_pr * cap * 0.5;

    // Reward filling bins tightly when the next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        // smooth-ish reward: exact fit of next item is highly desirable
        let gap = ((post_residual as f64) - next_item_size as f64).abs();
        score -= fits_next * 6.0 * (1.0 - gap / cap);
        // penalize post-residuals that are small-but-not-zero (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0 * (1.0 - pr / (next_item_size as f64));
        }
    } else {
        // last item: strongly prefer zero residual
        score += 2.0 * norm_pr;
    }

    // Last-chance bin: this is the only fitting bin -> strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Slight preference for bins below mean residual (tighter bins first)
    score += 0.05 * ((mean_residual - pr) / cap);

    // New-bin candidate: empty bin gets a moderate penalty so it's only chosen
    // when no open bin fits well; penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it decomposes modulo common item sizes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Base: prefer small post_residual, but reward exact "harmonic" residuals
    // that can be filled by a plausible future item (multiples of 10..=25).
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Fractional fill level of the bin
        let fill = 1.0 - (pr as f64) / cap;
        score -= 30.0 * fill;

        // Harmonic class: pr divisible by small common sizes => reusable
        let mut harmony = 0.0f64;
        for d in [10u32, 15, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        // pr expressible as sum of two common sizes
        if pr >= 20 && pr <= 50 && pr % 5 == 0 {
            harmony += 3.0;
        }
        score -= harmony;

        // Dead space penalty for awkward residuals (prime-ish / odd small gaps)
        if pr < 10 && pr > 0 {
            score += 25.0;
        } else if pr < 20 && pr % 5 != 0 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills remainder
            let nxt_fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * nxt_fill;
            // harmonic pair: item + next == residual exactly consumed later
            if (pr - next_item_size) == 0 {
                score -= 10.0;
            }
        } else {
            // next item does NOT fit here: penalize if gap is just barely too small
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 5.0 + (open_bins_count as f64).ln() * 3.0;
    }

    // Early stream: keep bins tight; late stream: allow slight slack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress);

    // Mean residual coupling: penalize bins far below mean residual (wasteful)
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when no good existing option exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 40.0;
        // but attractive if current item is large and would leave awkward residual elsewhere
        if item_size >= 70 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // pair next item into this fresh bin
        }
    }

    score
}

