pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if no plausible future item (>=1) can use it well;
    // treat gaps below ~12 as near-dead, escalating nonlinearly.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 35.0;
        } else if slack < 12.0 {
            score -= 15.0 - slack;
        }
    }
    // Penalize if post_residual is smaller than the next item (wasted lookahead potential),
    // but only mildly, since another bin may serve it.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // encourage closing out crowded states when many bins are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Opening a bin is less bad late in the stream (fewer future items to spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 12.0;
    } else {
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // which conserves large residuals for large future items.
    if !new_bin {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

