    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 470.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 175.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 13 && !next_consumes {
        score += 36.0 + (13 - post_residual) as f64 * 6.5;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 19.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 9.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 240.0;
        } else {
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 29.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 11.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 7.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
        // Two-item lookahead: residual after next item still fits a third small item.
        if slack > 0.0 && next_item_size > 0 && slack >= next_item_size.min(20) {
            score -= 6.0 * future_density;
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 39.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.5 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 9.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual to next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match: huge reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Post-residual just below next item is dead space for the lookahead.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit overall (post_residual already does that).
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (good compaction),
    // penalize bins that are already loose relative to the fleet.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins would leave
    // large dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so we only open new bins when justified.
        score += 30.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 20.0 * progress;
        // If many bins are open and loose, avoid opening yet another.
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference for filling bins with low residual overall.
    score += 0.10 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Penalize new bin when open bins can fit; reward slightly when it's the only option.
        score += 60.0 * desperation;
        // Early in stream, prefer filling existing bins to keep bin count low.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 40.0 * desperation;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64 / 100.0) * 25.0 * desperation;
        }
        return score;
    }

    // Tightness: reward small post_residual strongly (near-perfect fit).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual < 10 {
        score -= 15.0; // fully consumed residual is fine
    } else if post_residual < next_item_size.max(1) {
        // residual can't fit the lookahead item -> dead space
        score += 8.0;
    }

    // Lookahead: reward if post_residual exactly accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins above the mean (drain large residuals).
    if post_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // Time horizon: late in the stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.3 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post-residual with stream progress:
    // early on, large residuals are tolerable; late, they become costly dead space.
    let poly = 1.0 + 3.0 * progress * progress + 2.0 * progress;
    score += poly * norm_pr * norm_pr * cap * 0.5;

    // Reward near-perfect fits more strongly as stream progresses (smooth cubic in fill ratio)
    let fill = (item_size as f64) / cap;
    score -= 20.0 * fill * fill * fill * (0.5 + progress);

    // Penalize large post-residual quadratically, scaled by mean residual context
    score += 0.05 * pr * pr / (mean_residual.max(1.0));

    // Lookahead coupling: if next item fits into post-residual, reward this bin smoothly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            let tight = 1.0 - gap / cap;
            score -= 15.0 * tight * tight * (0.3 + 0.7 * progress);
        } else {
            // smooth penalty for wasting space the next item can't use
            score += 0.02 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it (smooth in fitting count)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild penalty for opening new bins when many bins are already open (fragmentation control)
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress + (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
