    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 16.0 * progress + 3.0 * fitting_bins_count as f64;
        // Early large items: opening a fresh bin is fine.
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 38.0;
        }
        // If the fresh bin can host both this and the next item, it is attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 22.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
    } else {
        // Prefer bins whose post-fit residual stays above the mean (still usable).
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        // Post-fit residual barely above next item: great chaining opportunity.
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 16.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 20.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 8.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // If mean residual is small (bins nearly full), squeeze into existing bins.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 22.0 * (1.0 - progress);
    }

    // Stranded-space analysis: residual that nothing upcoming can use.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    // Dead-ratio diagnostics on the remaining space.
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Quadratic waste penalty, amplified as stream progresses
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize bins far below mean residual (avoid scattering small residuals)
    score += 2.0 * (mean_residual - bin_residual as f64).abs() / cap;

    // Lookahead: reward leaving space for the next item, penalize blocking it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 3.0 * (1.0 - (pr - ni) / cap) * progress;
        } else {
            score += 3.0 * progress;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize opening a new bin unless it enables a perfect fit
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    if post_residual == 0 {
        score -= 480.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    score += open_bins_count as f64 * 1.2;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    score += post_residual as f64 * 0.4 * progress;

    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class thresholds via integer division on post_residual.
    let class = post_residual / (bin_capacity / 5); // 5 harmonic classes: 0..=4
    match class {
        0 => score -= 12.0,  // near-perfect fit: tiny dead space, reward strongly
        1 => score -= 6.0,   // small remainder, still good
        2 => score += 0.0,   // neutral middle
        3 => score += 4.0,   // large dead space forming
        _ => score += 8.0,   // bin left mostly empty: penalize
    }

    // Modulo coupling: residuals divisible by common item sizes are reusable.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 5.0; // residual is a harmonic multiple of the base grain
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 10.0; // perfect two-item chain closure
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: dead space likely.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged unless
    // this bin is empty and item is large relative to mean residual.
    if bin_residual == bin_capacity {
        score = 30.0 + post; // fresh bin baseline
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large items pair well in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open new bin
        }
    }

    // Progress-aware tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post * progress * 0.2;

    // Spread-awareness: when open bins are already loose (high mean residual),
    // prefer tighter fills; when bins are tight, tolerate slack.
    score -= (mean_residual - post) * 0.1;

    // Small tie-break toward fewer open bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // anything useful are heavily penalized (non-linearly).
    if post_residual > 0 {
        // smallest useful item is 1; treat gaps below ~10 as near-dead
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0).powi(2);
        } else if post_residual < 20 {
            score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio * waste_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // this placement creates a gap that blocks the next item
            score += 12.0;
        }
    }

    // Open-bin pressure: prefer keeping the number of active bins low
    // by favoring existing bins over the new-bin candidate.
    if bin_residual < bin_capacity {
        score -= 8.0 + (open_bins_count.min(20) as f64) * 0.5;
    } else {
        // New-bin candidate: penalize more as open bins accumulate,
        // but relax slightly early in the stream when few bins exist.
        score += 15.0 + (open_bins_count as f64) * 0.8;
    }

    // Mean-residual coupling: if the fleet of open bins is already loose
    // (high mean residual), discourage adding to sprawl unless tight fit.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item fills this bin's post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish -> very desirable
            score -= 150.0 / (1.0 + gap * 0.15);
        } else {
            // next item cannot fit in leftover: penalize dead space
            score += gap * 0.6;
        }
        // perfect two-item packing: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Compare residual against mean residual of open bins:
    // prefer bins with larger residuals for big items (keep tight bins for small items)
    let res = post_residual as f64;
    if item_size > 50 {
        score -= (res - mean_residual).max(0.0) * 0.3;
    } else {
        score += (mean_residual - res).max(0.0) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New bin candidate: penalize unless current residuals are very fragmented
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < 25.0 && open_bins_count > 2;
        if fragmented {
            score -= 60.0;
        } else {
            score += 90.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: the smaller the post residual relative to capacity, the bigger the discount (cubic shaping).
    let fill_ratio = 1.0 - post / cap;
    score -= 14.0 * fill_ratio.powi(3);

    // Near-perfect fill bonus: leaving almost nothing behind is excellent.
    if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead (k=2): reward if the next item also fits in the leftover space (chaining potential).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 9.0 * (1.0 - next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual < 10 {
        // Dead space too small for likely future items: mild extra penalty.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize bins whose residual deviates upward from the mean (they are wasting space anyway).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Time horizon: later in the stream, compact aggressively into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * t * fill_ratio;

    // New-bin candidate handling: default to keeping items in open bins...
    if bin_residual == bin_capacity {
        score += 22.0 + 0.4 * open_bins_count as f64;
        // ...unless NO open bin can fit the item, in which case a new bin is required/necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early stream with few bins: opening a fresh bin is cheaper.
        if t < 0.2 && open_bins_count < 4 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear decay of residual value with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - (pr / cap).powf(2.0 + 2.0 * progress);
    score -= 20.0 * tightness * (0.5 + progress);

    // Reward near-exact fits with a smooth cubic kernel around zero residual.
    let x = pr / cap;
    score -= 15.0 * (-x * x * 18.0).exp() * (1.0 - progress * 0.5);

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 5.0 + (-gap / cap) * 10.0;
        }
    }

    // Penalize creating dead space relative to mean residual (smooth quadratic).
    let dead = (pr - mean_residual).abs() / cap;
    score += 6.0 * dead * dead;

    // Mild penalty for spreading across many bins when residual is large.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "usable"
    // classes (multiples of small integers) are more likely to be filled later.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [2u32, 4, 5, 8, 10, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 1.0;
            }
        }
        // Reward harmonic residuals (subtract), scaled by residual size so
        // large harmonious gaps get a stronger bonus.
        score -= harmony * (pr as f64 / cap) * 6.0;
    } else {
        // Perfect fit: heavily reward.
        score -= 40.0;
    }

    // Integer-division threshold: classify post_residual into dead-space tiers.
    let tier = pr / 10; // 0..=10
    let tier_penalty = match tier {
        0 => -30.0,          // near-perfect fit
        1 => -10.0,          // small gap, still flexible
        2 | 3 => 0.0,        // mid gap
        4 | 5 | 6 => 4.0,    // awkward gap
        7 | 8 | 9 => 8.0,    // likely dead space
        _ => 12.0,           // huge gap = wasted bin
    };
    score += tier_penalty;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 15.0 * fit_frac;
            // Harmonic check: does next item divide the residual evenly?
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize leaving large residuals.
            score += (pr as f64 / cap) * 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open residuals
    // are badly fragmented (high mean residual relative to capacity) or no fit exists.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: moderate score, penalized more when open bins are healthy.
        let healthy = 1.0 - (mean_residual / cap).min(1.0);
        score = 25.0 + 30.0 * healthy + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size * 2 {
            score -= 8.0; // big item coming; fresh space useful
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 - (post_residual as f64 / cap) * progress * 5.0;

    // Fraction-of-capacity coupling: reward filling bins past half capacity.
    let fill_frac = item_size as f64 / cap;
    if (bin_residual as f64) / cap >= 0.5 {
        score -= fill_frac * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact-fill lookahead reward
    if post_residual == 0 {
        score -= 480.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
            if post_residual >= next_item_size * 2 {
                score -= 30.0 * (1.0 - progress);
            }
            if post_residual >= next_item_size * 3 {
                score -= 14.0 * future_density;
            }
            if slack > 0.0 && slack < 4.0 {
                score -= 16.0;
            }
            if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
                score += 14.0;
            }
            if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
                score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
            }
        }
    }

    // Penalize stranded gaps the next item cannot use
    if post_residual > 0 && !next_consumes {
        let stranded = post_residual as f64 / cap;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 12 {
            score += 40.0 + (12 - post_residual) as f64 * 6.0;
        }
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < next_item_size && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
            if post_residual < 30 {
                score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
            }
            if next_item_size - post_residual <= 6 {
                score += 10.0 * (1.0 - progress);
            }
            if fitting_bins_count > 1 && post_residual < item_size.min(50) {
                score += 8.0 * (1.0 - progress);
            }
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 12.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Last-resort fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.35 + 16.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Dead-space penalties for unusable leftover
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.6 && !next_consumes {
            score += 10.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
        if post_residual == item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    score += post_residual as f64 * 0.4 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can no longer fit a
    // meaningful item (below the smallest plausible size, here 10) are
    // effectively wasted. Penalize them quadratically.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 3.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= tightness * 2.0;

    // Penalize creating a mid-range residual that no typical item (10..80)
    // can use well: gaps in (0, 10) or awkwardly small vs next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward using bins whose residual is far above the mean (aging bins),
    // encouraging consolidation into emptier bins.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly.
        score += 15.0 + pressure * 2.0;
        // Allow a new bin if the item would leave a huge unusable gap anyway
        // (e.g. item nearly fills a fresh bin).
        if item_size >= 90 {
            score -= 40.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Mild lookahead: prefer placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
