pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // for leaving awkward mid-range gaps that are hard to fill later.
    let pr = post_residual as f64;
    let awkward = (pr - 25.0).abs() / 25.0; // peaks away from "nice" residual sizes
    score += 0.6 * awkward * pr.sqrt();

    // Exact or near-exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly;
    // penalize bins that would strand space the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size < post_residual {
            let chain_waste = pr - nxt;
            score -= 12.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here; deprioritize mildly
        }
        // If next item is large, avoid wasting big-capacity bins on small items.
        if nxt >= 60.0 && item_size <= 30 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // More competition: prefer the bin that keeps the most usable remainder.
        score -= 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: when many bins are open with slack, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(5.0);
    score += new_bin * (18.0 + 14.0 * open_pressure * (0.4 + 0.6 * progress));

    // Late in the stream, consolidation matters more: penalize new bins harder,
    // reward filling existing ones even with imperfect fits.
    score -= (1.0 - progress) * 0.0 + progress * 8.0 * (1.0 - new_bin);

    // Mean-residual coupling: if this bin is unusually full vs. average,
    // prefer it (it keeps the fleet balanced toward closed bins).
    let fullness = (bin_capacity - bin_residual) as f64;
    let mean_fullness = bin_capacity as f64 - mean_residual;
    score -= 0.15 * (fullness - mean_fullness);

    // Item-size-dependent tightness: large items deserve tighter fits.
    if item_size >= 50 {
        score += 0.3 * pr; // extra penalty for waste after big items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
