    score += 40.0 * x * x * (1.0 - x) * (0.5 + progress);
    // penalize large dead space late in the stream
    score += 30.0 * x.powi(3) * progress;
    // reward tight fits
    score -= 25.0 * (1.0 - x) * (1.0 - x);
    // lookahead: favor bins whose residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap);
        score -= 15.0 * match_term.max(0.0) * (1.0 - progress * 0.5);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt();
    }
    // mean residual context coupling
    score += 0.1 * (mean_residual - pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in small residue classes are "dead space".
    // Class residuals into deciles of capacity (integer division).
    let post_class = post_residual / (bin_capacity / 10).max(1);
    let item_class = item_size / (bin_capacity / 10).max(1);
    let next_class = next_item_size / (bin_capacity / 10).max(1);

    // Penalize small-but-nonzero dead space quadratically.
    if post_residual > 0 {
        let dead = (bin_capacity as f64 / (post_residual as f64 + 1.0)).ln();
        score += 6.0 * dead * dead;
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Harmonic coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 18.0;
        }
        // Reward when next item's class is small enough to nest in this class.
        if next_class <= post_class {
            score -= 4.0 * (post_class - next_class) as f64;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting a good bin now.
        score += 3.0;
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins with low residual relative to mean (tighten tight bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Modulo-threshold logic: residual congruent to small classes (1..=5 mod 20) is nearly dead.
    let r = post_residual % 20;
    if r >= 1 && r <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Early stream: encourage opening fewer bins; late stream: pack tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 15.0 + 10.0 * (1.0 - progress);
        score += base;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    // Item class harmony: large items prefer large-residual bins.
    score -= 0.3 * item_class as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Baseline slightly above a good existing fit, below a bad one.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps the lookahead too
        }
    }

    // Mild late-stream tightening: waste less as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0
        * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.35 * slack;
    }
    // Next item cannot use the leftover: penalize proportional dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when the stream is early/many bins already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Slight late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large dead space, especially if no small items may fill it
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * dead * dead;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize wasting residual
            score += 5.0;
        }
    } else {
        // Last item: prefer filling bins as much as possible
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to mean (balance) when many bins open
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Time horizon: early in stream, be conservative about new bins (higher score for empty bin);
    // late in stream, pack tightly into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when progress is high (avoid opening bins late)
        score += 12.0 + 20.0 * progress;
        // but if nothing fits well and many bins open, allow a fresh bin
        if post_residual == bin_capacity && open_bins_count > 0 && item_size > 60 {
            score -= 15.0;
        }
    }

    // Reward tight fits relative to item size
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * t) + pr_norm * (1.0 - t) * (1.0 - t);
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 15.0 * (1.0 - pr / ns.max(1.0));
        } else {
            score -= 10.0 * (pr / (pr + ns));
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 12.0 * dev * dev * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "coarse class" (multiples of 10) does it fall in?
    let post_class = post_residual / 10; // 0..=10
    let item_class = item_size / 10;     // 1..=10
    let next_class = (next_item_size as u32).saturating_mul(10) / 10;

    // Penalize post_residuals that are not in useful harmonic classes.
    // Residuals that are exact multiples of 10 pair well with items of size 10..80
    // (which are also multiples of 10 in the canonical distribution).
    let rem = post_residual % 10;
    score += rem as f64 * 1.5; // off-class residual: dead space penalty

    // Reward leaving residuals that exactly match the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 40.0;
    }
    // Reward leaving residual >= next item (next item can chain here).
    else if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 10.0 + (post_residual - next_item_size as u32) as f64 * 0.5;
    }
    // Penalize residuals that cannot fit the next item but are large.
    else if next_item_size > 0 && post_residual < next_item_size as u32 && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Integer-division thresholds on post_residual:
    // residuals below 10 are almost dead; residuals in 10..=20 are marginal.
    if post_residual < 10 {
        score += 12.0; // near-perfect fit, excellent
    } else if post_residual < 20 {
        score -= 2.0;
    } else if post_residual > 60 {
        score += 5.0; // large leftover: this bin was nearly empty, prefer fuller bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we only
    // open a new bin when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if next item is huge and current item is small, opening fresh
        // preserves flexibility: reduce penalty.
        if next_item_size as u32 >= 60 && item_size <= 30 {
            score -= 20.0;
        }
    }

    // Progress coupling: late in the stream, tighten up (prefer tight fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mean residual coupling: if open bins are already slack on average,
    // penalize adding to slack; prefer bins below mean residual (tighter).
    let diff = mean_residual - post_residual as f64;
    score += diff * 0.2;

    // Harmonic class match bonus: item class + post class == 10 means
    // perfect complementary fill (e.g., item 30 into residual 70).
    if (item_class + post_class) as u32 == 10 && post_residual % 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" zone: residual too small to be broadly reusable.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero handled above; here reward
    // filling most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 8.0 + 2.5 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits well, opening may still win (handled by base score).
        // Reward new bin if the next item is large and this item is small.
        if next_item_size > 0 && next_item_size as f64 > bin_residual as f64 - item_size as f64 {
            score -= 5.0;
        }
    } else {
        // Reusing an open bin relieves pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead: penalize placements that leave a residual just barely
    // unable to fit the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Mild preference for bins with residuals below current mean (consolidate
    // small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards -> strong reward for small gap
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit after placement -> penalize leftover dead space
            score += 25.0 + gap * 0.3;
        }
    }

    // Prefer bins tighter than the mean residual (good fills), penalize loose bins
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        score += 120.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference to fill older/many bins as stream progresses
    score += 0.1 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty scaled on residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item,
    // but only when it's not a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: penalize residuals that can't fit the next item (waste),
    // reward residuals that can exactly or nearly fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual unusable for next item
            score += 4.0;
        }
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is very poor (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // == 1.0 for empty bin
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Base score for a fresh bin; attractive when existing fits are bad.
        score = 40.0 + 60.0 * (1.0 - pressure) + 10.0 * poor_fit;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If next item is huge, a fresh bin may be better preserved.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // encourage filling bins rather than spreading.
    score -= 0.15 * mean_residual;

    // Mild preference to keep number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    // Early-stream exploration: slightly favor new bins early to build a diverse pool.
    if step_index < total_items / 10 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let rn = r / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: quadratic coupling of post-residual with stream progress.
    // Later in the stream, we tolerate larger residuals less (waste matters more).
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) + 1.2 * progress * progress;
    let mut score = r * progress_coupling + 40.0 * rn * rn * progress;

    // Reward tight fits (small post-residual) with a strong non-linear bonus.
    score -= 30.0 * (1.0 - rn).powi(4);

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let wasted = (next_item_size as f64 - r).max(0.0) / cap;
        score += 25.0 * wasted * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Reward leaving room exactly usable by the next item.
        let gap = (r - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - gap).powi(3).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins whose post-residual stays near the mean
    // (keeps residual distribution compact, easier future fits).
    let dev = (r - mean_residual).abs() / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate handling: default penalty; relax late in the stream or
    // when many bins are open (diversification of residual sizes).
    if is_new_bin {
        let relax = 0.35 * progress + 0.15 * (open_bins_count as f64).min(10.0) / 10.0;
        score += 45.0 * (1.0 - relax);
    }

    // Mild penalty for opening/sustaining many bins early.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" (mod 10) are more likely to be filled later.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    let decade = (pr / 10) as f64;

    // Reward small absolute leftover strongly (super-linear).
    score -= (cap - pr as f64 / cap * 0.0) * 0.0; // keep base linear
    score -= (cap - pr as f64) * 0.05;            // reward tight fit

    // Dead-space penalty: leftover that no plausible item can use.
    if pr > 0 && pr < 10 {
        score -= 6.0; // tiny leftover = perfect fill
    } else if pr >= 10 && pr <= 30 {
        score -= 3.0; // usable by mid items
    } else if pr > 80 {
        score += 2.0; // nearly empty bin, wasteful to use now
    }

    // Modulo-class coupling: leftover divisible by 10 pairs well with
    // typical item grids; reward multiples of 10 and 20.
    if pr % 10 == 0 { score -= 1.5; }
    if pr % 20 == 0 { score -= 1.0; }
    if pr % 5 == 0 && pr % 10 != 0 { score -= 0.5; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            score -= 2.0 + (pr - next_item_size) as f64 * -0.02;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.03;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer the tightest (base post_residual does this)
        score += 0.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is huge relative to capacity and open bins are messy.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let messiness = (mean_residual / cap).clamp(0.0, 1.0);
        // penalize new bin generally, discount when item is large & no tight fit
        let penalty = 4.0 - 3.0 * frac - 2.0 * messiness * (1.0 - frac);
        score += penalty.max(0.5);
    }

    // Harmonic threshold on integer division of post_residual by item size:
    // if the leftover could hold the current item again, it's flexible space.
    if item_size > 0 && pr / item_size >= 1 {
        score -= 1.0;
    }

    // Stream progression: late in stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Slight preference to keep few open bins when many are already open.
    score += open_bins_count as f64 * 0.01 * (post_residual as f64 / cap);

    // Mean-residual anchor: bins far below mean residual are "holes";
    // favor them to balance load across bins.
    score -= (mean_residual - post_residual as f64) * 0.02;

    // Residue-class tie-breaker: pseudo-harmonic weight from pr mod 7.
    let harmonic = ((pr % 7) as f64 - 3.0) * 0.05;
    score += harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small-but-usable gap: mild penalty scaled by how marginal it is.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Larger leftover space is a resource: reward keeping it.
        score -= (post_residual as f64 - 20.0) * 0.3;
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into the leftover,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 40.0 - slack as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: leftover is likely dead space.
        score += 15.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening a new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is below the mean (tighter bins get filled).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize post_residual (tight fit), but with diminishing returns
    // for very small residuals (dead space below ~10 is nearly useless anyway).
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.5 * (pr / bin_capacity as f64));

    // Aggressive 2-step lookahead: reward when post_residual exactly (or nearly)
    // matches the next item size, creating a perfect chain fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < 5.0 {
            // near-perfect chain: strong reward
            score -= 60.0 - 8.0 * gap;
        } else if pr >= nxt {
            // next item fits here afterwards: mild reward scaled by tightness
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize wasted lookahead
            score += 8.0 * (nxt - pr).min(bin_capacity as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // pushing this bin below the mean balances residual distribution.
    score -= 0.35 * (mean_residual - pr);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // gives a good fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin: full residual
        score = bin_capacity as f64;
        if next_item_size > 0 {
            // fresh bin is attractive if next item is large (would need space anyway)
            score -= 0.15 * next_item_size as f64;
        }
        // discourage opening new bins early in the stream / when open bins exist
        score += 10.0 * (open_bins_count as f64).sqrt();
    }

    // Slight progression term: late in the stream, be more conservative
    // about leaving large residuals anywhere.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 460.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 175.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 13 && !next_consumes {
        score += 35.0 + (13 - post_residual) as f64 * 6.5;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 19.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 9.5 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 7.5 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 235.0;
        } else {
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 29.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 11.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 7.5 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 8.0 && next_item_size >= item_size {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 23.5;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 9.5 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 11.5 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 39.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 14.5 * (progress - 0.7) * 10.0 / 3.0;
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if open_bins_count > 2 && progress > 0.25 {
            score += 9.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.5 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 8.5 * future_density;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.5 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 9.5;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.5 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 8.5 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.5 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 9.5 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 8.5 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 14.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual as f64 <= 5.0;
        let lonely = fitting_bins_count <= 1;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 25.0; // base penalty for opening a new bin
        if tight_fit { nb -= 15.0; }
        if lonely { nb -= 12.0; }
        nb -= 8.0 * progress; // later in stream: slightly prefer consolidating
        if open_bins_count == 0 { nb = -100.0; }
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            nb -= 6.0; // new bin can also host next item
        }
        return score + nb;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small dead space) non-linearly
    score -= 10.0 * (-post_residual as f64 / 10.0).exp();

    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain perfect fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
