    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins with small residuals relative to global mean
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early in stream: keep flexibility by avoiding huge residual creation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 40 {
        score += 0.15 * (post_residual as f64 - 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post-residual); later, tolerate slack.
    let poly = x * x * (1.0 - progress) - x * progress;
    score += 20.0 * poly;

    // Penalize large dead space quadratically, damped by progress.
    score += 15.0 * x * x * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly favor this bin when it is the only one fitting.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
