pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space valued by how "reusable" it is.
    // Residuals that are multiples of common item sizes (or near multiples of 10)
    // are more likely to be filled later.
    let r = post_residual;
    if r > 0 {
        let mod10 = (r % 10) as f64;
        score += mod10 * 0.8; // penalize residuals not aligned to decade grid
        // Harmonic classes via integer division: coarse classes of leftover space
        let class = r / 20; // 0..5 classes: tiny, small, medium, large, huge
        let class_bonus = match class {
            0 => 25.0, // tiny leftover (0..20) is nearly dead space -> but small bins get small absolute score; reward tight fit
            1 => 10.0,
            2 => 4.0,
            3 => -2.0,
            _ => -6.0, // big leftover is flexible
        };
        score -= class_bonus;
        // Exact-fitting harmonic rewards: residual divisible by small sizes
        if r % 10 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 5.0; }
        if r % 50 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            // harmonic class of the slack after the next item
            let slack_class = (r - next_item_size) / 20;
            score -= 15.0 - slack_class as f64 * 2.5;
            if (r - next_item_size) % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; mildly penalize leaving mid-range gaps
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open new bins when existing fits are truly poor.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.15;
    } else {
        // prefer bins tighter than the mean residual (best-fit flavor)
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Prefer packing into already-open bins over spreading across many.
    score += open_bins_count as f64 * 0.05;

    // Early stream: be slightly more conservative (keep big residuals flexible);
    // late stream: squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

