        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    // Exact residual match reward.
    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Post-residual that cannot fit the lookahead item is less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer reusing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: reward when the next item fits snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: two items seal the bin exactly.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward more when the leftover after it is small.
            let double_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * double_left;
        } else {
            // Next item won't fit in this bin's remainder: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.30 * gap;
        }
    }

    // Prefer bins whose residual is already below average (tight bins close out fast).
    score += 0.40 * (mean_residual - post_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize large dead space creation relative to typical item sizes (min 1, max 100).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 10.0; // small scraps still usable
        } else if dead > 70.0 {
            score += 0.15 * (dead - 70.0); // large unusable-looking gap
        }
    } else {
        score -= 20.0; // perfectly closed bin
    }

    // Early in the stream, be more conservative about filling bins tightly;
    // later, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score = bin_capacity as f64 - pressure - 10.0 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by fill ratio.
    let fill = item_size as f64 / cap;
    score -= fill * (cap - post_residual as f64) * 0.5;

    // Penalize small dead space that nothing can use (wasted residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into the resulting residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect pairing: next item exactly fills residual
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // When many bins are open, encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: make it unattractive unless existing bins are hopeless.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if residual space in this new bin would fit the next item too, soften.
        if next_item_size > 0 && bin_capacity >= next_item_size + item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let fit = item_size as f64;

    // Base: post-residual, scaled smoothly by stream progress (late stream -> tighter packing)
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty for awkward dead space (quadratic-cubic coupling)
    let dead = pr / cap;
    score += 25.0 * dead * dead * (1.0 + dead);

    // Reward near-perfect fits with smooth bell-shaped coupling
    let tightness = 1.0 - (fit / cap);
    score -= 18.0 * (1.0 - tightness * tightness) * (1.0 - progress);

    // Lookahead: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let ratio = (nxt / (pr + 1.0)).min(1.0);
        score -= 12.0 * ratio * ratio * (1.0 - ratio);
        // Penalize leaving exactly-sized gap for next item (fragmentation risk)
        score += 8.0 * ((pr - nxt).abs() as f64 / cap);
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins: mild penalty to consolidate
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near average (smooth coupling)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 / mod 25 create
    // "usable" vs "dead" space classes. Dead space (small nonzero residuals)
    // should be penalized more than proportionally.
    let pr = post_residual;
    if pr > 0 {
        let r10 = pr % 10;
        let dead = (r10 > 0 && r10 <= 4) as f64;
        score += dead * (pr as f64).sqrt() * 2.5;
        // Harmonic ladder: residuals that are exact capacity fractions are good
        let frac = pr as f64 / bin_capacity as f64;
        let harmonic_bonus = (0.25f64 - frac).abs() + (0.5f64 - frac).abs() + (0.75f64 - frac).abs() + (1.0f64 - frac).abs();
        score += harmonic_bonus * 6.0;
    } else {
        score -= 30.0; // perfect fill
    }

    // Perfect pairing: post_residual exactly equals lookahead item size
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr >= next_item_size {
            score -= 4.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            score += (next_item_size - pr) as f64 * 0.35; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer reuse when the fit is tight,
    // allow fresh bin only when fit is very poor and many bins are open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let reuse_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 12.0 + tightness * 20.0 - reuse_pressure * 0.4
            - (open_bins_count as f64 / (step_index as f64 / total_items.max(1) as f64).max(1.0)) * 0.3;
        // Fresh bin is attractive mid-stream when mean residual is large
        if mean_residual > 45.0 { score -= 10.0; }
    }

    // Tight fits rewarded
    score -= (bin_residual - item_size) as f64 * 0.0;

    // Progress-based mild conservatism: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to hold any plausible item
    // (min item size 1, but statistically small gaps < ~12 are near-unusable).
    let dead_zone = 12.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.5; // heavy penalty for tiny gaps
    } else {
        // mild reward for medium usable residuals
        score -= 0.15 * (post_residual.min(bin_capacity / 2) as f64);
    }

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Exact fill potential for the lookahead item: leaving room for next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 5 {
            score -= 15.0; // enables a chained near-perfect fit
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // residual blocks the next item's reuse of this bin
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, favor filling existing ones
    // (especially the new-bin candidate, which would increase open_bins_count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open bins pressure
        score += 10.0 + 8.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Slight preference for bins tighter than the mean residual (well-packed bins)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus when the next item exactly fills the residual left behind.
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * (bin_capacity as f64 / (gap + 1.0));
        // Penalize leaving residual slightly larger than next item (dead space for one step).
        if post_residual > next_item_size && post_residual - next_item_size < item_size {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 5.0;
    }

    // Prefer bins whose residual was already tight relative to the fleet mean.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        score += 40.0;
        if good_lookahead {
            score += 10.0;
        }
        // As stream progresses, be more reluctant to open new bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 * progress;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // Penalize large unusable leftovers (below typical next item granularity).
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize leaving small dead space that only tiny items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fill;
        } else {
            // Next item won't fit here: penalize proportionally to wasted capacity.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty to prefer best-fit among alternatives via fill ratio.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global residual alignment: prefer bins whose residual is below the mean (more packed),
    // which tends to consolidate fullness.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: opening a new bin is only attractive when no open bin fits
    // well. A fresh bin has residual == capacity; make it costly early/late but cheaper
    // when open bins are scarce or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 55.0; // base cost of a new bin
        score -= 35.0 * item_frac; // large items justify fresh bins
        score -= 10.0 * progress; // slightly cheaper to open bins later in the stream
        if open_bins_count == 0 {
            score -= 60.0; // must open
        }
    }

    // Mild time-dependent consolidation pressure: as the stream progresses, favor
    // reducing the number of open bins by filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement (minimize leftover)
    let mut score = pr;

    // Non-linear coupling: tight fits are rewarded quadratically
    // (small post_residual relative to item => strong bonus)
    let tightness = (it / cap) * (1.0 - pr / cap);
    score -= 6.0 * tightness * tightness * cap * 0.1;

    // Lookahead: reward if next item fits in the post residual (smooth falloff)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let slack = 1.0 - (fits_next / cap);
        score -= 3.0 * slack * slack * (nx / cap);
        // Penalize post_residual that almost-but-not-quite fits next item
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 4.0 * gap * gap * cap * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize smoothly, more when open bins have usable mean residual
    if bin_residual == bin_capacity {
        let mean_usable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 6.0 * mean_usable * mean_usable;
        // Later in stream, opening new bins is slightly less attractive
        score += 2.0 * progress * (1.0 - it / cap);
    } else {
        // Prefer bins whose residual is close to mean (balanced depletion)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 0.5 * dev * dev;
    }

    // Mild stream-progress weighting on waste: dead space matters more early
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // class 1: leftover fits a small item (<= 20) -> still somewhat useful
        if pr <= 20 {
            score -= 6.0;
        }
        // class 2: leftover in the "dead zone" (21..=39): hard to fill -> penalize
        else if pr <= 39 {
            score += 8.0;
        }
        // class 3: leftover 40..=59: half-bin class, very reusable
        else if pr <= 59 {
            score -= 10.0;
        }
        // class 4: leftover 60..=79: large reusable class
        else if pr <= 79 {
            score -= 4.0;
        }
        // class 5: 80..=99: near-empty bin, basically like new bin
        else {
            score += 2.0;
        }

        // modulo-arithmetic bonus: leftover divisible by common size classes 10/20/25
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
    } else {
        // perfect fit: zero waste
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: partial reward scaled by tightness
        let tight = (next_item_size as f64) / (pr as f64);
        score -= 6.0 * tight;
    } else if next_item_size > 0 {
        // next item would not fit in the leftover -> mild penalty proportional to waste
        score += 2.0 * ((next_item_size - pr) as f64 / 100.0);
    }

    // Prefer filling nearly-full bins: tightness reward
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 8.0 * tightness;

    // Mean residual coupling: if this bin is below mean residual (fuller than avg), favor it
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early stream: be more conservative about fragmenting bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a baseline penalty so that any
    // reasonable existing placement beats opening a new bin, unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // but if the item is huge relative to capacity, opening fresh is fine
        if item_size >= 60 {
            score -= 10.0;
        }
        // if no existing bin fits, new bin is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // small tie-break noise-free deterministic term using open_bins_count
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
        // Small gaps (10..20) are only usable by tiny items; mild penalty.
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else if post_residual > 0 {
            score += 8.0; // next item won't fit here; this bin likely becomes dead space
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into them.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Prefer bins with residuals close to the mean (balanced packing).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score += 35.0 + bad_fit - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0).powi(3);
    } else {
        // Last item: minimize final waste aggressively
        score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Tight fit bonus (small post_residual)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(2);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() > 20.0
        } else {
            false
        };
        if poor_fit && fitting_bins_count > 0 {
            score -= 25.0; // prefer fresh bin over wasteful placement
        } else {
            score += 80.0; // discourage opening new bins when fits exist
        }
    }

    // Late in stream: be more conservative, keep residuals usable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // creates unusable sliver for the next item
        }
    }

    // Time horizon: early in the stream, be more selective (favor new bins
    // for large items to preserve flexibility); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (1.0 - progress) * 15.0;
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
        // Opening a new bin is attractive when existing residuals are scattered/high
        score += 0.15 * mean_residual;
        if open_bins_count > 0 && item_size >= 50 && progress < 0.5 {
            score -= 10.0;
        }
    } else {
        // Prefer filling bins that are already relatively empty among open bins
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Penalize proliferation of open bins when consolidation is possible
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    // Mild reward for keeping residuals aligned with common item sizes
    let mod_penalty = (post_residual % 10) as f64;
    score += 0.3 * mod_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize remaining residual, with non-linear polynomial coupling to progress.
    // Early in the stream, larger residuals are fine (bins can still be filled);
    // late in the stream, residual is more likely to become dead space.
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial term: penalize residuals that are awkwardly small but nonzero
    // (dead space), rewarding perfect fits via a quadratic valley around 0.
    score += 0.4 * norm_pr * norm_pr * (1.0 - progress);

    // Lookahead coupling: reward residual that can still host the next item
    // (smooth interaction rather than hard threshold).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { -(nxt - pr) / cap };
        score -= 0.8 * fit * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + (item_size as f64 / cap);
    }

    // Slight preference to consolidate: bins with below-mean residual get priority.
    score -= 0.3 * (mean_residual - pr / cap);

    // New-bin candidate handling: make empty bin mildly unattractive unless
    // residuals of open bins are nearly exhausted.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form "usable" slots
    // (residues divisible into common small-item sizes) are less penalized.
    let pr = post_residual;
    let residue = pr % 10;
    let harmonic_bonus = match residue {
        0 => 12.0,                     // perfectly divisible slot
        5 => 6.0,                      // half-class
        2 | 4 | 6 | 8 => 2.0,          // even class
        1 | 3 | 7 | 9 => -4.0,         // odd/dead class
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: large post_residual is wasteful if item
    // was small; tiny post_residual is excellent packing.
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr <= 5 {
        score -= 15.0;
    } else if pr > bin_capacity / 2 {
        score += (pr as f64 - cap * 0.5) * 0.5; // leaving >half empty is bad
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving a slot that
            // blocks a better split later
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when it would be a fresh, well-
    // structured container late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so new bins are used only when existing fits are poor
        score += 18.0;
        // late in the stream, a fresh bin keeps future flexibility
        score -= progress * 8.0;
        if open_bins_count > 8 {
            score += 4.0; // too many open bins already
        }
        // if the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / cap) * 6.0;
    }

    // Mild preference for bins below mean residual (balance + tightness)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space: penalize proportionally to how close it is to being wasted.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 12.0 + waste * 0.8;
        } else {
            // Post-residual can host the next item: strong reward.
            score -= 15.0;
            // Extra reward for a tight-but-usable fit (next item nearly fills gap).
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / 100.0;
            score -= snug * 8.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Penalize very small leftover gaps that no item (min size 1..10 range) may use well.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    if bin_residual != bin_capacity {
        score -= 3.0 / (1.0 + pressure * 0.2);
    } else {
        // New-bin candidate: acceptable only if existing bins fit poorly.
        let poor_fits = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 18.0 * poor_fits + (item_size as f64) * 0.05;
        // Mildly cheaper to open a new bin early in the stream.
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer bins whose residual is below mean (consolidate fuller bins).
    let r = post_residual as f64;
    if r > mean_residual {
        score += (r - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - r) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 460.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 170.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 13 && !next_consumes {
        score += 35.0 + (13 - post_residual) as f64 * 6.5;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 235.0;
        } else {
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 29.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 39.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.5 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 25.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

