pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 450.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 170.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 14 && !next_consumes {
        score += 35.0 + (14 - post_residual) as f64 * 7.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 19.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 235.0;
        } else {
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 29.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 10.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 39.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 12.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 25.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.5 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.5 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: a fresh bin is only attractive when the current
    // fit is poor or the item would leave large unusable residue.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && next_item_size > post_residual as u32;
        let no_alternative = fitting_bins_count == 0;
        if poor_fit || no_alternative {
            score -= 60.0;
        } else {
            score += 40.0 + 0.5 * post_residual as f64;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 {
        score -= 10.0;
    }
    if open_bins_count > 5 && bin_residual < bin_capacity {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild time decay: early on, be pickier about tight fits (more items to come).
    score -= (1.0 - progress) * 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    // on large leftover space (dead space grows super-linearly).
    let mut score = post + 0.9 * (post * post) / cap;

    // Reward near-perfect fits smoothly.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: reward if next item fits into post_residual, penalize otherwise.
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= post { 1.0 } else { 0.0 };
        score -= 8.0 * fits * (next_item_size as f64 / cap);
        score += 3.0 * (1.0 - fits) * (post / cap) * (1.0 - progress);
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open; relax slightly if fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post / cap; // = 1 - item_size/cap
        score += 25.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score -= 18.0 * poor_fit * poor_fit;
    }

    // Mean-residual coupling: bins deviating from mean residual are less attractive
    // (smooth quadratic interaction with progress).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap * (0.5 + progress);

    // Mild stream-progress modulation: late in the stream, consolidation matters more.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    // Class 1: leftover fits next item exactly or nearly -> good.
    // Class 2: leftover in dead zone (small, unusable) -> penalty.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // integer-division harmonic classes on post_residual
        let pr = post_residual;
        let class = pr / 10; // decade classes 0..=9
        match class {
            0 => score += 60.0,          // 1..9: dead space, nearly unusable
            1 => score += 30.0,          // 10..19: only fits tiny items
            2 => score += 10.0,          // 20..29
            3 => score += 0.0,
            4 => score -= 5.0,
            5 => score -= 10.0,
            6 => score -= 12.0,
            7 => score -= 15.0,
            8 => score -= 18.0,
            _ => score -= 22.0,          // 90..99: big residual, flexible bin
        }

        // Exact harmonic coupling: does the NEXT item fit perfectly into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 250.0; // perfect lookahead fit: strongly prefer this bin
            } else if next_item_size <= pr {
                // leftover fraction usable by next item
                let usable = next_item_size as f64 / pr as f64;
                score -= 40.0 * usable;
                // near-miss harmonic: next item within a small delta of filling the bin
                let delta = pr - next_item_size;
                if delta <= 5 {
                    score -= 30.0 * (1.0 - delta as f64 / 6.0);
                }
            } else {
                // next item does NOT fit here: leftover risks becoming dead space
                if pr < 20 {
                    score += 25.0;
                }
                // modulo-class check: pr % next_item_size small => future stacking potential
                let m = pr % next_item_size.max(1);
                if m <= 3 {
                    score -= 15.0;
                }
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral baseline with slight preference when open bins
    // are fragmented (low mean residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0
            + 0.05 * open_bins_count as f64
            - 10.0 * (mean_residual / bin_capacity as f64)
            - 20.0 * progress;
        // Don't open a new bin for a tiny item unless nothing fits well.
        if item_size <= 30 && fitting_bins_count > 0 {
            score += 80.0;
        }
        // Large items fragment bins less; slightly favor new bin for big items
        // when existing residuals are poor.
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Mild global pressure: keep total open bins low.
    score += 0.02 * open_bins_count as f64;

    score
}

