    }

    // Dead-space penalty: residuals too small for the smallest item (1..=2)
    // are unusable; treat them as wasted space and penalize extra.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0 * (min_item - post_residual) as f64;
    }

    // Penalize mid-range dead space that nothing can fill efficiently:
    // residuals in (0, 30) are hard to use; scale penalty by gap smallness.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap * 0.5;
        if next_item_size == post_residual {
            score -= 200.0;
        }
