    // If next item does NOT fit in this bin after placement, mild penalty
    // (this bin becomes dead for the lookahead).
    if next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones
    // when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
