        score -= (1.0 - gap / bin_capacity as f64) * 15.0;
        if post_residual == next_item_size {
            score -= 40.0; // chain fit: next item exactly fills remainder
        }
        // Penalize if next item cannot fit in post_residual (dead end likely).
        if post_residual < next_item_size {
            score += 8.0;
