    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 9.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 12.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    // Residual exactly equals next item's class: good chain.
    if post_residual > 0 && post_residual == item_size {
        score -= 14.0 * (1.0 - progress);
    }

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 {
        score -= 22.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual reward (tight fit), non-linear
    let pr = post_residual as f64;
    score -= 40.0 * (-pr / 15.0).exp();

    // Penalize dead space that no plausible future item can use
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_item = 1.0f64;
    if (pr as u32) < item_size.min(20) && pr > 0.0 {
        score += 25.0 + 20.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain packing)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 35.0 + 0.4 * nx;
        }
        // Penalize leaving residual that is awkwardly just below next item
        else if post_residual > 0 && next_item_size <= bin_residual {
            score += 10.0 * (1.0 - (nx - pr) / 30.0).max(0.0);
        }
    }

    // Prefer bins with below-mean residual (fill fuller bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: encourage opening new bins when fit is mediocre (keep flexibility)
    let early = (1.0 - progress).max(0.0);
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early, penalized late
        score -= 30.0 * early;
        score += 40.0 * progress;
        // If item is large, new bin is fine
        if item_size >= 60 { score -= 15.0; }
    }

    // Many open bins: discourage proliferation
    score += 0.5 * open_bins_count as f64 * (if bin_residual == bin_capacity { 1.0 } else { 0.0 });

    // Slight preference for bins whose residual is close to item size (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    if post_residual == 0 {
        score -= 480.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    score += open_bins_count as f64 * 1.2;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    score += post_residual as f64 * 0.4 * progress;

    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic in normalized post-residual (tight fits favored).
    let mut score = x * x * cap;

    // Cubic coupling with stream progress: early on, tolerate slack less;
    // later, penalize waste more strongly to keep bins closed out.
    score += 0.35 * x.powi(3) * cap * (0.5 + progress);

    // Reward near-perfect fits (post_residual close to 0) with a smooth bonus.
    score -= (1.0 - x).powi(4) * (8.0 + 6.0 * progress);

    // Dead-space penalty: residuals too small for the smallest plausible item
    // are wasted; penalize smoothly via a bell around small-but-nonzero x.
    let dead = (x * (1.0 - x) * 4.0).powi(2); // peaks at x=0.5, zero at ends
    score += dead * (1.0 - progress) * 3.0;

    // Lookahead coupling: if next item can use the post residual, reward it.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (x - nx).abs();
        score -= (1.0 - (fit * cap / 40.0).min(1.0)) * (4.0 + 4.0 * progress);
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make empty bin slightly unattractive unless it beats
    // a genuinely bad fit (large post residual on an open bin).
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    // Nudge toward bins whose residual is close to the mean (balance load).
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
