pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Tight-fit rewards (waste minimization) ---
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect fill
    }

    // --- Harmonic class of post_residual (mod 10 residue classes) ---
    let m = (post_residual % 10) as i32;
    score += match m {
        0 => -3.0,       // round residual: reusable by many sizes
        1..=3 => 2.0,    // awkward sliver class
        4..=6 => 0.0,    // neutral class
        7..=9 => 3.0,    // dead-space prone class
        _ => 0.0,
    };

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // next item exactly fills this bin
        } else if next_item_size > post_residual {
            score += 4.0; // next item won't fit here anyway
        } else {
            score += (post_residual - next_item_size) as f64 * 0.05;
        }
    }

    // --- Last-chance bonus: only fitting bin avoids opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // default: prefer existing bins
        score += 20.0 + 0.3 * open_bins_count as f64;
        // no open bin can fit: new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // harmonically reserve new bin when lookahead is large and residual is small
        if next_item_size > 0 && next_item_size >= item_size && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    // --- Penalize unusable micro-slush (< 10, below min item size) ---
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    } else if post_residual > 10 && post_residual < 20 {
        // Medium-small gaps are moderately wasteful.
        score += 10.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer compacting.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate handling: opening a bin is penalized unless the current
    // fit would leave dead space or the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0 + 3.0 * open_bins_count as f64;
        let dead_space_here = post_residual > 0 && post_residual <= 10;
        let lookahead_pair = next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual - next_item_size) <= 10;
        if dead_space_here || (fitting_bins_count > 1 && !lookahead_pair) {
            score += base_penalty;
        } else {
            // Fresh bin is attractive when it enables a tight follow-up pair.
            score -= if lookahead_pair { 35.0 } else { 0.0 };
            score += base_penalty * 0.5;
        }
    }

    // Lookahead: if the residual left behind can exactly host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (denser bins first).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 8.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    } else {
        score += 8.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    // Early in the stream, tolerate more exploration (mild new-bin leniency).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact-fill lookahead reward
    if post_residual == 0 {
        score -= 480.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
            if post_residual >= next_item_size * 2 {
                score -= 30.0 * (1.0 - progress);
            }
            if slack > 0.0 && slack < 4.0 {
                score -= 16.0;
            }
            if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
                score += 14.0;
            }
            if post_residual >= next_item_size * 3 {
                score -= 14.0 * future_density;
            }
        }
    }

    // Penalize stranded gaps the next item cannot use
    if post_residual > 0 && !next_consumes {
        let stranded = post_residual as f64 / cap;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 12 {
            score += 30.0 + (12 - post_residual) as f64 * 5.0;
        }
        if post_residual < next_item_size && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
            if post_residual < 30 {
                score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
            }
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 12.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Last-resort fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.3 + 16.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
    }

    // Dead-space penalties for unusable leftover
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.6 && !next_consumes {
            score += 10.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if post_residual == item_size {
            score -= 15.0 * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
    }

    score += post_residual as f64 * 0.4 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the NEXT item fits into post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item can also go here: strong reward, scaled by tightness.
            let tight = 1.0 - (post_residual as f64 - next_f) / bin_capacity as f64;
            score -= 25.0 + 20.0 * tight;
        } else {
            // Next item won't fit: penalize leftover dead space relative to next item.
            let gap = (post_residual as f64 - next_f).max(0.0);
            score += 5.0 + gap * 0.3;
        }
        // Exact match is ideal.
        if next_item_size == post_residual {
            score -= 40.0;
        }
    } else {
        // Last item: just prefer minimal residual (already implicit).
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist and item is small.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - fit_ratio);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 8.0; // sequential large items benefit from fresh bins anyway
        }
    }

    // Early in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, but discount late in the stream
    // (wasted space matters less when few items remain).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_weight = 1.0 + (1.0 - progress) * 0.05;
    score += (post_residual as f64).powi(2) * 0.01 * dead_weight;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (bin_capacity as f64 / item_size as f64) * (1.0 - post_residual as f64 / bin_residual.max(1) as f64) * 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
