    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item uses leftover space
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving medium-sized gaps
            score += 8.0;
        }
    }

    // Compare against global mean residual: prefer bins that leave residuals
    // close to the mean (balanced fragmentation) early on.
    if open_bins_count > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * (1.0 - progress) * 0.3;
    }

    // Many open bins: discourage spreading items; prefer filling existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate (empty bin): make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + post_residual as f64;
        // Late in the stream, opening a new bin is fine since the stream ends soon.
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
