    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space non-linearly, softened as stream progresses.
    score += 12.0 * norm_pr * norm_pr * (1.0 - 0.5 * progress);

    // Reward tight fits: small post_residual gets a polynomial bonus.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward leaving space the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mildly penalize opening bins early, more so mid-stream.
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (1.0 - progress);
    }

    // Mild preference to spread load when many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: prefer bins near the mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

