        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 9.5;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.5 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 8.5 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.5 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 9.5 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 8.5 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward near-exact fills strongly (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 35.0 * (1.0 - tightness).powf(6.0);

    // Penalize small-but-unusable residuals that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder; mild penalty scaled by waste.
            score += 3.0 * tightness;
        }
    } else {
        // Last item: squeeze it anywhere possible.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into low-residual bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln1p();
    score += crowding * 0.8 * tightness;

    // Compare against mean residual: favor bins already below mean (concentrating waste).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Late in the stream, be greedier about tight fits; early, keep options open.
    score -= 8.0 * progress * (1.0 - tightness);

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // But if nothing else fits well (large waste everywhere), allow a fresh bin.
        if mean_residual < 5.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: minimize leftover, weighted by stream progress (later items value tight fits more)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // small residuals early are fine, but tiny dead space late is valuable -> reward quadratically
    let pr_norm = pr / cap;
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize large unusable residuals: dead space below smallest plausible item
    if pr_norm > 0.0 && pr_norm < 0.05 {
        score += 30.0 * (0.05 - pr_norm) * 20.0;
    }

    // Reward good fill ratio with smooth saturating polynomial
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio);

    // Lookahead coupling: if next item fits the post residual, reward strongly (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (pr - nx).abs();
        score -= 8.0 * (1.0 - compat / cap) * (1.0 - compat / cap);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference to fill bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Prefer bins below mean residual (keeps residual distribution balanced)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual in {0, small} strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic dead-space classes: residuals that are hard to fill later
    // (odd / non-divisible-by-10 chunks) get penalized.
    let class = post_residual % 10;
    if class != 0 {
        score += class as f64 * 1.5; // awkward leftover slivers
    }

    // Integer-division thresholds on post_residual: large usable chunks
    // are "harmonic" (can host a full class of items).
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 30 {
        score -= 3.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 5.0; // nearly dead bin
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // big bonus; if next item is close, mild bonus; if next item can never
    // use this residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when all
    // existing bins would leave bad fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a bin; waived if existing fits are poor.
        let avg_fit_quality = mean_residual - pr;
        score += 18.0;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 25.0; // open bins are nearly full anyway
        }
        let _ = avg_fit_quality;
        // Early in stream, opening bins is cheap (long horizon to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score -= (open_bins_count as f64).sqrt() * (bin_residual as f64 - pr) / cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it rather than opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -0.2;
    }

    // Lookahead: if next item fits the post residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can pair here: strong reward scaled by how snugly it fits.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * (bin_capacity as f64 - pair_waste);
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            let dead = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 0.3 * dead;
        }
    }

    // Reward matching against mean residual: bins far below mean residual are
    // "tight" bins worth filling; bins above mean have slack elsewhere.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when good fitting options exist.
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        // New-bin candidate: score is residual (100). Add penalty unless item is large
        // relative to mean residual (poor fits elsewhere make new bins attractive).
        if item_size as f64 > mean_residual * 0.8 {
            score -= 10.0;
        } else {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 6.0; // perfect two-item chain
            }
        } else {
            score += 2.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Global state coupling: prefer bins with residual below mean (tighter bins).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 3.0 * dev;

    // Time horizon: early in stream, be conservative (favor compacting open bins);
    // late in stream, accept looser fits to close out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fits preferred (non-linear in normalized post-residual).
    let x = pr / cap;
    let mut score = 100.0 * x * x + 20.0 * x;

    // Smooth coupling of wasted space with stream progress:
    // early on, dead space matters less (bins can still be filled later);
    // late in the stream, compactness is critical.
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward residual that still accommodates the next item,
    // penalize residuals that strand just under the next item's size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 15.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 12.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize opening a bin unless the current
    // fit is poor; the penalty decays as the stream progresses.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Slight preference to balance residuals across open bins.
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact-fill lookahead reward
    if post_residual == 0 {
        score -= 480.0;
    }
    // Tiny residual bonus (borrowed from best): near-perfect fills
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
            if post_residual >= next_item_size * 2 {
                score -= 30.0 * (1.0 - progress);
            }
            if slack > 0.0 && slack < 4.0 {
                score -= 16.0;
            }
            // Chain-fit: slack small relative to current item keeps bin tight
            if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
                score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
            }
            if post_residual >= next_item_size * 3 {
                score -= 14.0 * future_density;
            }
        }
    }

    // Penalize stranded gaps the next item cannot use
    if post_residual > 0 && !next_consumes {
        let stranded = post_residual as f64 / cap;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 12 {
            score += 30.0 + (12 - post_residual) as f64 * 5.0;
        }
        if post_residual < next_item_size && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
            if post_residual < 30 {
                score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
            }
        }
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 12.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Last-resort fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.3 + 16.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        // Late-stream: prefer reusing open bins more strongly
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
