        // Small post-residual penalty: avoid creating slivers
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        // Pair-friendly leftover: post_residual + next fits into a small zone
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Dead-space penalties for unusable leftover
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / cap;
        if dead_ratio > 0.6 && !next_consumes {
            score += 10.0 * (dead_ratio - 0.6) * (1.0 - progress);
