}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead space"
    // (too small for typical small items) are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver
    }

    // Classify post_residual by harmonic bands of capacity fractions.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f;
    if frac <= 0.05 {
        score -= 40.0; // near-perfect fill
    } else if frac <= 0.15 {
        score -= 15.0;
    } else if frac <= 0.35 {
        score += 5.0;
    } else {
        score -= 10.0; // large residual leaves room for future items
    }

    // Modulo-arithmetic coupling: does post_residual pair with next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: harmonic match bonus
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 55.0;
            } else if gap < dead_threshold {
                score -= 10.0;
            } else {
                score -= (gap as f64).sqrt() * 2.0;
            }
            // residue-class match: (post_residual % next_item_size) small is good
            let r = post_residual % next_item_size;
            if r < dead_threshold {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's residual; penalize mildly
            score += 12.0;
            // unless residual is large enough for average future items
            if pr > mean_residual {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage closing bins (filling them) rather than spreading.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Early in the stream, prefer compact placements; late, prefer using big residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (pr / cap_f);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let crowded = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += 45.0 - crowded;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps pair large items
        }
    }

    // Integer-division threshold: residual that could hold a "half item" pair.
    let half = bin_capacity / 2;
    if post_residual >= half && post_residual < half + 10 {
        score -= 12.0; // prime slot for medium items
    }

    score
}

