    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to known next item
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
