    // Lookahead: bonus if the residual left behind can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 5.0;
        }
        // Perfect two-item pairing: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading when many bins are open and residuals are large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
        // Prefer filling bins with below-average residual early; later, any fill is fine.
        score += (post_residual as f64 - mean_residual) * (0.15 - 0.1 * progress);
    }

    // New-bin candidate: base cost, discounted early in the stream or when
    // open bins are crowded (few fitting bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let mut new_bin_cost = 40.0 + 6.0 * open_bins_count as f64;
        // If existing fit is bad (large post_residual) and next item won't fit either,
        // opening a new bin becomes attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            new_bin_cost -= 18.0;
        }
        if item_size >= 60 { new_bin_cost -= 10.0; } // big items like fresh bins
        new_bin_cost -= 15.0 * (1.0 - progress);     // cheaper to open bins early
        new_bin_cost += 20.0 * crowding;             // crowded state discourages hoarding
        score = score.max(0.0) + new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) * (1.0 - progress) * 24.0
             - prn * progress * progress * 10.0
             + prn * prn * prn * progress * 18.0;
    score += poly * cap;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + progress);
        } else {
            score -= (pr - ni).min(ni) * 0.3 * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.15 * prn;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let progress = if total_items > 0 { step_index as f64 / total_items . max (1) as f64 } else { 0.0 } ;
    let future_density = (total_items . saturating_sub (step_index)) as f64 / total_items . max (1) as f64 ;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual ;
    if post_residual == 0 { score -= 545.0 ; }
    else if post_residual <= 4 { score -= 245.0 ; }
    if post_residual > 0 && post_residual < 10 && ! next_consumes { score += 55.0 + 0.75 * post_residual as f64 ; }
    if post_residual > 0 && post_residual < item_size . min (80) { score += 42.0 + 0.5 * post_residual as f64 ; }
    let slots = post_residual / 10 ;
    score -= 5.0 * slots as f64 ;
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 460.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64) ;
            if slack > 0.0 && slack <= 7.0 { score -= 74.0 ; }
            if slack > 0.0 && slack < 12.0 { score += 38.0 ; }
            if post_residual >= next_item_size * 2 { score -= 62.0 * (0.5 + 0.5 * future_density) ; }
            if slack as u32 + item_size <= bin_capacity && open_bins_count > 2 { score -= 14.0 ; }
        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 0.55 * waste ;
            if waste > bin_residual as f64 { score += 28.0 ; }
        }
    }
    if post_residual > 0 && post_residual < 20 {
        let dead_sliver = 20.0 - post_residual as f64 ;
        let future_help = if next_consumes { 1.0 } else { 0.0 } ;
        score += dead_sliver * (1.55 - future_help) ;
    }
    score += (mean_residual - bin_residual as f64) * 0.09 ;
    if fitting_bins_count <= 2 && bin_residual < bin_capacity { score -= 18.0 * (1.0 - 0.3 * progress) ; }
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0 ; }
    let fit_ratio = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= fit_ratio * 8.0 ;
    if fit_ratio > 0.9 && bin_residual < bin_capacity { score -= 10.0 * (fit_ratio - 0.9) * 6.0 ; }
    if bin_residual == bin_capacity {
        score += 20.0 * fitting_bins_count as f64 ;
        score += 20.0 * progress ;
        if mean_residual > item_size as f64 + 10.0 { score += 30.0 ; }
        if progress < 0.1 && item_size > bin_capacity / 2 { score -= 42.0 ; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size { score -= 27.0 ; }
        if post_residual == 0 && mean_residual >= item_size as f64 { score += 17.0 ; }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 { score -= 11.0 * (1.0 - progress) ; }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 { score -= 37.0 * (1.0 - progress) ; }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size { score -= 19.0 * (1.0 - progress) ; }
        if post_residual >= item_size . max (next_item_size) && post_residual < item_size . max (next_item_size) + 6 { score -= 13.0 * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 4 { score -= 20.0 ; }
        if progress > 0.7 { score += 12.0 * (progress - 0.7) * 10.0 / 3.0 ; }
    } else {
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual { score += 22.0 * (1.0 - progress) ; }
        if post_residual > 0 && fitting_bins_count == 1 && post_residual >= item_size . max (next_item_size) { score -= 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual < item_size . min (next_item_size . max (1)) { score += 9.0 ; }
        if post_residual > 0 && post_residual == bin_residual - item_size && bin_residual >= item_size + 12 { score += 14.0 ; }
        if post_residual > 0 && post_residual % 10 == 0 { score -= 6.0 ; }
        if post_residual > 0 && post_residual < item_size && post_residual < 30 && next_item_size > post_residual { score += 12.0 * (1.0 - progress) ; }
        if post_residual > 0 && post_residual < 6 { score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress) ; }
    }
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64 ;
        if dead_ratio > 0.6 { score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress) ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 { score -= 9.0 ; }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size . max (1) == 0 { score -= 10.0 * (1.0 - progress) ; }
        if dead_ratio > 0.55 && post_residual < item_size . min (40) { score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress) ; }
        if dead_ratio > 0.45 && next_consumes && (post_residual - next_item_size) < 8 { score -= 12.0 * (1.0 - progress) * future_density ; }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size { score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress) ; }
        if next_item_size == 0 || next_item_size > post_residual {
            let stranded = post_residual as f64 / bin_capacity as f64 ;
            score += 12.0 * stranded * (1.2 - progress) ;
            if post_residual < 25 { score += 8.0 * (25.0 - post_residual as f64) * future_density ; }
        }
    }
    if post_residual > 0 && post_residual == item_size { score -= 15.0 * (1.0 - progress) ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity remaining

    // Dead-space penalty: residuals that are unusable "harmonic slivers"
    // (small nonzero remainders) are punished super-linearly.
    if post_residual > 0 {
        let sliver = (frac * 10.0).fract(); // within each decile of capacity
        score += 6.0 * sliver * sliver;
    }

    // Perfect fit: zero waste is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Integer division thresholds on post_residual ---
    // Classify residual into harmonic buckets: tiny / small / medium / large.
    let bucket = post_residual / 10; // 0..10 integer division class
    match bucket {
        0 => score += 8.0,          // residual < 10: nearly dead space
        1 => score += 3.0,          // 10..19: only fits smallest items
        2 => score -= 0.0,          // neutral
        3 | 4 => score -= 2.0,      // 30..49: good mid-range residual
        _ => score -= 4.0,          // >= 50: large residual, very reusable
    }

    // --- Modulo arithmetic coupling with next_item_size ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Lookahead: reward residuals that accommodate the next item.
        score -= 5.0;
        // Harmonic alignment: does post_residual mod next_item_size leave a clean fit?
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 4.0; // next item would tile the residual perfectly
        } else {
            score += (rem as f64) * 0.15; // penalize awkward leftover
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; residual becomes dead weight.
        score += 4.0 + (next_item_size as f64 - pr).min(20.0) * 0.2;
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits: strongly prefer using it
        // over opening a new bin (unless residual is hopeless).
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline but discourage when existing bins fit well.
        score = c * 0.5;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: opening a new bin is correct
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // pairing large items into fresh bins
        }
        return score;
    }

    // --- Tightness reward: prefer bins where item fills a large share ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio;

    // --- Stream progression modulation ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Late in the stream, waste matters more; early, keep bins flexible.
    score += (1.0 - progress) * (post_residual as f64) * 0.05;
    score -= progress * 3.0 * fill_ratio;

    // --- Mean residual context ---
    // Prefer bins below mean residual (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.03;

    // Small tie-breaker noise via deterministic coupling (no seeds).
    score += ((post_residual as f64 * 0.618).fract()) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable dead space (strict dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure from number of open bins: discourage scattering across many bins
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with below-average residual (fill emptier-of-space bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish, but allow it to win when existing
    // bins would leave bad dead space or fits are poor
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative anyway
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    if post_residual == 0 {
        score -= 460.0;
    }
    if post_residual > 0 && post_residual <= 4 {
        score -= 170.0;
    }

    if post_residual > 0 && post_residual < 13 && !next_consumes {
        score += 34.0 + (13 - post_residual) as f64 * 6.5;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 19.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 9.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 7.5 * (1.0 - progress);
        }
    }

    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 235.0;
        } else {
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 29.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 11.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 7.5 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 23.5;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 9.5 * (fit_ratio - 0.85) * 6.0;
    }

    score += open_bins_count as f64 * 1.2;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 11.5 * (1.0 - progress);
    }

    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 39.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 14.5 * (progress - 0.7) * 10.0 / 3.0;
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 13.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.5 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 8.5 * future_density;
        }
    }

    score += post_residual as f64 * 0.4 * progress;

    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 7.5 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 9.5;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 7.5 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 8.5 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.5 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 9.5 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 11.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 8.5 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 14.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that is too small to ever be useful.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 2.0; // nearly-full but wasted sliver
        } else {
            // 2-step lookahead: if next item fits into post_residual, big bonus.
            if next_item_size > 0 && next_item_size <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                score -= 25.0 + (slack / cap) * 20.0;
            } else if next_item_size > post_residual {
                // Next item won't chain here: mild penalty proportional to leftover.
                score += (pr / cap) * 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with residual below mean (concentrate fill in emptier bins).
    let residual = bin_residual as f64;
    score += (residual - mean_residual) * 0.3;

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count == 0 { 0.0 } else { open_bins_count as f64 };
        let poor_fit = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        let base = 30.0 + crowded * 2.0 + poor_fit;
        // Early in the stream, opening bins is cheap; later, discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual so small leftovers dominate.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, encourage consolidation (prefer bins with low residual).
    let open_f = open_bins_count as f64;
    score -= mean_residual * 0.05 * (open_f / (open_f + 5.0));

    // Time horizon: early in the stream, be more willing to spread out; late, consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.2;
    score -= post_residual as f64 * progress * 0.3;

    // New-bin candidate: only attractive when current fit is bad or no good alternative.
    if bin_residual == bin_capacity {
        let bad_fit = if bin_capacity >= item_size { (bin_capacity - item_size) as f64 } else { 0.0 };
        // Opening a new bin costs a base penalty; relax it late in the stream.
        let mut nb = 35.0 - 15.0 * progress;
        // If few bins fit the item, new bin is more acceptable.
        if fitting_bins_count <= 1 {
            nb -= 20.0;
        }
        // If the new bin leaves a very small residual (large item), it's efficient.
        nb -= bad_fit * 0.2;
        score += nb.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like
    score += 20.0 * poly * norm_pr * norm_pr;

    // Penalize small but nonzero post_residual (dead space), smoothly
    score -= 15.0 * (-norm_pr * 6.0).exp() * (1.0 - poly);

    // Reward tight fits more as stream progresses
    score -= 10.0 * poly * (item_size as f64 / cap);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - poly) + 10.0 * poly;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = pr - next_item_size as f64;
        score -= 12.0 * (-fit_gap / 30.0).exp();
    } else if next_item_size > 0 {
        score += 5.0 * poly;
    }

    // Slight preference for bins deviating from mean residual (consolidation)
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: neutral baseline with mild progress-dependent penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 460.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 170.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 36.0 + (12 - post_residual) as f64 * 6.5;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 16.0 + 0.45 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
        if next_item_size <= item_size && dead_ratio_of(item_size, bin_residual, bin_capacity) > 0.6 {
            score += 9.0 * (dead_ratio_of(item_size, bin_residual, bin_capacity) - 0.6) * (1.0 + progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 240.0;
        } else {
            score -= 36.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 14.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 13.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 13.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 23.5;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 23.0 + mean_residual * 0.35 + 17.0 * progress + 3.5 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 23.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 11.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 28.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 24.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 13.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 17.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 21.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 5.5 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 11.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.5 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

fn dead_ratio_of(item_size: u32, bin_residual: u32, bin_capacity: u32) -> f64 {
    (bin_residual.saturating_sub(item_size)) as f64 / bin_capacity.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as u32; // 0..3 harmonic classes: >75, >50, >25, <=25 percent free

    // Reward bins whose post residual lands in "usable" harmonic classes (>= 50% free),
    // penalize bins that leave tiny dead space (class 0: nearly full but wasted sliver).
    match class {
        3 => score -= 6.0,
        2 => score -= 3.0,
        1 => score += 2.0,
        _ => {
            // Dead space class: tiny residual. Penalize more as open bins grow.
            score += 4.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Integer-division harmony: does next_item_size divide cleanly into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let quot = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && quot >= 1 {
            // Perfect modular fit for the lookahead: strong reward.
            score -= 8.0 + 2.0 * quot as f64;
        } else if rem <= 10 {
            // Near-multiple fit: mild reward.
            score -= 3.0;
        } else {
            // Leaves awkward remainder: penalize proportional to leftover.
            score += rem as f64 * 0.15;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit here: bin becomes dead for the next step.
        score += post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer tighter fits (lower post residual dominates naturally).
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: attractive only when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (mean_residual - item_size as f64) / bin_capacity as f64 >= 0.25;
        if good_fit_exists {
            score += 12.0; // discourage opening a new bin when a decent fit exists
        } else {
            score -= 5.0; // prefer fresh bin over ruining a bin's harmonic class
        }
    }

    // Late-stream consolidation: as the stream ends, favor filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far below mean residual, it is a poor filler target.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
