}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (1..=15) are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here; this residual becomes dead space for lookahead.
        score += (post_residual as f64) * 0.8;
    }

    // New-bin candidate: only attractive when existing fit is poor (large post_residual
    // or many open bins). Baseline keeps it competitive but not dominant.
    if bin_residual == bin_capacity {
        score = 25.0 + mean_residual * 0.3 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // this bin becomes a perfect two-item bin -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover slack after the pair
            score -= 30.0;
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the remaining space: penalize dead space,
            // scaled by how close the next item is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: only the current fit matters; reward tight fits harder.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare against mean residual: placing into a bin with residual far
    // below the mean (a tight bin) is good; a very roomy bin should be
    // saved for larger future items.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Slightly discourage opening new bins when many bins are already open
    // and the item fits reasonably well in an existing one.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize slightly unless it's early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space (unusable slivers) more than moderate leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are large
    // or the fit into any open bin would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is better early (long horizon to fill them later)
        let early_bonus = 80.0 * (1.0 - progress);
        score -= early_bonus;
        // Penalize new bin when mean residual across open bins is generous
        score += 0.6 * mean_residual;
        // If many bins can fit the item, opening a new one is wasteful
        score += 8.0 * fitting_bins_count as f64;
        // Perfect-fit item into fresh bin is fine
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual well, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit;
    }
    // If next item would exactly fill the bin after this placement, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize placements that leave post residual too small for next item,
    // creating likely dead space
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference to fill bins with larger residual when many bins are open
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
