pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize dead space quadratically, weighted by progress
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead: reward bins whose post residual can hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (nxt / cap);
        } else {
            score += 15.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).max(0.0);

    // New-bin candidate: make it moderately attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.3 * progress) + 0.5 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
        // Two-item lookahead: residual that fits next item twice is very valuable.
        if post_residual >= next_item_size * 2 + 1 {
            score -= 6.0 * future_density;
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    // Exact residual match: placement that zeroes out the bin entirely.
    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space buckets
    let pr = post_residual;
    // Residuals <= 9 are essentially dead (min future item assumed small)
    if pr <= 9 {
        score -= 50.0; // tiny dead space is fine
    } else if pr <= 25 {
        score += 20.0; // awkward mid zone
    } else if pr <= 50 {
        score += 8.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair
    // nicely with typical item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 15.0;
    }
    // Residuals of 5 mod 10 are semi-usable
    if pr % 10 == 5 {
        score -= 5.0;
    }

    // Lookahead coupling: can next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // fraction of residual consumed by next item
            let frac = next_item_size as f64 / pr as f64;
            score -= 40.0 * frac;
            // integer-division threshold: residual can host next item at least once
            let q = pr / next_item_size.max(1);
            if q >= 2 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; prefer leaving a class-0 residual
            score += 5.0;
            if pr > 0 && (pr % 10 != 0) {
                score += 10.0;
            }
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default,
    // only chosen when open bins look bad
    if bin_residual == bin_capacity {
        score = 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins below mean residual (keeps residuals balanced)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
