    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight-fit bonus scaled by how well post_residual matches next item.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - diff / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: favor filling existing bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual below the current mean (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size);
        if bad_fit {
            score += 30.0; // discourage opening a bin that will trap waste
        } else {
            score += 15.0; // mild default reluctance to open new bins
        }
    }

    score
}

