    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 5.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 13.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64); // next item still fits, tighter is better
        } else {
            // next item cannot fit here: penalize dead space proportional to leftover
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets
    let diff = mean_residual - post_residual as f64;
    score -= 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers (< smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, prefer closing bins tightly (waste minimization)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // When many bins are open, favor consolidation into tighter bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately unattractive unless lookahead fails
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin pairs well with the lookahead chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 30.0 * (-post_residual as f64 / 10.0).exp();

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Dead space for the lookahead item: penalize proportionally.
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits into the leftover: reward.
            score -= 0.4 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual.max(0.0);
        score += 25.0 + 0.5 * open_bins_count as f64 + 0.3 * mean_fit;
        // Early in the stream, opening bins is cheaper; late, expensive.
        score += 40.0 * (1.0 - progress);
        // If no open bin fits well (high post_residual elsewhere), new-bin cost shrinks.
        if post_residual == 0 && bin_residual == bin_capacity {
            // empty bin candidate never gets perfect-fit bonus
            score += 50.0;
        }
    } else {
        // Prefer bins whose residual deviates below mean (consolidating space).
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty for wasting large residuals on small items.
    if item_size < 20 && bin_residual > 70 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: reward tight fits more strongly as stream progresses
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let coupling = fill * fill * (0.5 + progress);
    score -= 8.0 * coupling * (post_residual as f64).sqrt();

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + progress * 6.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + 3.0 * progress;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Smooth residual-mean alignment term
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Discard near-empty placements that waste the bin early
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    if post_residual == 0 {
        score -= 480.0;
