        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }
    score += post_residual as f64 * 0.4 * progress;
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }
    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }
    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify dead space into mod classes ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fills are gold: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Residual "harmonic classes": residuals that are multiples of small units
    // (5, 10, 20) are reusable by typical item sizes; odd fragments are dead space.
    let dead = (post_residual % 5) as f64;
    score += dead * 3.0;                       // penalize non-aligned fragments
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;                          // reward decade-aligned residuals
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;                          // extra reward for 20-aligned residuals
    }

    // Integer-division thresholds on post_residual: tiny residuals are near-dead.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;                          // unusable sliver
    }

    // --- Lookahead coupling with next_item_size (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item could fit here: reward keeping this residual compatible.
            let class_match = (post_residual % next_item_size.max(1)) as f64;
            score -= 20.0 - class_match * 0.5;
        } else {
            // Next item won't fit regardless: residual quality matters less,
            // slight penalty if we waste a large residual on a poor fit.
            let waste = (post_residual as f64) - (item_size as f64);
            if waste > 0.5 * cap {
                score += 25.0;
            }
        }
        // Harmonic pairing: if next item exactly matches residual, huge reward.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus pressure from open bins.
        score = 0.5 * cap + (open_bins_count as f64) * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If next item is huge, a fresh bin may be preferable.
        if next_item_size >= 60 && post_residual > 0 {
            score -= 20.0;
        }
        // Don't open a new bin when many bins already fit the item well.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
    }

    // --- Tightness reward: bins where the item fills most of the residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, MIN_USEFUL] is nearly unusable
    // for typical items (sizes >= 10, but interface allows 1..100 so assume >= 10 dead zone).
    const MIN_USEFUL: u32 = 10;
    if post_residual > 0 && post_residual < MIN_USEFUL {
        score += 60.0 + (MIN_USEFUL - post_residual) as f64 * 4.0;
    }

    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= MIN_USEFUL {
        score -= 10.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item: penalize proportionally.
        score += 0.35 * (post_residual as f64).min(next_item_size as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual > 30 {
            score += 0.4 * (post_residual - 30) as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many bins; encourage filling
    // existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is close to the item (tight fit relative to mean state).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // New-bin candidate handling: an empty bin gets a baseline score near capacity.
    // Only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            // Penalize opening new bins when open bins exist, scaled by open count.
            score += 15.0 + 2.5 * open_bins_count as f64;
            // But if all fits would leave large dead space, allow the new bin.
            if post_residual_of_best_unknown() {}
        }
    }

    // Mean-residual coupling: if the average open residual is large, gently favor
    // bins below the mean (help drain oversized residuals first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

#[inline(always)]
fn post_residual_of_best_unknown() {}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match bonus (post_residual == next_item_size)
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.35;
        }
        // Extra reward if the next item fits exactly after this placement chain
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize creating small unusable dead space (hard-to-fill slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: low post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below the mean (pack big items into emptier bins).
    score += (bin_residual as f64 - mean_residual) * 0.12;

    // Early in stream: encourage keeping bins balanced; late: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * tightness;

    // New empty bin candidate: penalize unless nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is excellent
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: post-residual that can host the next item is valuable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // chain-friendly: also nearly fitting next item well
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 15.0;
            }
        } else {
            // dead space relative to the next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving residuals in the awkward zone (small, hard-to-fill)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Time horizon: late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.8;

    // Global pressure: if mean residual is high, prefer reusing fuller bins
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // penalize opening a new bin generally; overcome only when current
        // placements would waste a lot
        score += 25.0 + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate slack less strongly
    let coupling = 1.0 + 0.8 * progress * (1.0 - progress);
    score *= coupling;

    // Penalize post-residual that is small but unusable (dead space) via smooth term
    let dead = (1.0 - norm_pr).powi(6);
    score += 12.0 * dead * (1.0 - progress);

    // Lookahead: reward bins whose post-residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference to reuse existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Exact-fill lookahead reward
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-exact fills: tiny leftover residuals are extremely valuable
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
            if post_residual >= next_item_size * 2 {
                score -= 30.0 * (1.0 - progress);
            }
            if post_residual >= next_item_size * 3 {
                score -= 14.0 * future_density;
            }
            if slack > 0.0 && slack < 4.0 {
                score -= 16.0;
            }
            if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
                score += 14.0;
            }
            if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
                score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
            }
        }
    }

    // Penalize stranded gaps the next item cannot use
    if post_residual > 0 && !next_consumes {
        let stranded = post_residual as f64 / cap;
        score += 14.0 * stranded * (1.2 - progress);
        if post_residual < 12 {
            score += 30.0 + (12 - post_residual) as f64 * 5.0;
        }
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < next_item_size && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 2.5;
            if post_residual < 30 {
                score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
            }
            if post_residual < item_size.min(80) {
                score += 18.0 + 0.5 * post_residual as f64;
            }
            if next_item_size - post_residual <= 6 {
                score += 10.0 * (1.0 - progress);
            }
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    // Tight-fit reward: item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 26.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 12.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Last-resort fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 24.0 + mean_residual * 0.3 + 16.0 * progress + 4.0 * fitting_bins_count as f64;
