        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if post_residual == item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    score += post_residual as f64 * 0.4 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic classes: post_residual divisible by small numbers tends to be
    // reusable by common item sizes (modular compatibility bonus)
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 15.0; // aligns with typical size grid
        } else if post_residual % 5 == 0 {
            score -= 7.0;
        }
        // penalize awkward dead space: small odd residuals below 10
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 4.0;
        }
    }

    // Next-item lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= (10 - gap) as f64 * 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(30) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.35;
        // but allow new bin if item is large and few bins fit it
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Prefer tighter bins: relative fill fraction
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 10.0 * (1.0 - fill);
    }

    // Mean residual context: if this bin's residual is far below mean, it's tight — good
    score -= (mean_residual - pr).max(-50.0).min(50.0) * 0.2;

    // Open bins count pressure
    score += open_bins_count as f64 * 0.05;

    score
}

