    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is wasted capacity
    } else if post_residual == 0 {
        score -= 45.0; // perfect fit is ideal
    }

    // Penalize mid-range dead space proportionally harder as it approaches unusability.
    if post_residual >= 10 {
        score += 0.35 * (10.0f64).min(post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are poor
        // for the item and the next item too.
        score += 25.0 + 12.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item nicely.
            if next_item_size + item_size <= bin_capacity {
                score -= 30.0;
            }
        }
        // Late in the stream, prefer filling existing bins.
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual matches the item closely (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score -= 8.0 * (1.0 - tightness / bin_capacity as f64);

        // Lookahead: if next item fits in the post-residual, reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // If next item would leave another tiny dead gap, penalize slightly.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score += 10.0;
        }

        // Prefer bins with residual close to the mean (balance the pool).
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
