        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits after this placement: mild reward proportional to slack.
        score -= 50.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit before this placement but not after:
        // penalize blocking the lookahead item.
        score += 120.0;
    }

    // Compare residual against mean residual of open bins: keeping residuals
    // balanced avoids fragmented dead space.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when good open bins exist, but allow it
    // early in the stream or when few bins are open (flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 + 150.0 * progress;
        if open_bins_count <= 2 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
