        if post_residual >= next_item_size {
            // residual can host the next item: reward proportionally
            score -= 0.35 * (post_residual as f64 / bin_capacity as f64).min(0.5);
        } else {
            // dead space: penalize unusable leftover
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large residual waste relative to mean residual of open bins
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheap late
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted as stream progresses
        score += 45.0 * (1.0 - 0.5 * t);
        // if item is large, a fresh bin is more attractive
        score -= 0.2 * item_size as f64;
    } else {
        // reward filling existing bins more aggressively as stream progresses
        score -= 10.0 * t * (bin_residual - post_residual) as f64 / bin_capacity as f64;
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let future_density = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let next_consumes = next_item_size > 0 && next_item_size <= post_residual;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 480.0;
    }
    // Near-perfect fit: leave only tiny slivers.
    if post_residual > 0 && post_residual <= 4 {
        score -= 190.0;
    }

    // Dead-space avoidance: small unusable gaps are heavily penalized,
    // unless the lookahead item exactly consumes the remaining space.
    if post_residual > 0 && post_residual < 12 && !next_consumes {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
        if post_residual < 30 {
            score += 20.0 * (1.0 - progress) * (30.0 - post_residual as f64) / 30.0;
        }
        if post_residual < item_size.min(80) {
            score += 18.0 + 0.5 * post_residual as f64;
        }
        if next_item_size - post_residual <= 6 {
            score += 10.0 * (1.0 - progress);
        }
        if fitting_bins_count > 1 && post_residual < item_size.min(50) {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Reward a bin that can also host the next item after this placement.
    if next_consumes {
        let slack = (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 260.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
        if post_residual >= next_item_size * 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if slack > 0.0 && slack < 4.0 {
            score -= 16.0;
        }
        if slack > 0.0 && slack < 12.0 && slack < item_size.min(15) as f64 {
            score += 14.0;
        }
        if post_residual >= next_item_size * 3 {
            score -= 14.0 * future_density;
        }
        if slack > 0.0 && slack < 20.0 && next_item_size > item_size {
            score -= 8.0 * (20.0 - slack) / 20.0 * (1.0 - progress);
        }
    }

    // Tight fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 24.0;
    if fit_ratio > 0.85 && bin_residual < bin_capacity {
        score -= 10.0 * (fit_ratio - 0.85) * 6.0;
    }

    // Open-bins pressure.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.35 + 18.0 * progress + 4.0 * fitting_bins_count as f64;
        if progress < 0.1 && item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 24.0;
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.5 {
            score -= 12.0 * (1.0 - progress);
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.9 && open_bins_count > 2 {
            score -= 30.0 * (1.0 - progress);
        }
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0 / 3.0;
        }
        if open_bins_count > 2 && progress > 0.25 && fitting_bins_count > 0 {
            score += 10.0 * (1.0 - progress);
        }
        if item_size >= bin_capacity * 3 / 4 && open_bins_count > 0 && progress < 0.5 {
            score += 26.0 * (1.0 - progress);
        }
        if next_item_size > 0 && open_bins_count > 0 && mean_residual >= (item_size + next_item_size) as f64 {
            score += 14.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 0 && (post_residual as f64) >= mean_residual * 0.8 {
            score -= 7.0 * (1.0 - progress);
        }
        if next_consumes && post_residual < next_item_size + 4 {
            score -= 18.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size && bin_residual - item_size - next_item_size <= 3 {
            score -= 22.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual < 6 {
            score += 6.0 * (6 - post_residual) as f64 * (1.0 + progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 8 {
            score -= 9.0 * future_density;
        }
    }

    // Late in the stream, leftover waste hurts more.
    score += post_residual as f64 * 0.4 * progress;

    // Squeeze into existing bins when mean residual is small.
    if open_bins_count > 2 && next_item_size > 0 && (mean_residual as u32 as f64) < next_item_size as f64 * 0.9 {
        score -= 24.0 * (1.0 - progress);
    }

    // Stranded-space penalties.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let stranded = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * stranded * (1.2 - progress);
        if post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) * future_density;
        }
        if post_residual < item_size && bin_residual > bin_capacity * 3 / 4 {
            score += 10.0;
        }
    }

    if post_residual > 0 {
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.6 && !next_consumes {
            score += 8.0 * (dead_ratio - 0.6) * (1.0 - progress);
        }
        if open_bins_count > 4 && post_residual >= 30 && post_residual % item_size.max(1) == 0 {
            score -= 9.0 * (1.0 - progress);
        }
        if dead_ratio > 0.5 && next_item_size > post_residual && open_bins_count > 2 {
            score += 6.0 * (dead_ratio - 0.5) * future_density;
        }
        if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size <= 2 {
            score -= 10.0 * future_density;
        }
        if dead_ratio > 0.55 && post_residual < item_size.min(40) {
            score += 14.0 * (dead_ratio - 0.55) * (1.0 - progress);
        }
        if dead_ratio > 0.45 && next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 8 {
            score -= 12.0 * (1.0 - progress) * future_density;
        }
        if dead_ratio > 0.6 && post_residual < next_item_size && next_item_size <= item_size {
            score += 9.0 * (dead_ratio - 0.6) * (1.0 + progress);
        }
    }

    if post_residual > 0 && post_residual == item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let x = r / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = r as f64;

    // Smooth polynomial coupling: penalize large residuals early, small residuals late
    let coupling = x * (1.0 - x) * (0.5 + t);
    score += 40.0 * coupling;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * t);

    // Penalize dead space: residuals too small for typical items
    let dead = (1.0 - x * 10.0).max(0.0);
    score += dead * dead * (15.0 + 20.0 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 8.0 * (1.0 - (nx / cap));
        } else {
            score += 5.0 * (nx - r) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * x * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that divide capacity well
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are exact divisors of capacity are highly reusable
        if bin_capacity % pr == 0 {
            score -= 18.0;
        }
        // Class by residual magnitude bands (harmonic fractions of capacity)
        let frac = pr as f64 / cap;
        if frac <= 0.1 {
            score += 25.0; // dead space penalty
        } else if frac <= 0.2 {
            score += 8.0;
        } else if frac <= 0.35 {
            score -= 6.0;
        } else if frac <= 0.5 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
        // Modulo-10 granularity: residuals on multiples of 10 pair with typical item sizes
        if pr % 10 == 0 {
            score -= 5.0;
        }
        // Perfect fit bonus
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 6.0;
            // harmonic pair: next item leaves a divisor residual
            let npr = pr - next_item_size;
            if npr > 0 && bin_capacity % npr == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual; penalize small residuals more
            score += 4.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild preference for tighter bins when many bins are open
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be more selective, keep bins balanced
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 40.0 * fill_ratio;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Lookahead penalty: post residual too small for next item -> dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    // New-bin candidate: bias by remaining stream length; early on prefer reusing bins,
    // late in stream a fresh empty bin is more acceptable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
    score
}
